INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '6f926972-8f2f-4f3b-9620-d007e85c774a', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'firma sahibi melih bey ziyaret edildi düzce kooperatifinden ve süperlit boru firmasına çalışmaktda 10 çekici 13 trailer bulunmakta melih bey şuan 4 aracının faal çalışmakta olduğunu belirtti lastik ihtiyacı var ama talebe göre alım yapacağını belirtti.', '{"il": "DÜZCE", "ilce": "MERKEZ"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'a67fccd5-3cb5-4f92-9710-a16b955d86cd', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'yiğitler inşaat firmasının beton tarafı ziyaret edildi firma ortaklarında ali yiğit ile görüşüldü lastik alımı yapacakları zaman bizdende teklif almalarıni ve satın almaya iletşim bilgisi bırakıldı firama prometon kullnmakta kaplamada yıldırımlar ile çalıyor', '{"il": "DÜZCE", "ilce": "MERKEZ"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '04e7b2b7-9485-4325-bd74-97b2c01a02b9', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'firma sahibi uğur çapar ziyaert edildi 385/55r22.5 sava talebi vardı stokta olmadığı için yks lastikten fiyat aldım bize maliytei 19.500 kdv dahil 22.750 kdv dahil tellif vermiştim uğurbey takodan alım yapmış 19.900 kdv dahilden 40 adet  firma bu ebattan sadece sava kullanmakta . ödene vadesi 60-90 güm içerisinde her hafta havale yapmakta', '{"il": "DÜZCE", "ilce": "KAYNAŞLI"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2bc51543-9c88-4a83-8a17-967c87ae8b23', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'ahmet fidan ile görüşüldü aralık ayında yapılan kumho marka lastiklerin takılış km leri alındı performasn takibi için firma 60 plkadan 30 plakya düştü ahmet bey araç satışı yapıp yerine alım yapmamış', '{"il": "BOLU", "ilce": "ÇAYDURT"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '98b26dc3-cc6c-471a-8d7d-978919f57bad', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'firma sahibi süleyman şahin ziyaret edildi 385/55R22.5 CHS5 continental fiyat teklifi verilmişti 33.000 kdv dahil vade 90 alımını sordum anadolu petrol den 10 adet alım yapmış 28.500 den firmada 100 adet plaka var aktif çalışn araç 25 olduğunu belirtti lastil alımı için vade sordu 90 gün dedim 150 -180 gün talep etti bende kendisine 60 yada 90 gün içersinde k kart taksitli yapa biliriz dedim dönüş yapacak', '{"il": "KARABÜK", "ilce": "MERKEZ"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e3cf1cb5-7780-4169-ae58-95b53bc2708b', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'orhan yılmaz ile görüşüldü yeni lastik markalarımız anlatıldı orhan bey binek araçlarda kumho kullandığını ve memnun olduğunu belirtti ticari araçlar için kumho fiyatları verildi satış yapıldı deposunu sayıp adet bilgisi verecek.', '{"il": "KARABÜK", "ilce": "MERKEZ"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '261357a0-0b55-4577-b014-f5cce77ec1a8', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'satın alma yusuf bey ziyaret dildi firma düz 50 adet alım yaptığını belirtti tbr lastkten prometon alımı yapmış mayıs sonunda tekrar alım olacak bizden de taklif alacağını belirtti', '{"il": "KARABÜK", "ilce": "MERKEZ"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1ab1b225-ff05-4cc3-8c25-77047e54a732', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'firmanın satın almasına ietişim bilgilerimiz bırakıldı lastik alımnı firmas sahibi yapmakta', '{"il": "KARABÜK", "ilce": "MERKEZ"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '459e3043-a7e7-42b7-a50a-113ec9ee5e15', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'firma ortaklarında yaşar bey ziyaret edidli saılun marka batı karadeniz marmara trakya ve ege bölgelerinde satış yapacaklarını öncelikle toptan noktaları ile hareket edeceklerini belirtti daha önce goodyear otr bölümünde çalışan volkan yumuşu işe aldıklarını ve izmitte ikamet edeceğini belirtti saılun ekibi ile ziyaretlere başlamışlar co ile  tbr de 4 firma olacaklarmış isim belitmedi karadeniz bölgesinde yulmazlar mış 385/55R22.5 sava için fiyat istedim 18.900 kdv dahil k kartı taksitli ödeme ile fiyat verdi saılın siparişleri bu hafta geleceğini belitti ziyaret ettikleri bir çok noktda saılun deyince bizi soruyorlarmış', '{"il": "KARABÜK", "ilce": "MERKEZ"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '8c4dbe70-7ebb-4c4f-a5b9-90af659854cc', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'firma sahibi cemal dereli ziyaret edildi vermiş olduğmuz fiyat teklifi soruldu cemal bey alım yaptığını belirtti kimden alım yaptığnı sordum şahin kardeşlerden alım yapmış sizin fiyatınızdan 1.400 ile 1.500 fark vardı bu yüzden dönüş yapmadım dedi firanın ödemesi havele oto semih ile aranızda 800 ile 100tl var dedi bizim iskontumuz nisan istesinden 41 isk idi şahin kardeşlerin 45 il 47 arasında memduh beye bilgi verildi şahin kardeşler memduh ile ilave isk için iletişime geçmemiş cemal bey bizden de 30 adet alım yaptı memduh bey 7-9 ilave isk desteği verdi', '{"il": "KARABÜK", "ilce": "YENİCE"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd9884584-5fb0-415f-aca9-30ae0f5551e4', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'firma sahibi murat sönmezin iletişim bilgileri alındı satın alma şeref bey  bizden fiyat teklifi almıyor prometin alımı yapıyor murat beyden randevu talep edildi.', '{"il": "KARABÜK", "ilce": "MERKEZ"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'ce290249-a64d-4ab8-92a4-60ad1db1d4cb', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-22'::date, NULL, 'metin bey ile görüşüldü toplu alım yapmadığını ihtiyaca göre alım yaptığını belirtti 315/80R22.5 R152PRO 20 adet alım yapmış albayraklar 21.500 tl fiyat vermiş kart ödemeli(38.5 isk) metin bey bayi olmayan başka yerden 20.500(41 isk) alım yaptığını belirtti firma mıchelın flo bayisi kaplamada bizle çalışacak', '{"il": "BARTIN", "ilce": "MERKEZ"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '8fd9dbf9-5f59-49b0-bcb3-ccc95178d732', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-22'::date, NULL, 'soner bey ziyaret edildi firma sanko çimentonun ocağını işletmekte 4 adet 26.5R25 maxam satışı yapıldı çimento fabrikasında işlerin çok uoğın olduğunu belirtti fabrika bakımdan dolayı 20 gün yatışa geçmiş', '{"il": "BARTIN", "ilce": "MERKEZ"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '8b1ab4be-de03-4a62-a51b-249550f385e3', '80fff50c-ffc7-4623-a382-a814263609c4', 'Hüseyin Bilgi', 'TICARI', 'TAMAMLANDI', '2026-04-22'::date, NULL, 'ilhan beye şirket bilgileri verildi satın alma portalına ekletildi bundan sonra bizdenden de fiyat alacak', '{"il": "BARTIN", "ilce": "MERKEZ"}'::jsonb, 'EXCEL_MIGRASYON', '80fff50c-ffc7-4623-a382-a814263609c4');
