INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'ad57acd6-da02-41dd-83c4-7cf89b55b448', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-01'::date, NULL, 'Genel ziyaret gerçekleştirildi. Kampanyalar özelinde bilgi aktarıldı. Gecikmiş 10.000₺ bakiye ile ilgili bilgi verildi.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bilgi": "Bizimle de çalışacağını fakat bu aralar Erenler Lastiğe destek verdiğini söyledi. Jant ve ön düzen ağırlıkta çalışmakta.", "bayilikler": ["Dunlop", "Lastikpark"], "raf_markalari": ["Dunlop", "Michelin", "Pirelli", "Kumho", "Çıkma"], "rakipler": ["Erenler"], "marka_listesi": ["Dunlop", "Kumho", "Michelin", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '61142a4f-0b15-47e0-a6af-575d0bf7aea3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-01'::date, NULL, 'Genel ziyaret gerçekleştirildi. Geçen hafta eski dotlu SSR satışı gerçekleştirmiştik. Bekir Usta''nın kardeşi olup aynı şekilde jant ağırlıkta çalışıyorlar.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Pasif Nokta", "bayilikler": ["Express Lastik"], "raf_markalari": ["Nexen"], "marka_listesi": ["Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '562b81cb-a105-46ea-ba9f-c24570ad6024', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-01'::date, NULL, 'Genel ziyaret gerçekleştirildi. Daha önceden de ziyaretlerim olmuştu fakat cari ve b2b açılışı gerçekleştirememiştik. Bu ziyaretimde cari ve b2b açılışını sağlayacağız.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Yeni Nokta", "bilgi": "Hankook bayisi aynı zamanda ön takım, jant hizmetleri de mevcut.", "bayilikler": ["Hankook"], "raf_markalari": ["Hankook", "Nexen", "Funtoma", "Delinte"], "rakipler": ["Erenler"], "marka_listesi": ["Delinte", "Funtoma", "Hankook", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
