INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0ce2df6f-88fa-4f75-91ed-e0ebc6559aff', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-01'::date, NULL, 'Genel ziyaret gerçekleştirildi.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bilgi": "Bu aralar Century uygun ve uzun vadede aldığını bundan sebep raf payının fazlalıkta olduğu görüldü.", "bayilikler": ["Lastik VS"], "raf_markalari": ["Sentury", "Delinte", "Lassa", "Saetta"], "marka_listesi": ["Delinte", "Lassa", "Saetta", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4f248859-d919-4005-8ce3-b993b3d2ec3d', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-01'::date, NULL, 'Genel ziyaret yapıldı. 4 adet eski dotlu 18 jant siparişi alındı.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Pasif Nokta", "bilgi": "Pasif bir nokta fakat b2b''yi takip etmekte.", "bayilikler": ["Pirelli"], "raf_markalari": ["Pirelli", "Kumho", "Delinte", "Continental", "Lassa", "Starmaxx", "Milestone", "Hankook"], "marka_listesi": ["Continental", "Delinte", "Hankook", "Kumho", "Lassa", "Milestone", "Pirelli", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '914713c0-9b0e-4f0d-8303-37a9028c20f1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-01'::date, NULL, 'Tahsilat için ziyaret gerçekleştirildi. Kısa süre içerisinde çek görüntüsünü ileteceğini ve muhtemelen 02.04.2026 en geç 03.04.2026 tarihinde yine geçen haftaki gibi 50.000₺ ödeme yapacağını söyledi.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Riskli Nokta", "raf_markalari": ["Çıkma"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '51ffe505-a039-439b-945f-6335297051b8', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-01'::date, NULL, 'Genel ziyaret yapıldı. Daha önceden Tümay Bey ile görüşme ve tanışma gerçekleştirilmişti. Bir sonraki ziyarette kampanyalı ürünlerden sipariş alacağız.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bilgi": "Aktif olarak michelin bayiliğini bıraktıklarını şu an sadece tabela durduğunu belirtti.", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Kumho", "Nexen"], "marka_listesi": ["Kumho", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3c62fae0-0e67-4159-857b-f904095c5c2f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-06'::date, NULL, 'Yeni oluşturduğumuz bir müşteri. Aktif ve risksiz şekilde çalışmaktayız. Genel ziyaret yapıldı. 4 adet sailun satışı gerçekleştirildi.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bilgi": "Ön takım, fren, yağ değişimi gibi işlemler de yapmakta.", "raf_markalari": ["Sailun", "hankook", "laufen", "lassa", "seatta"], "marka_listesi": ["Hankook", "Lassa", "Laufenn", "Sailun", "Seatta"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1e149c29-7298-4858-8a19-5e5ea4ae516e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-06'::date, NULL, 'Eski bir müşterimiz daha önceden Yıldıray Bilen ile ticari lastik çalışıyormuş. Önceki ziyaretlerimde b2b aktifleştirmiştim. Bugün de Yıldıray Bilen ile ziyaret gerçekleştirdik.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Lastik sektörüne yeni girmişler. Çok markalı çalışıyor.", "raf_markalari": ["Waterfall", "Kumho", "Goodyear"], "rakipler": ["YUKE", "Mutaf", "Tatko"], "marka_listesi": ["Goodyear", "Kumho", "Waterfall"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1f1e5d23-919d-4fa0-8cc4-d27d1daa9886', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-06'::date, NULL, 'Genel ziyaret gerçekleştirildi. 4 adet 19 Jant Conti siparişi alındı.', '{"bolge": "Kuruçeşme", "nokta_durumu": "Eski Nokta", "bilgi": "Daha çok pazaryerinden ürün tedariği sağlıyor. Düzenli ziyaretlerle yavaş ticaretimizi hareketlendirme tekrar başladık. Mart ve Nisan aylarında 48 adet ürün satışı gerçekleştirdik. Brisa markaları ile beraber hareketin daha da hızlanacağını düşünüyorum.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Continental"], "rakipler": ["YUKE", "Mutaf", "Tatko", "Pazaryerleri"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b90f9d6e-835f-4039-b4a6-c48f230878c6', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-06'::date, NULL, 'Genel ziyaret gerçekleştirildi. Cariyi ve b2b sistemini yeni kurmuş olup İlk satışımızı geçen hafta yapmıştık.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bilgi": "Bu haftaki raf yoğunluğu Riken üzerineydi. Kredi kartı çekimlerini tatkodan yaptığı için sürekli alacaklı olduğunu ve bu sebeple ticaritinin büyük bir kısmını onlarla yaptığını söyledi. Contide ilk tercihi biziz.", "bayilikler": ["Lastik Park"], "raf_markalari": ["Lassa", "Bridgestone", "Riken"], "rakipler": ["Tatko"], "marka_listesi": ["Bridgestone", "Lassa", "Riken"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '34e544b5-c22b-4cbb-943a-c8443d5468c6', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-06'::date, NULL, 'Genel ziyaret yapıldı. Şubat ayında eski dotlu ürünlerden ürün satışı gerçekleştirmiştik.', '{"bolge": "İzmit", "nokta_durumu": "Pasif Nokta", "bilgi": "Çayırova bölgesinde de kardeşinin bir lastik dükkanı mevcut. Risksiz bir şekilde çalışıyoruz. Keskin geçen hafta içerisinde ziyaret gerçekleştirmiş. Bizimle sorunsuz bir şekilde çalıştığını ifade etmiş.", "raf_markalari": ["Continental", "Barum", "Matador", "Çıkma"], "marka_listesi": ["Barum", "Continental", "Matador"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '42f53f2f-abb4-4e9d-9d5a-6e830c8ec11f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-06'::date, NULL, 'Genel ziyaret yapıldı. 4 adet roadx lastik satışı gerçekleşti.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Laufen"], "marka_listesi": ["Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
