INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0e640f01-dd18-492c-b659-4550c9d2390a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-06'::date, NULL, 'Genel ziyaret yapıldı. B2b açmıştık fakat hiç satış gerçekleştirememiştik. Bugün ilk satışımızı 8 adet 205/55R16 Conti ile gerçekleştirdik.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bilgi": "Çok markalı çalışıyor. Genel olarak servis hizmeti veriyor.", "bayilikler": ["Her Lastik"], "raf_markalari": ["Optimo", "Riken", "Petlas", "Hankook", "Kumho", "Waterfall"], "rakipler": ["Tatko", "YUKE"], "marka_listesi": ["Hankook", "Kumho", "Optimo", "Petlas", "Riken", "Waterfall"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '53125984-8cf8-42ac-8d1b-86bde19fc56f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-06'::date, NULL, 'Genel ziyaret yapıldı. Geçen hafta cari ve b2b açılışını gerçekleştirmiştik.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bilgi": "Ön takım ve rot üzerine daha çok işlem yapmakta. Şu sıralar kampanyalı goodyear ürünleri aldığını ifade etti.", "raf_markalari": ["Goodyear", "Pirelli", "Lassa", "Bridgestone", "Continental"], "rakipler": ["YUKE", "Haskar"], "marka_listesi": ["Bridgestone", "Continental", "Goodyear", "Lassa", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f0eca459-375c-411b-a4b6-7325c3b7abb5', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-06'::date, NULL, 'Genel ziyaret yapıldı, vadesi geçmiş bakiye ile ilgili görüşme gerçekleştirildi. Muhtemelen bu hafta tüm bakiyeyi kapatacağını ifade etti. Bakiye kapanışı sonrası sipariş yazılacak.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Akü satış ve hizmeti de mevcut. Ön düzen hizmeti de vermekte. Gecikmiş bakiyesini 31.000₺ ye kadar düşürdük.", "raf_markalari": ["Continental", "Matador"], "rakipler": ["YUKE", "Mutaf"], "marka_listesi": ["Continental", "Matador"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'a0fdf9d4-482b-4ba5-8f12-d60d4ce2a334', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-06'::date, NULL, 'Genel ziyaret yapıldı. Yavaş yavaş bu notkada da hareket sağlamaya başladık. 4 adet 205/55R16 Conti siparişi aldık.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Ön düzen hizmeti de vermekte.", "bayilikler": ["Lastik Park"], "raf_markalari": ["Lassa", "Bridgestone", "Seatta", "Continental"], "rakipler": ["YUKE", "Tatko"], "marka_listesi": ["Bridgestone", "Continental", "Lassa", "Seatta"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c494f542-1d55-4508-b09f-2d67609b80b9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-06'::date, NULL, 'Genel ziyaret yapıldı. Vadesi geçmiş bakiye ile ilgili görüşüldü. Ödemelerinin bu hafta geleceğini ifade etti. Vadesi geçmiş 60.000₺ bakiye kapatılacak.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Çok markalı çalışan,  konum ve mağaza olarak güzel bir nokta. Ödemeleri neredeyse düzene girdi. Bakiyeyi 180.000₺''den 89.000₺''ye kadar düşürdük. Yakın tarihte yaklaşık 1.000.000₺ civarında bir tutar ile dolandırılmış bu sebeple aksaklıklar yaşadığını ifade etti. Ödeme düzeni sonrası aktif şekilde çalışacağımızı düşünüyorum.", "bayilikler": ["Hankook"], "raf_markalari": ["Continental", "Michelin", "Hankook"], "rakipler": ["YUKE", "Mutaf", "Haskar", "Keskin", "Ayko"], "marka_listesi": ["Continental", "Hankook", "Michelin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e4a0b1cd-a4e8-4f35-a9e3-ab6fee410746', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-07'::date, NULL, 'Genel ziyaret yapıldı 2.000₺ gibi bir rakam gecikmedeydi. Gecikmiş bakiye tahsilatı yapıldı.', '{"bolge": "Derince-Körfez", "nokta_durumu": "Aktif Müşteri", "bilgi": "Jant satışı da mevcut. Derincede iç tarafta bir nokta. 4-8 çalışıyoruz. Sailun alımı da yapıyor.", "raf_markalari": ["Goodyear", "Sailun", "Nexen", "Lassa", "Hankook"], "marka_listesi": ["Goodyear", "Hankook", "Lassa", "Nexen", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2e24a75d-d9b1-434f-977e-788e580e1378', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-07'::date, NULL, 'Genel ziyaret yapıldı. Yeni oluşturduğumuz bir nokta. 8 adet lastik satışı gerçekleştirmiştik.', '{"bolge": "Derince-Körfez", "nokta_durumu": "Yeni Nokta", "bilgi": "Ön takım ve ön düzen işlemleri de yapmakta.", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas", "Lassa"], "marka_listesi": ["Lassa", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
