INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '790106e4-d8dc-45b8-baf4-daec192e7678', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-07'::date, NULL, 'Genel ziyaret yapıldı. Aktif olarak çalışmaktayız.17 ve 18 jant olmak üzere toplam 8 adet Conti siparişi alındı.', '{"bolge": "Derince-Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "Çok markalı çalışmakta.. Ekspertiz hizmeti de veriyor. Limana yakın ve güzel bir nokta. Aktif ziyaretlerle alım gerçekleştiriyor. Premium bir nokta", "bayilikler": ["Lastikpark"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
