INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b20ace7e-4e75-45cb-8d22-d0fdd6f5af17', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-07'::date, NULL, 'Genel ziyaret yapıldı. Bu hafta içerisinde bakiyeyi kapatıp tekrar sipariş yazılacak. Herhangi bir gecikmiş bakiyesi yok düzenli çalışıyoruz.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Sorunsuz şekilde çalışmaya devam ediyoruz. Her zaman ilk tercihi biziz.", "bayilikler": ["Continental"], "raf_markalari": ["Continental", "Matador"], "rakipler": ["USPA", "Keskin", "Mutaflar"], "marka_listesi": ["Continental", "Matador"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b0a6ea3c-4f34-4dfc-ab59-6360eea305c2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-07'::date, NULL, 'Genel ziyaret yapıldı. Geçmişte çalışılmış fakat 2025''ten beri hiç çalışamamışız. Düzenli ziyaretler ile tekrar kazanmaya çalışıyorum. B2b aktifleştirilmesini de sağlamıştık.', '{"bolge": "Başiskele", "nokta_durumu": "Pasif Nokta", "bilgi": "2 adet akü garanti sorunu yaşanmış bu sebeple ticaretimiz de durmuş.", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas"], "rakipler": ["YUKE"], "marka_listesi": ["Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
