INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '888e742a-dcf1-4fb9-b7bd-c67c681198d3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-08'::date, NULL, 'Genel ziyaret yapıldı, Gökay Bey yerinde olmadığı için görüşme gerçekleştirilemedi.', '{"bolge": "Karamürsel-Gölcük", "nokta_durumu": "Eski Nokta", "bilgi": "Eskiden çalıştığımız lastiğim noktamız.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa"], "marka_listesi": ["Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
