INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '62e72edc-5866-475d-835b-e020d2c5f523', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-08'::date, NULL, 'Genel ziyaret gerçekleştirildi. Neredeyse hiç çalışmadığımız bir noktaydı. Aktif ziyaretler ve B2b etkinleştirilmesi ile beraber bu hafta 4 adet conti satışı gerçekleştirmiştik.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bilgi": "Jant satışı da mevcut. Civardaki tüm lastikçilerle dirsek temasında.", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas"], "marka_listesi": ["Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c5e29a5c-91b6-483d-9358-4d551a4d7c40', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-08'::date, NULL, 'Genel ziyaret gerçekleştirildi. Yeni oluşturduğumuz bir nokta. Geçen hafta 6 adetlik conti satışı gerçekleştirmiştik.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bilgi": "E-5 kenarında rot hizmeti de veren bir nokta. Çok markalı satış var. Conti özelinde tedarikte sorun yaşadığını belirtmişlerdi. Aktif ziyaretler sağlamaktayım. ISB''ye çok yakın bir nokta.", "bayilikler": ["LastikJantAVM"], "raf_markalari": ["Lassa", "Kormoran", "Hankook"], "rakipler": ["Keskin", "Uspa"], "marka_listesi": ["Hankook", "Kormoran", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3beece18-2947-4eb5-8580-5b3ee5ac8016', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret yapıldı. Sailun özelinde bilgi verildi ve stok, fiyat listesi paylaşıldı. 13-14 jantlarda sipariş alacağız.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bilgi": "Mevcutta Hüseyin Bilgi ile ticari çalışıyor.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Laufen", "Pirelli"], "marka_listesi": ["Lassa", "Laufenn", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd0a74274-6204-48e6-869a-264d77812995', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Gecikmiş bakiye ile ilgili ziyaret sağlandı Ömür bey yerinde olmadığı için görüşme sağlanamadı. Bakiyenin tahsili için finans ve ben aramalar sağlıyoruz. Ufak ufak tahsilatlara devam ediyoruz.', '{"bolge": "Düzce", "nokta_durumu": "Riskli Nokta", "bilgi": "Riskli nokta. Bakiye tahsil edildikten sonra risksiz şekilde devam edilmeli.", "raf_markalari": ["Delinte", "Laufen"], "marka_listesi": ["Delinte", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2cd2a570-5803-41e0-afe2-32ae975f6acb', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret yapıldı. Daha önceden ziyaret etmiştim. Sezgin Bey ile tanışma sağlandı.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Tüketicide ihtiyacının olmadığını daha çok ticari hizmet verdiğini belirti. Hüseyin Bilgi''ye bilgi verildi.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4a4b2b54-82c0-4d5e-bd06-6cb0f192b4ff', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret yapıldı, Sailun özelinde bilgi verildi ve liste paylaşıldı. Ayrıca bazı ebatlarda teklif istedi teklif hazırlanıp verildi. Sailun siparişlerleri ile ilgili bilgi dönecek bizlere.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bilgi": "Civardaki küçük lastikçiler ile beraber toplu sipariş yazdırıyor. Kış lastiklerinde öyle yapmışlar.", "raf_markalari": ["Petlas", "Pirelli", "Dayton", "Starmaxx"], "marka_listesi": ["Dayton", "Petlas", "Pirelli", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
