INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b8a0d908-8e54-48e1-bf28-48846ff981ab', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret yapıldı, daha önceden b2b açılışı sağlamıştık. Yakın tarihte Conti ve matador siparişi verecekler. Sailun özelinde bilgilendirme yapıldı. Sailun ile ilgili de dönüş yapacaklar.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Lastiğim noktası ve ticari lastik de yapmakta. Aynı zamanda yedek parça servis hizmeti de vermekte", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Goodyear", "Dayton", "Bridgestone", "Prometeon"], "marka_listesi": ["Bridgestone", "Dayton", "Goodyear", "Lassa", "Prometeon"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
