INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'a5035f79-b37b-45ab-b532-b189dfa4b5e9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret yapıldı, daha önceden b2b açılışı sağlamıştık.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Performans, modifiye, yay gibi hizmetler veriyor.", "raf_markalari": ["Michelin", "petlas", "nexen", "lassa"], "marka_listesi": ["Lassa", "Michelin", "Nexen", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '7444b468-38cd-465a-8a4d-8136710e78f3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret yapıldı, daha önceden ziyaret sağlamıştık. Henüz vergi açılışı gerçekleşmemiş. Vergi açılışı gerçekleştirdikten sonra cari ve b2b açılışını sağlayacağız. Daha önceki görüşmemizde sailun özelinde de görüşmüştük.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Sailun ile ilgili talepleri olacak, Ucuz ve çıkma daha çok satıyor.", "raf_markalari": ["Lassa", "Dayton", "Petlas"], "marka_listesi": ["Dayton", "Lassa", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'fa4c6130-34e9-4899-b16c-321f2e37b14e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret yapıldı. Daha önce cari ve b2b açılışını yapıp ilk Conti satışımızı gerçekleştirmiştik. Sevkiyat hızımızdan dolayı Conti''de ilk tercihin artık KRB olduğunu belirtti.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Ticari lastik satışı da yapıyor. Ara ara taleplerimiz oluyor diye belirtti. Hüseyin Bilgi''ye bilgi verildi.", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Kormoran", "Nexen"], "rakipler": ["Uspa", "Keskin", "YUKE", "Bar Oto"], "marka_listesi": ["Kormoran", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '744153f9-e23f-4807-9209-40ce1086c642', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret yapıldı, kampanyalardan bilgi verildi. Sailun özelinden de bilgi aktarıldı. 205/55r16 Conti siparişi  ile ilgili dönüş yapacak bizlere.', '{"bolge": "Düzce", "nokta_durumu": "Pasif Nokta", "bilgi": "Jant satışı ve rot hizmeti de vermekte.", "bayilikler": ["Dunlop"], "raf_markalari": ["Lassa", "Falken", "Dunlop", "Bridgestone", "starmaxx", "michelin"], "marka_listesi": ["Bridgestone", "Dunlop", "Falken", "Lassa", "Michelin", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2c91432d-16ae-4646-a235-ebddf8753e49', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret ve tanışma gerçekleşti. Cari ve b2b açılışı yapılacak.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Müşterilerin özellikle Conti taleplerinin olduğunu KDR çok pahalı kaldığı için tedarikte sorun yaşadığını ve USPA''dan baktığını belirtti.", "bayilikler": ["Hankook"], "raf_markalari": ["Hankook", "Laufenn"], "rakipler": ["Uspa", "YUKE", "Bar Oto"], "marka_listesi": ["Hankook", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3bed035a-fc69-488d-b2c2-94f1735e12b5', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret gerçekleştirildi. Geçen ziyaretmide b2b aktifleştirmesini sağlamıştık.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bilgi": "Sadece lastikpark markaları mevcut. Başka marka alımı pek yapmıyor.", "bayilikler": ["Brisa"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd83fe887-d3a4-4304-a321-a539e85f8e81', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret gerçekleştirilldi.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastik Park"], "raf_markalari": ["Sentury"], "marka_listesi": ["Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b0bbc328-269c-403e-b114-bcfb185a0f9a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret gerçekleştirildi. Sailun C grubu 235/65r16 ve 225/75r16 teklif verildi. Karayolları araçları için 80 adetlik bir alım olacakmış. Aynı zamanda sailun listesini de paylaşmıştık. Onları da inceleyip bilgi dönüşü yapacaklar.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bilgi": "Hüseyin Bilgi müşterisi mevcutta çalışmaktayız. Brisa grubu alımlarını rota lastikten yapıyor.", "raf_markalari": ["Lassa"], "rakipler": ["Rota Lastik"], "marka_listesi": ["Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '51a29b47-a162-4e53-b7a3-e5109f7018c1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret ve tanışma gerçekleşti. Cari ve b2b açılışı yapılacak.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Kumho bayisi, güzel ve iş potansiyeli olan bir nokta. Mutaf ile iyi çalışmaktaymış.", "bayilikler": ["Kumho"], "raf_markalari": ["Kumho", "nexen", "goodyear"], "rakipler": ["Mutaf"], "marka_listesi": ["Goodyear", "Kumho", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'a689caed-850c-4b58-81c4-5e714e9b9b4a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-09'::date, NULL, 'Genel ziyaret ve tanışma gerçekleşti. B2b açılışı yapılacak. Sailun ile ilgili detaylı bilgi verildi, liste paylaşıldı. Bize dönüş yapacak.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bilgi": "Eren Hacıoğlu telefonla destek oluyormuş. Cariyi toptana ve bana çevirip düzenli rut planına aldık. Kış lastiklerinde sailun vermişiz daha önce. Alacaklı bizden şu anda. KK çekimlerini yapıyor. Sailun özelinde çalışma yapıp bize dönecek.", "raf_markalari": ["Petlas", "Goodyear", "Starmaxx", "Sailun"], "rakipler": ["AAKale"], "marka_listesi": ["Goodyear", "Petlas", "Sailun", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '85a8a360-5acf-4caf-881c-0ee3bc2dad6a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-13'::date, NULL, 'Genel ziyaret yapıldı. LSR''ler ile ilgili görüşüldü. Ayrıca 235/65R16 Conti siparişi verilecek. Dönüş beklemekteyiz.', '{"bolge": "Gebze", "nokta_durumu": "Eski Nokta", "bilgi": "Tekrar haretkelendirme sağladık. LSR''ler ile ilgili +3 iskonto ile ilgili bilgi verildi. Bundan sonra mutlaka fiyat alacaklar bizden.", "bayilikler": ["LastikVS"], "raf_markalari": ["Kumho", "Goodyear", "Lassa", "Laufenn", "Hankook", "Continental"], "rakipler": ["Ayko", "YUKE", "Mutaf", "Keskin", "Mollaoğlu", "Lastikpark"], "marka_listesi": ["Continental", "Goodyear", "Hankook", "Kumho", "Lassa", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bfd6fca3-b120-4a14-9b61-27710a0f16b2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-13'::date, NULL, 'Genel ziyaret yapıldı, Sailun özelinde bilgi verildi ve liste paylaşıldı.', '{"bolge": "Gebze", "nokta_durumu": "Eski Nokta", "bayilikler": ["Her Lastik"], "raf_markalari": ["Uniroyal", "Michelin", "Continental"], "marka_listesi": ["Continental", "Michelin", "Uniroyal"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1fa9033d-6707-431b-9a97-ca91a4b88544', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-13'::date, NULL, 'Genel ziyaret yapıldı. Sailun özelinde bilgi verildi. Elinde çok fazla alt marka olduğu için sailun ile ilgili bir alım düşünmüyor.', '{"bolge": "Derince-Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "Continentalda iyi çalışmaktayız. İlk tercih her zaman biziz.", "bayilikler": ["LastikPark"], "raf_markalari": ["Lassa", "Bridgestone", "Hankook", "Continental", "Matador", "Starmaxx", "Laufenn"], "rakipler": ["Lastikpark"], "marka_listesi": ["Bridgestone", "Continental", "Hankook", "Lassa", "Laufenn", "Matador", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '790106e4-d8dc-45b8-baf4-daec192e7678', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-13'::date, NULL, 'Genel ziyaret yapıldı. Cüneyt Bey yerinde olmadığı için görüşme gerçekleştirilemedi.', '{"bolge": "Derince-Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "Continental ile aktif olarak çalışmaktayız. İlk tercih her zaman biziz.", "bayilikler": ["Lastikpark"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b90f9d6e-835f-4039-b4a6-c48f230878c6', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-13'::date, NULL, 'Genel ziyaret yapıldı. Yeni oluşturduğumuz bir nokta. Gölcük şubelerine de lastik sipariş girilmeye başladı. Conti ile çalışmaktayız.', '{"bolge": "Kuruçeşme", "nokta_durumu": "Yeni Nokta", "bilgi": "3 şubesi olan bir nokta. Continentalda ilk tercih biz olarak çalışıyoruz.", "bayilikler": ["Lastikpark"], "raf_markalari": ["Riken", "Sentury", "Lassa", "Hankook", "Goodyear", "Dayton"], "rakipler": ["Tatko"], "marka_listesi": ["Dayton", "Goodyear", "Hankook", "Lassa", "Riken", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2e24a75d-d9b1-434f-977e-788e580e1378', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-13'::date, NULL, 'Genel ziyaret yapıldı. Yeni oluşturduğumuz bir nokta. Satış gerçekleştiriyoruz. B2b aktif takip ediyor. Şu an bizden alacaklı şekilde gidiyor.', '{"bolge": "Derince-Körfez", "nokta_durumu": "Yeni Nokta", "bilgi": "Ön düzen ve ön takım hizmetleri de vermekte.", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas"], "marka_listesi": ["Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1f1e5d23-919d-4fa0-8cc4-d27d1daa9886', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-13'::date, NULL, 'Genel ziyaret yapıldı. LSR ile ilgili de görüşülecekti fakat Mehmet Bey yerinde olmadığı için görüşülemedi.', '{"bolge": "Kuruçeşme", "nokta_durumu": "Eski Nokta", "bilgi": "Tekrar haraketlenme sağladık. Şu an sorunsuz şekilde çalışmaktayız.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Continental"], "rakipler": ["YUKE", "Mutaf", "Tatko", "Pazaryerleri"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e4a0b1cd-a4e8-4f35-a9e3-ab6fee410746', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-13'::date, NULL, 'Genel ziyaret yapıldı. Sailun özelinde bilgi verildi. 6 adet 175/70R13 Sailun satışı gerçekleştirdik.', '{"bolge": "Derince-Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "Jant satışı da mevcut. Derincede iç tarafta bir nokta. 4-8 çalışıyoruz. Genelde sailun çalışmaktayız.", "raf_markalari": ["Goodyear", "Sailun", "Nexen", "Lassa", "Hankook"], "marka_listesi": ["Goodyear", "Hankook", "Lassa", "Nexen", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '373ecc09-9880-4a43-8571-d6087784537f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-13'::date, NULL, 'Genel ziyaret yapıldı. Pasif nokta haline gelmişti. Düzenli ziyaretlerle satışa tekrar başladık. 16.000 gecikmiş bakiyesi var. Muhtemelen yarın kart çekilecek.', '{"bolge": "Derince-Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["Hankook"], "raf_markalari": ["Hankook", "Laufen"], "marka_listesi": ["Hankook", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '34e544b5-c22b-4cbb-943a-c8443d5468c6', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-13'::date, NULL, 'Genel ziyaret gerçekleştirildi. Eski dotlu ürün satışları yapmıştık. Sailun özelinde de bilgi verildi.', '{"bolge": "Kuruçeşme", "nokta_durumu": "Pasif Nokta", "raf_markalari": ["Continental", "Barum", "Matador", "Çıkma"], "marka_listesi": ["Barum", "Continental", "Matador"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c494f542-1d55-4508-b09f-2d67609b80b9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-13'::date, NULL, 'Genel ziyaret gerçekleştirildi. Gecikmiş bakiyesinden 26.000₺ tahsilatta gerçekleştirdik.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Gecikmiş bakiyesi bittikten sonra aktif ve düzenli bir şekilde çalışacağımız bir nokta. Müşterimiz de Lassa Bridgestone ile beraber sattığımız markalarda ilk tercihin biz olacağını belirtti.", "bayilikler": ["Hankook"], "raf_markalari": ["Lassa", "Petlas", "michelin", "dayton", "bridgestone", "laufenn", "continental"], "rakipler": ["YUKE", "Mollaoğlu", "Keskin", "Çakıroğlu"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa", "Laufenn", "Michelin", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '98575284-8d03-4b7b-8537-bb0d11f20cac', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-14'::date, NULL, 'Genel ziyaret yapıldı.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Lassa, Bridgestone alımlarını Sevtar''dan daha önceden yapmış.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "rakipler": ["YUKE", "Sevtar"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
