INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0e640f01-dd18-492c-b659-4550c9d2390a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-14'::date, NULL, 'Genel ziyaret yapıldı, geçen hafta 8 adet conti 205/55R16 ile ilk satışımızı gerçekleştirmiştik. Yine  de 6 adet daha conti satışı gerçekleştirdik.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bilgi": "Brisa grubundan da bundan sonra ilk bizi arayarak çalışacağını söyledi. Çok markalı çalışmakta.", "bayilikler": ["Her Lastik"], "raf_markalari": ["Optimo", "Riken", "Petlas", "Hankook", "Kumho", "Waterfall", "Sentury", "Unique"], "rakipler": ["Tatko", "YUKE"], "marka_listesi": ["Hankook", "Kumho", "Optimo", "Petlas", "Riken", "Sentury", "Unique", "Waterfall"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
