INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c0536bdc-737e-4a79-a1bb-464ad91dfd37', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-15'::date, NULL, 'Genel ziyaret ve Fevzi Bey ile tanışma gerçekleştirildi. Kartvizit bırakıldı.', '{"bolge": "Kaynarca", "nokta_durumu": "Yeni Nokta", "bilgi": "Brisa grubunda Bayraktar ile çalışmakta. Contideki alımlarını da Erenler''den yapmaktaymış.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "rakipler": ["Albayrak"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '571df243-f880-4dd2-ad6b-3acbef2726b8', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-15'::date, NULL, 'Genel ziyaret yapıldı. Daha önce sailun özelinde de bilgilendirme sağlamıştık. Düzenli ve aktif çalıştığımız bir nokta. Gecikmiş dahil tüm bakiyesini kapattık.', '{"bolge": "Karasu", "nokta_durumu": "Eski Nokta", "bilgi": "Kış lastiğinde sailun alımı yapmış daha önce. Aktif olarak çalışıyoruz. Nexen ağırlıkta çalışıyor.", "bayilikler": ["Lastikpark"], "raf_markalari": ["Nexen", "Hankook", "Continental", "Starmaxx", "Milestone", "Petlas", "Sailun", "Michelin", "Laufenn", "Riken", "Unique"], "rakipler": ["YUKE", "Çakıroğlu", "Tatko"], "marka_listesi": ["Continental", "Hankook", "Laufenn", "Michelin", "Milestone", "Nexen", "Petlas", "Riken", "Sailun", "Starmaxx", "Unique"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'a3f243c5-f57b-468c-a46d-dec783618133', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-15'::date, NULL, 'Genel ziyaret gerçekleştirildi. Önceki ziyaretlerimde cari ve b2b açmıştık. 60 Gün vadeli Sailun, Matador, Conti satışı gerçekleştirmişik. Bugün de kartlarını çekip 8 adet satış gerçekleştirdik.', '{"bolge": "Karasu", "nokta_durumu": "Yeni Nokta", "bilgi": "Dikkatli izlediğim bir nokta.", "bayilikler": ["Lastik Evi"], "raf_markalari": ["Continental", "Matador", "Sailun", "Dayton", "Laufenn"], "marka_listesi": ["Continental", "Dayton", "Laufenn", "Matador", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '45fd034d-bad4-4ba8-8039-702e59dafd50', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-15'::date, NULL, 'Genel ziyaret gerçekleştirildi. Yeni oluşturduğumuz bir nokta. 12 adet Conti satışı gerçekleştimiştik. Havale ile çalışıyoruz.', '{"bolge": "Karasu", "nokta_durumu": "Yeni Nokta", "bilgi": "Yedek par.a ve yağ işi de yapmakta. Ziraii lastik satışları da mevcut.", "bayilikler": ["Goodyear"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
