INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0ce2df6f-88fa-4f75-91ed-e0ebc6559aff', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-16'::date, NULL, 'Genel ziyaret gerçekleştirildi. Bu hafta içerisinde 4 adet 7.50-16 Forklift lastiği satışı gerçekleştirdik.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bilgi": "Century ve Unique markalarında uygun ve uzun vadede ürün aldığını belirtti. 17.5 grubunda çalışacağız.", "bayilikler": ["Lastik VS"], "raf_markalari": ["Sentury", "Delinte", "Lassa", "Saetta", "Nexen"], "marka_listesi": ["Delinte", "Lassa", "Nexen", "Saetta", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '562b81cb-a105-46ea-ba9f-c24570ad6024', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-16'::date, NULL, 'Genel ziyaret gerçekleştirildi. Bir önceki ziyarette cari ve b2b açılışı gerçekleştirmiştik. Conti taleplerinde mutlaka baktığını belirtti.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Yeni Nokta", "bilgi": "Hankook bayisi aynı zamanda ön takım, jant hizmetleri de mevcut.", "bayilikler": ["Hankook"], "raf_markalari": ["Hankook", "Nexen", "Funtoma", "Delinte"], "rakipler": ["Erenler"], "marka_listesi": ["Delinte", "Funtoma", "Hankook", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
