INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'dba694ff-7450-4fc6-8fbd-d06a8f974342', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-16'::date, NULL, 'Genel ziyaret gerçekleştirildi. Kartvizit bırakıldı. İhtiyaç durumunda arama yapacaklar. Cari ve b2b açılışı yapılamadı.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastikpark"], "raf_markalari": ["Petlas", "Delinte", "Starmaxx", "Sentury"], "marka_listesi": ["Delinte", "Petlas", "Sentury", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bec9387a-a196-44d7-bf7d-bf57f25666ab', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-16'::date, NULL, 'Genel ziyaret gerçekleştirildi. Yetkili olmadığı için görüşme gerçekleştirilemedi. Bir sonraki rutta tekrar ziyaret gerçekleştirilecek.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Continental"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e28d5a69-590f-4188-a2d9-8ab053dce0b6', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-16'::date, NULL, 'Genel ziyaret gerçekleştirildi. İhtiyaç durumunda arama yapılacak.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bilgi": "Jant satışı da yapmakta olup, Ön düzen hizmeti de vermekte.", "bayilikler": ["Her Lastik"], "raf_markalari": ["Unique", "Sentury", "Lassa", "Laufenn", "Hankook", "Nexen"], "marka_listesi": ["Hankook", "Lassa", "Laufenn", "Nexen", "Sentury", "Unique"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '85a8a360-5acf-4caf-881c-0ee3bc2dad6a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret gerçekleştirildi. Gökmen Bey ile görüşme sağlandı. Gürkan Bey rahatsız olduğu için iş yerinde yoktu. Gürkan Bey ile 235/65R16C Conti için dönüş beklemekteyiz.', '{"bolge": "Gebze", "nokta_durumu": "Eski Nokta", "bilgi": "Tekrar haretkelendirme sağladığımız bir nokta oldu. LSR''ler ile ilgili +3 iskonto ile ilgili bilgi verildi.", "bayilikler": ["LastikVS"], "raf_markalari": ["Kumho", "Goodyear", "Lassa", "Laufenn", "Hankook", "Continental"], "rakipler": ["Ayko", "YUKE", "Mutaf", "Keskin", "Mollaoğlu", "Lastikpark"], "marka_listesi": ["Continental", "Goodyear", "Hankook", "Kumho", "Lassa", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bfd6fca3-b120-4a14-9b61-27710a0f16b2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret yapıldı. Geçtiğimiz haftalarda gecikmiş bakiyesinin tamamını kapatmıştık.', '{"bolge": "Gebze", "nokta_durumu": "Eski Nokta", "bilgi": "Şu an sökme takma aşırı yoğun olduğu için yeni ürün siparişi ile ilgili bir çalışma olmamış. Dönüş sağlayacak tarafımıza", "bayilikler": ["Her Lastik"], "raf_markalari": ["Uniroyal", "Michelin", "Continental"], "marka_listesi": ["Continental", "Michelin", "Uniroyal"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4cd8a0b5-3613-402e-977f-da00582e5bea', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret yapıldı. Ahmet Bey ile görüşüldü.', '{"bolge": "Yarımca", "nokta_durumu": "Yeni Nokta", "bilgi": "Neredeyse her hafta düzenli olarak ziyaret etmekteyim. Henüz cari ve b2b açılışı sağlayamadık.", "raf_markalari": ["Petlas", "Falken"], "rakipler": ["YUKE"], "marka_listesi": ["Falken", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4b5ce588-1064-4e28-901d-4c01ac93b3aa', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret yapıldı. Ahmet Bey ile görüşme sağlandı. Daha önceden de ziyaretler gerçekleştirmiştim. Henüz cari ve b2b açılını yapamadık.', '{"bolge": "Yarımca", "nokta_durumu": "Yeni Nokta", "bilgi": "Ön takım ve ön düzen işlemleri de yapmakta.", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas", "Starmaxx"], "marka_listesi": ["Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2609fbe4-e458-4a67-800a-fe8ecb239905', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret gerçekleştirildi. Muhammed Bey ile görüşme sağlandı. Daha önceden cari ve b2b açılışı yapmıştık. Henüz satış gerçekleştiremedik.', '{"bolge": "Körfez", "nokta_durumu": "Yeni Nokta", "bilgi": "Risk oluşturmadan 4-8 çalışacağımız bir nokta.", "bayilikler": ["Lastik Ustam"], "raf_markalari": ["Nexen", "laufenn", "hankook"], "marka_listesi": ["Hankook", "Laufenn", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '51a29b47-a162-4e53-b7a3-e5109f7018c1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret gerçekleştirildi. Geçen hafta içerisinde 2 adet Conti satışı gerçekleştirmiştik.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "Adnan Karakaya''ya bağlı bir müşteriydi. Çok fazla binek soruyormuş bu sebeple cariyi bana devrettik. Ticari lastik işi de yapıyor. Ağırlıkta çıkma . Petrol içerisinde bir nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4437b39c-0cf0-453b-897a-a8ab59eef39c', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret yapıldı. Zeliha Hanım yerinde olmadığı olmadığı için görüşme gerçekleştirilemedi. Fakat bugün sabah telefon ile görüşmelerimize istinaden 2 adet matador satışı gerçekleştirdik.', '{"bolge": "Körfez", "nokta_durumu": "Pasif Nokta", "bilgi": "Düzenli ziyaretlerle beraber ilk satışımızı da gerçekleştirmiş olduk.", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin"], "marka_listesi": ["Michelin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0bb06852-6863-4ea5-8323-c51435cc6a37', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret yapıldı, Bayram Bey ile görüşme sağlandı. 4-8 çalıştığımız bir nokta.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "4-8 çalışıyoruz. Çok makarlı satış yapan bir nokta. Jant satışları da mevcut. Körfez yol kenarında yer alan bir nokta.", "raf_markalari": ["Falken", "Petlas", "Waterfall", "Starmaxx"], "marka_listesi": ["Falken", "Petlas", "Starmaxx", "Waterfall"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1fa9033d-6707-431b-9a97-ca91a4b88544', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret yapıldı. Sailun özelinde 17.04.2026 tarihinde görüşme gerçekleştirmiştik. Listeyi tam anlamıyla inceleyemediğini ifade etti.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "Aktif ve iyi çalıştığımız bir nokta. Continentalda iyi çalışmaktayız. İlk tercih her zaman biziz.", "bayilikler": ["LastikPark"], "raf_markalari": ["Lassa", "Bridgestone", "Hankook", "Continental", "Matador", "Starmaxx", "Laufenn"], "rakipler": ["Lastikpark"], "marka_listesi": ["Bridgestone", "Continental", "Hankook", "Lassa", "Laufenn", "Matador", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '790106e4-d8dc-45b8-baf4-daec192e7678', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret yapıldı. 18.04.2026 Cumartesi günü 16 adet Continental Dört mevsim lastik satışı gerçekleştirmiştik.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "Çok markalı çalışmakta. Ekspertiz hizmeti de veriyor. Limana yakın ve güzel bir nokta. Aktif ziyaretlerle alım gerçekleştiriyor. Premium bir nokta. Contide ilk olarak her zaman bizi tercih ediyor.", "bayilikler": ["Lastikpark"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b90f9d6e-835f-4039-b4a6-c48f230878c6', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret yapıldı. Eyyüp Bey ile görüşme gerçekleştildi. Yeni oluşturduğumuz bir nokta. Aktif ve peşin olarak çalışmaktayız.', '{"bolge": "Kuruçeşme", "nokta_durumu": "Yeni Nokta", "bilgi": "3 şubesi olan bir nokta. Continentalda ilk tercih biz olarak çalışıyoruz. Tatkoda çok fazla alacağı olduğu ve kartları oraya çektiği için Brisa grubu veya diğer ürün markalarında başka bir yerden alım yapamadığını belirtti.", "bayilikler": ["Lastikpark"], "raf_markalari": ["Riken", "Sentury", "Lassa", "Hankook", "Goodyear", "Dayton"], "rakipler": ["Tatko"], "marka_listesi": ["Dayton", "Goodyear", "Hankook", "Lassa", "Riken", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1f1e5d23-919d-4fa0-8cc4-d27d1daa9886', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret yapıldı. 3 adet matador 4 mevsim C grubu ve 5 adet conti ürün satışı gerçekleştirdik. LSR grubunda da Ayko''dan sipariş verdiğini belirtti. Ama mutlaka bizden de fiyat alıyor. Brisa grubunda da iyi ve tekrar düzenli çalışacağımız bir nokta olacaktır.', '{"bolge": "Kuruçeşme", "nokta_durumu": "Eski Nokta", "bilgi": "Tekrar haraketlenme sağladık. Şu an sorunsuz şekilde çalışmaktayız. Genel olarak internetten alışveriş yapmakta.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Continental"], "rakipler": ["YUKE", "Mutaf", "Tatko", "Ayko", "Pazaryerleri"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c494f542-1d55-4508-b09f-2d67609b80b9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-20'::date, NULL, 'Genel ziyaret gerçekleştirildi. Nihat Bey ile görüşme gerçekleştirildi. Gecikmiş bakiyesinden 50.000₺ havale alınarak gecikmiş bakiye kapatıldı. 6 adette matador siparişi aldık.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Gecikmiş bakiyesini bitirdik. Düzenli bir nokta haline getireceğiz. Brisa grubunda da aktif olarak çalışacağız.", "bayilikler": ["Hankook"], "raf_markalari": ["Lassa", "Petlas", "michelin", "dayton", "bridgestone", "laufenn", "continental"], "rakipler": ["YUKE", "Mollaoğlu", "Keskin", "Çakıroğlu"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa", "Laufenn", "Michelin", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '98575284-8d03-4b7b-8537-bb0d11f20cac', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret yapıldı. Vadesi geçmiş bakiyelerin tamamı kapatıldı geçen hafta.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "rakipler": ["YUKE", "Sevtar"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '7ff2ade8-4ca7-4e90-a994-57304640f528', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret yapıldı. Yeni oluşturduğumuz nokta. 4-8-12 şeklinde devam ediyoruz. Anlık sipariş ile yönetiyoruz. Brisa grubunda da bizi takip edecek.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bilgi": "Yetkili ve firma ortağı Savaş Okuyucu Bey ortaklıktan ayrılacağını ve yeni dükkan baktığını belirtti.", "bayilikler": ["Pirelli"], "raf_markalari": ["Pirelli", "Lassa", "Bridgestone", "Linglong"], "rakipler": ["YUKE", "Mutaf", "Ayko"], "marka_listesi": ["Bridgestone", "Lassa", "LingLong", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '42f53f2f-abb4-4e9d-9d5a-6e830c8ec11f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret yapıldı. Brisa grubundan da sipariş vermeye başladı.  9.400₺ nakit tahsilat yapıldı.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Batı Lastik''ten 4.000₺ fiyat ve 60 gün vade ile 205/55R16 Continental alımı yapmı. Aynı zamanda yine Batı Lastik''ten laufenn alımı yapmış.", "bayilikler": ["Petlas"], "raf_markalari": ["Laufen", "Sailun", "Continental"], "marka_listesi": ["Continental", "Laufenn", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'a0fdf9d4-482b-4ba5-8f12-d60d4ce2a334', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret yapıldı, Bu hafta tekrar 205/55R16 conti satışı gerçekleştirmiştik. Contideki ilk tercih her zaman biziz.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Brisa grubunda da ekran fiyatlarına bakacaklarını belirtti. Ayko ve tatkodan alım yaptığını ama ağırlıkta tatkodan alım yaptığını belirtti.", "bayilikler": ["Lastik Park"], "raf_markalari": ["Lassa", "Bridgestone", "Seatta", "Continental"], "rakipler": ["YUKE", "Tatko"], "marka_listesi": ["Bridgestone", "Continental", "Lassa", "Seatta"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0e640f01-dd18-492c-b659-4550c9d2390a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret yapıldı, neredeyse her ziyarette 1 takım da olsa satış yapıyoruz. Bugün yine 4 adet 205/55R16 Conti satışı gerçekleştirdik.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bilgi": "Brisa grubundan da bundan sonra ilk bizi arayarak çalışacağını söyledi. Çok markalı çalışmakta. Sorun yaşadığı için Her Lastik bayiliğini bırakabileceğii belirtti.", "bayilikler": ["Her Lastik"], "raf_markalari": ["Optimo", "Riken", "Petlas", "Hankook", "Kumho", "Waterfall", "Sentury", "Unique"], "rakipler": ["Tatko", "YUKE"], "marka_listesi": ["Hankook", "Kumho", "Optimo", "Petlas", "Riken", "Sentury", "Unique", "Waterfall"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f0eca459-375c-411b-a4b6-7325c3b7abb5', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret yapıldı. Erkan Bey yerinde olmadığı için görüşme gerçekleştirilemedi. Gecikmiş bakiyesinin tamamını kapatmış ve yeni sipariş yazmıştık.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Akü satış ve hizmeti de mevcut. Ön düzen hizmeti de vermekte.", "bayilikler": ["Continental"], "raf_markalari": ["Continental", "Matador"], "rakipler": ["YUKE", "Mutaf"], "marka_listesi": ["Continental", "Matador"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd7433894-29a3-4215-8229-4a2f3a49afd4', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret gerçekleştirdi. Cari ve b2b açmış olup sailun satışı gerçekleştirmiştik. Brisa grubunda da dönüş yapacaklar.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bilgi": "Yavuz Mak''dan Lassa, Bridgestone,Dayton alımlarını yapıyor.  Conti dışında Brisa grubunda b2b üzerinden takip edeceğini belirtti."}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'da9686fc-18ae-49fe-a9ae-71d2673ff8c3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret yapıldı. Metin Bey yerinde olmadığı için görüşme gerçekleştiremedik.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bilgi": "Uzun süredir satış gerçekleştirememiştik. Yeni bir şube ve yeni cari açılışı yapmışlar. Aktif ziyaretlerle Cari açılışını sağladık ve geçen hafta 8 adet dayton satışımızı da gerçekleştirdik. Telefonla sürekli irtibat halinde olup fiyat ve lastik sormakta."}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f8ca1d05-f918-4205-919f-817804633db8', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret yapıldı. 25.000₺ gecikmiş bir bakiyesi vardı tahsilatı yapıldı.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bilgi": "Özellikle eski dotlu ve yüksek jantlarda satışlar gerçekleştiriyoruz.", "bayilikler": ["Lastiğim"], "rakipler": ["Ayko", "YUKE", "Mutaf", "Keskin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bd01899f-c2a4-4837-8f83-d6e9f318df36', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret yapıldı.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bilgi": "Normalde İhtiyaç durumunda alım yapıyordu geçen hafta ilk defa stok için de 8 adet 205/55R16 Conti alımı gerçekleştirdi. . Genelde havale ve kart ile çalışıyoruz. Stok seviyelerimizin iyi ve aktif ziyaretlerimiz ile beraber artık contide ilk tercih olarak bizi tercih ettiğini belirtti.", "raf_markalari": ["Hankook", "Goodyear", "Starmaxx", "Petlas", "Lassa", "Kumho", "Kormoran"], "rakipler": ["Mollaoğlu", "YUKE"], "marka_listesi": ["Goodyear", "Hankook", "Kormoran", "Kumho", "Lassa", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '8ddc5191-0153-40f9-8768-c35ee3bdb1f9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret yapıldı, Harun Bey yerinde olmadığı için görüşme gerçekleştirilemedi. Cari ve B2b açılışını gerçekleştirmiştik. Henüz satış gerçekleştiremedik.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bilgi": "Yol yardım hizmeti de vermekte. Biraz spotçu mantığı ile çalışıyor.", "raf_markalari": ["Pirelli", "Michelin", "Kormoran", "Laufenn", "Hankook", "Lassa"], "marka_listesi": ["Hankook", "Kormoran", "Lassa", "Laufenn", "Michelin", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '5055ca10-4a65-4430-931d-ca277ec65f0e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret gerçekleştirildi. Sailun satışları gerçekleştiriyoruz. Risk oluşturmadan devam ediyoruz. Zaman zaman havaleli de çalışıyor.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bilgi": "Fren ve mekanik servisi de yapmakta olan bir nokta.", "raf_markalari": ["Petlas", "Nexen", "Sailun", "Continental", "Lassa"], "rakipler": ["Haskar"], "marka_listesi": ["Continental", "Lassa", "Nexen", "Petlas", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '62e72edc-5866-475d-835b-e020d2c5f523', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret gerçekleştirildi. Neredeyse hiç çalışmadığımız bir noktaydı. Aktif ziyaretler ve B2b etkinleştirilmesi ile beraber bu hafta tekrar 4 adet conti satışı gerçekleştirdik.', '{"bolge": "Yeşilova", "nokta_durumu": "Pasif Nokta", "bilgi": "Jant satışı da mevcut. Civardaki tüm lastikçilerle dirsek temasında.", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas"], "marka_listesi": ["Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '52dfd932-453a-420e-8206-bec3a12a7bb2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret gerçekleştirildi. 4 adet 19 Jant Conti siparişi alındı.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bilgi": "Contide ilk tercihi her zaman biziz. Fiyatlarımızın da iyi olduğunu belirtti. Brisa grubu ile ilgili de b2b den takip gerçekleştirecek. Brisa gubunu genel olarak sevtardan alım yapıyor. Sailun özelinde de çalışma yapıp alım gerçekleştirecek. Ayko lastiğim tabelası takmayı teklif etmiş. Bizim de değerlendirebileceğimiz bir nokta. Jant ve performans satışları iyi derecede.", "raf_markalari": ["Lassa", "bridgestone", "Continental", "kumho", "laufen", "michelin", "nexen."], "rakipler": ["Ayko", "Sevtar", "YUKE", "Çakıroğlu", "Konlas"], "marka_listesi": ["Bridgestone", "Continental", "Kumho", "Lassa", "Laufenn", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0842e709-27dd-4f2f-a72e-3a9bba6368cd', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret gerçekleştirildi.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bilgi": "Brisa markalarında b2b üzerinden takip edeceğini belirtti.  Henüz işlerin iyi seviyede olmadığını hem stoklarının olduğunu hem de Ayko''daki alacağının devam ettiğini belirtti. Aktif ziyaretlerimizle 4 adet Conti satışı gerçekleştirmiştik.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Starmaxx", "Dayton"], "rakipler": ["Ayko"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e0c319c6-35e6-464f-8224-7104956cdd70', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret yapıldı. Gecikmiş bakiye ile ilgili görüşme sağlandı. Hizmetini verdiği firmanın ihalesinin iptal olduğunu ve yaptığı işlerle ilgili faturaları firmaya keseceğini belirtti. Firmadan gelen ödeme ile bakiyemizi kapatacak.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "80 adet 195/65R15 Sailun kış lastiklerini yaz ile takas etmek istiyor. Bakiye kapandıktan sonra konu ile ilgili görüşeceğimizi belirttim."}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '62c1529f-5a00-4a82-8742-742e77f1f31f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-21'::date, NULL, 'Genel ziyaret yapıldı. Sailun ve Conti grubunda çalışıyoruz.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Gecikmiş bakiyesini kapattık. Aktif olarak çalışmaktayız. Brisa grubunda da fiyatları kontrol ettiğini belirtti. Ayko ile çalışmaktan da mutlu olmadığını ve neredeyse hiç çalışmadığını belirtti.", "bayilikler": ["Pirelli"], "raf_markalari": ["Pirelli"], "rakipler": ["Ayko", "Mutaf", "YUKE"], "marka_listesi": ["Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd2f983aa-79ac-4f77-8028-ee290e0ba2bb', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-22'::date, NULL, 'Genel ziyaret yapıldı. Tahir Bey ile görüşme gerçekleştirildi.  Bir önceki ziyaretimde cari ve b2b açılışını sağlamıştık. Aktif olarak çalışmaktayız. Genelde havaleli ve kredi kartı koşulu ile çalışıyoruz.', '{"bolge": "Karabük", "nokta_durumu": "Yeni Nokta", "bilgi": "Ekspertiz noktası. Genelde bizden conti alımı yapıyor. Sailun alımı da yapmıştı.", "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Continental", "Petlas"], "rakipler": ["Şahin Kardeşler"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e0be6a87-6d83-46c9-855b-3b115342183b', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-22'::date, NULL, 'Genel ziyaret yapıldı, B2b aktifleştirildi. Uğur Bey ile görüşme gerçekleştirildi. Daha önceden çalıştığımız bir nokta. Ürünlere bakacağını belirtti.', '{"bolge": "Karabük", "nokta_durumu": "Eski Nokta", "bilgi": "Peşin veya kk koşulu ile çalışmayı düşünüyorum.", "bayilikler": ["Lastikpark"], "raf_markalari": ["Falken", "Starmaxx", "Delinte", "Lassa", "Bridgestone", "Dayton", "Petlas"], "rakipler": ["Tatko"], "marka_listesi": ["Bridgestone", "Dayton", "Delinte", "Falken", "Lassa", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b916ab3e-c085-4b3b-8a84-6bdc46cec2e3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-22'::date, NULL, 'Genel ziyaret yapıldı. Ümit ve Turgay Beyler ile görüşme gerçekleştirildi. Brisa grubunda kontroller sağlayacaklarını ve dönüş yapacaklarını belirttiler.', '{"bolge": "Karabük", "nokta_durumu": "Eski Nokta", "bilgi": "Conti alımları da yapıyorlar. Aynı zamanda Balıkesir''de bir depoları mevcut olup toptan işi de yapmaktalar.", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas", "Falken", "Starmaxx", "Milestone"], "marka_listesi": ["Falken", "Milestone", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c88545d6-c7ef-43bb-895c-c8bb9d8b8594', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-22'::date, NULL, 'Genel ziyaret yapıldı, Mustafa Bey ile görüşme gerçekleştirildi. B2b aktifleştirilecek olup özellikle conti grubunda bakacaklarını belirttiler.', '{"bolge": "Karabük", "nokta_durumu": "Eski Nokta", "bayilikler": ["Brisa"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '960c715e-1d7e-465d-bca2-8077b9935439', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-22'::date, NULL, 'Genel ziyaret yapıldı, Emre Bey ile görüşme gerçekleştirildi. Bir önceki ziyaretimde cari ve b2b açılışını sağlamıştık. Sailun özelinde görüştüğümüzde alt marka olarak kolaylıkla petlas sattıklarını belirtti. Henüz satış gerçekleştiremedik.', '{"bolge": "Safranbolu", "nokta_durumu": "Yeni Nokta", "bilgi": "Şahin kardeşlerden alım yapmakta ve petlas satışı yapıyor.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Petlas"], "rakipler": ["Şahin Kardeşler"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
