INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '66af4850-0beb-403a-9ba8-cb4295ef6a62', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-22'::date, NULL, 'Genel ziyaret gerçekleştrildi. Serdar Bey ile görüşme gerçekleştidildi. Starmaxx ve Dunlop bayiliği var. Cari ve b2b açılışı sağlanacak. Sailun özelinde bilgilendirme sağlandı.', '{"bolge": "Bartın", "nokta_durumu": "Yeni Nokta", "bilgi": "Starmaxx ve Dunlop bayiliği var. Bartın bölgesinde bilinen ve çok markalı çaşışan bir nokta.", "bayilikler": ["Starmaxx", "Dunlop"], "raf_markalari": ["Hankook", "Laufenn", "Starmaxx", "Dunlop", "Goodyear"], "rakipler": ["Bar Oto", "YUKE"], "marka_listesi": ["Dunlop", "Goodyear", "Hankook", "Laufenn", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
