INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '01efd343-416d-43c5-9c28-6100ec9d3395', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-22'::date, NULL, 'Genel ziyaret yapıldı, Zekariyya Bey ile görüşme gerçekleştirildi. İhtiyaç durumunda arama yapılacak. Cari ve B2b açılışı yapılamadı.', '{"bolge": "Bartın", "nokta_durumu": "Yeni Nokta", "bilgi": "Bartın çıkışında yer alan Goodyear bayii.", "bayilikler": ["Goodyear"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Goodyear", "Seha", "Milestone"], "marka_listesi": ["Bridgestone", "Dayton", "Goodyear", "Lassa", "Milestone", "Seha"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '9a28b328-4c37-4904-947e-022521a90427', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-23'::date, NULL, 'Genel ziyaret yapıldı. Akın Bey ile görüşme gerçekleştirildi. Acılık Sanayi içerisinde Lastikpark noktası aynı zamanda araç bakım hizmetleri de vermekte. Cari ve b2b açılışı yapılacak.', '{"bolge": "Zonguldak", "nokta_durumu": "Yeni Nokta", "bilgi": "Yıllık 8-10 bin arası satışı mevcutmuş. Çok markalı bir bayi. Jant satışı da mevcut olup ön düzen hizmeti de vermekte.", "bayilikler": ["Lastikpark"], "raf_markalari": ["Lassa", "Bridgestone", "Yokohoma", "Delinte", "Falken", "Continental", "Pirelli", "Riken", "Hankook", "Laufenn"], "rakipler": ["Tatko", "Uspa", "YUKE"], "marka_listesi": ["Bridgestone", "Continental", "Delinte", "Falken", "Hankook", "Lassa", "Laufenn", "Pirelli", "Riken", "Yokohama"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bfec767d-c547-4e98-9898-d8b44d06cb1f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-23'::date, NULL, 'Genel ziyaret yapıldı. Murat Bey ile görüşme gerçekleştirildi. Petlas ve Dunlop bayilikleri var. Ankaradaki conti bayisi ile çalıştığnı belirtti. İhtiyaç durumunda arama yapacak. Cari ve b2b açılışı gerçekleştirilemedi. Bir sonraki ziyarette açılışlar yapılacak.', '{"bolge": "Zonguldak", "nokta_durumu": "Yeni Nokta", "bilgi": "Jant ve Rot hizmeti vermekte. Her iki bayii de Acılık sanayi içerisinde yer alıyor.", "bayilikler": ["Dunlop", "Petlas"], "raf_markalari": ["Dunlop", "Petlas", "Falken", "Lassa", "Dayton", "Milestone", "Starmaxx"], "marka_listesi": ["Dayton", "Dunlop", "Falken", "Lassa", "Milestone", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
