INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '744a17c4-4513-4a2c-9ee4-9a5f380be581', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-23'::date, NULL, 'Genel ziyaret ve Arif Bey ile tanışma gerçekleştirildi. Michelin bayiisi. Cari ve b2b açılışı sağlanacak. YUKE ile aktif çalışıyor. Kozlu sanayi sitesi içerisinde yer alıyor ve büyük bir bayi.', '{"bolge": "Zonguldak", "nokta_durumu": "Yeni Nokta", "bilgi": "Ön düzen hizmeti de mevcut.", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Kormoran"], "rakipler": ["YUKE"], "marka_listesi": ["Kormoran", "Michelin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
