INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b90efc14-613e-462f-8e1a-f9ed87a61bdc', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-23'::date, NULL, 'Genel ziyaret ve Engin Bey ile tanışma gerçekleştirildi. Çok markalı çalışmakta. Ağırlıkta tatko ve haskar ile çalışıyormuş.', '{"bolge": "Zonguldak", "nokta_durumu": "Yeni Nokta", "bilgi": "Dükkanı geçtiğimiz ağustos ayında devralmış. 8 yıl tatkoda son 2 yılda da haskarda bölge müdürlüğü yapmış.", "raf_markalari": ["Lassa", "Bridgestone", "Delinte", "Sentury", "Michelin", "Goodyear"], "rakipler": ["Tatko", "Haskar"], "marka_listesi": ["Bridgestone", "Delinte", "Goodyear", "Lassa", "Michelin", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '5fdc3796-a462-4c8b-a087-70d07337ccf1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-23'::date, NULL, 'Genel ziyaret ve Zeynep Hanım ile tanışma gerçekleştirildi. Ereğli sanayi sitesi içerisindeki çok büyük bir LastikPark noktası', '{"bolge": "Zonguldak", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastikpark"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
