INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f30df748-2c0c-405a-827b-416933e208b4', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-23'::date, NULL, 'Genel ziyaret ve Bülent Bey ile tanışma gerçekleştirildi. Conti ve brisa grubunda da taleplerinin olduğunu belirtti. Cari ve b2b açılışı yapılacak.', '{"bolge": "Zonguldak-Ereğli", "nokta_durumu": "Yeni Nokta", "bilgi": "Ereğli sanayi sitesi içerisinde Goodyear bayii.", "bayilikler": ["Goodyear"], "raf_markalari": ["Goodyear"], "marka_listesi": ["Goodyear"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
