INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '60ffc9ca-c2a7-4209-860b-12edfbe3732e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-23'::date, NULL, 'Genel ziyaret ve Bahri Bey ile tanışma gerçekleştirildi. Hankook tabelesı mevcut. İhtiyaç durumunda arama yapacak. Akçakoca sanayi sitesi içerisinde yer alan küçük bir nokta.', '{"bolge": "Düzce- Akçakoca", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Hankook"], "raf_markalari": ["Hankook", "Lassa"], "marka_listesi": ["Hankook", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '8a21da2e-8f90-49d9-bd13-714b8dc5fa95', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-23'::date, NULL, 'Genel ziyaret ve Güven Bey ile tanışma gerçekleştildi. Akçakoca çıkıışında Lastikpark noktası. Cari ve b2b açılışı yapılacak.', '{"bolge": "Düzce- Akçakoca", "nokta_durumu": "Yeni Nokta", "bilgi": "Eski Brisa bayisiymiş. (Güleryüz Lastik) şu an lastikpark noktası olarak hizmet vermekte.", "bayilikler": ["Lastikpark"], "raf_markalari": ["Lassa", "Goodyer", "Sentury", "Delinte", "Yokohoma", "Petlas"], "marka_listesi": ["Delinte", "Goodyear", "Lassa", "Petlas", "Sentury", "Yokohama"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b0bbc328-269c-403e-b114-bcfb185a0f9a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-24'::date, NULL, 'Genel ziyaret gerçekleştirildi. Sailun C grubu 235/65r16 ve 225/75r16 teklif verilmişti. Karayolları henüz dönüş yapmadığı için teklif sonuçlanmadı.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bilgi": "Hüseyin Bilgi müşterisi mevcutta çalışmaktayız. Brisa grubu alımlarını rota lastikten yapıyor.", "raf_markalari": ["Lassa"], "rakipler": ["Rota Lastik"], "marka_listesi": ["Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '51a29b47-a162-4e53-b7a3-e5109f7018c1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-24'::date, NULL, 'Genel ziyaret yapıldı. Daha önceki ziyaretimizde cari ve b2b açılışını sağlamıştık. Özellikle Conti grubunda destek alacağını belirtti.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Kumho bayisi, güzel ve iş potansiyeli olan bir nokta. Mutaf ile iyi çalışmaktaymış.", "bayilikler": ["Kumho"], "raf_markalari": ["Kumho", "nexen", "goodyear"], "rakipler": ["Mutaf"], "marka_listesi": ["Goodyear", "Kumho", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '66a900f6-3fd1-4bf1-8d42-821cb7c96af6', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-24'::date, NULL, 'Genel ziyaret yapıldı. Yol kenarı bir lastikçi önceden de ziyaretler sağlamıştım. Telefon ile arayıp bilgi alıyor. Whatsaap durumlarımı da takip etmekte.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Yol kenarında hizmet veriyor. Oğlu da yine düzcede yol kenarında bir noktada hizmet vermekte."}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd0a74274-6204-48e6-869a-264d77812995', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-24'::date, NULL, 'Gecikmiş bakiye ile ilgili ziyaret sağlandı. 10.000₺ KK çekildi. Bu hafta içerisinde yine 20.000₺ kk kart çekilecek. Gecikmiş ve toplam bakiyesi 89.000₺ ye kadar düşürüldü.', '{"bolge": "Düzce", "nokta_durumu": "Riskli Nokta", "bilgi": "Riskli nokta. Bakiye tahsil edildikten sonra risksiz şekilde devam edilmeli.", "raf_markalari": ["Laufenn"], "marka_listesi": ["Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4a4b2b54-82c0-4d5e-bd06-6cb0f192b4ff', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-24'::date, NULL, 'Genel ziyaret yapıldı. Bu hafta içerisinde satışlar gerçekleştirmiştik. Depo sayımı sonrası minimum 50 adet  205/55R16 Matador siparişi vereceğini belirtti.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bilgi": "Yaklaşık 2 yıl önceden 4 adet 195/65R15 Barum alacağı kalmış bizden. 8 adet bu üründen Fatura etmişiz ama ihtiyaç olduğu için 4 adetini Cemile Hanım ve Ömer Bey bilgisinde kullanılmış ama daha sonradan teslim edilmemiş. Bu konu ile ilgili yüz yüze de bilgi vereceğim.", "raf_markalari": ["Petlas", "Pirelli", "Dayton", "Starmaxx", "Laufenn"], "marka_listesi": ["Dayton", "Laufenn", "Petlas", "Pirelli", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'ea211b8a-b29b-4ee5-8ac5-1d8287a426bf', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-24'::date, NULL, 'Genel ziyaret yapıldı, Nihal Hanım ile görüşme gerçekleştirildi. cari ve b2b önceki ziyaretimde açmıştık.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Düzcedeki Brisa Bayiisi Tevekkel Oto''nun kuzenleri.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '6a0739fe-77b6-4cea-b2f5-ee01dab160fe', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-24'::date, NULL, 'Genel ziyaret yapıldı. Emrah Bey ile görüşme gerçekleştirildi. Muhammet Özdemirli noktamızdan alımlarını yapıyor. Ortak lastik alımları gerçekleştiriyorlrmış.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Petlas", "Çıkma", "Starmaxx", "Laufenn"], "marka_listesi": ["Laufenn", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '07cb245c-c6c3-4eb9-9b11-0b62d5247e04', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-24'::date, NULL, 'Genel ziyaret yapıldı, Ümit Bey yerinde olmadığı için görüşme gerçekleştirilemedi. Önceki ziyaretlerimde cari ve b2b açılışı sağlamıştık.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Aynı zamanda yedek parça servis hizmeti de vermekte", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas", "Dayton", "Starmaxx"], "marka_listesi": ["Dayton", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '7444b468-38cd-465a-8a4d-8136710e78f3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-24'::date, NULL, 'Genel ziyaret yapıldı. Abdurrahman Bey ile görüşüldü. Şahıs olarak cari açılışı sağlandı. 4 adet Conti siparişi alındı.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Sailun ile ilgili de talepleri olacak, Ucuz ve çıkma daha çok satıyor.", "raf_markalari": ["Lassa", "Dayton", "Petlas"], "marka_listesi": ["Dayton", "Lassa", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '744153f9-e23f-4807-9209-40ce1086c642', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-24'::date, NULL, 'Genel ziyaret yapıldı, bir önceki ziyaretimiz sonrasında hareketlendirme sağladık ve iki ebattan (toplamda 24 adet olmak üzere  205/55R16  ve  225/45r17 ) conti siparişi alıp sevk ve tahsilatını gerçekleştirdik. Aktif ziyaretlerle daha da hareket sağlayacağımızı düşünüyorum. Tekrar sipariş çalışıp bilgi verecek.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bilgi": "Jant satışı ve rot hizmeti de vermekte.", "bayilikler": ["Dunlop"], "raf_markalari": ["Lassa", "Falken", "Dunlop", "Bridgestone", "starmaxx", "michelin", "Continental"], "marka_listesi": ["Bridgestone", "Continental", "Dunlop", "Falken", "Lassa", "Michelin", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'fa4c6130-34e9-4899-b16c-321f2e37b14e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-24'::date, NULL, 'Genel ziyaret yapıldı. Daha önce cari ve b2b açılışını yapıp ilk Conti satışımızı gerçekleştirmiştik. Sevkiyat hızımızdan da memnun kalmıştı. B2b üzerinden Brisa grubunu da özellikle takip ettiğini belirtti.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Michelin stoklarının yüksek olduğundan dolayı bu ara neredeyse sadece michelin satışı gerçekleştirdiğini belirtti.", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Kormoran", "Nexen"], "rakipler": ["Uspa", "Keskin", "YUKE", "Bar Oto"], "marka_listesi": ["Kormoran", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c494f542-1d55-4508-b09f-2d67609b80b9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-27'::date, NULL, 'Genel ziyaret gerçekleştirildi. Nihat Bey ile görüşme gerçekleştirildi. Şu an için düzene soktuğumuz ve düzenli şekilde çalışmaya devam ettiğimiz bir nokta haline getirdik.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Hankook"], "raf_markalari": ["Lassa", "Petlas", "michelin", "dayton", "bridgestone", "laufenn", "continental"], "rakipler": ["YUKE", "Mollaoğlu", "Keskin", "Çakıroğlu"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa", "Laufenn", "Michelin", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '98575284-8d03-4b7b-8537-bb0d11f20cac', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-27'::date, NULL, 'Genel ziyaret yapıldı. Geçen aydan kalan ve iade talebini girdiğimiz ürünler ile ilgili de görüşüldü. Faturası henüz tarafımıza kesilmedi.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "rakipler": ["YUKE", "Sevtar"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '42f53f2f-abb4-4e9d-9d5a-6e830c8ec11f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-27'::date, NULL, 'Genel ziyaret yapıldı. Cuma ve Cumartesi ve bugünkü siparişlerin tahsilatı tamamlandı. (29.900₺ havale)', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Laufen", "Sailun", "Continental"], "marka_listesi": ["Continental", "Laufenn", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
