INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '5c1a7c1b-601c-4641-82d4-17e952c93ff3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret yapıldı. Cari ve b2b açılışı yapılamadı. Fikret Bey ile daha sonra görüşmek üzere ziyaret edilecek.', '{"bolge": "Körfez", "nokta_durumu": "Yeni Nokta", "bilgi": "Oto yıkama da mevcut."}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '373ecc09-9880-4a43-8571-d6087784537f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret yapıldı. Tekrar aktifleştirdiğimiz bir nokta. 12 adet conti siparişi alındı. Conti fiyatlarımızdan memnun.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "E-5 alt yolda Hankook bayii.", "bayilikler": ["Hankook"], "raf_markalari": ["Hankook", "Laufen", "Lassa", "Continental"], "marka_listesi": ["Continental", "Hankook", "Lassa", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '96f13f57-a374-404f-b9a9-2e980e651f3d', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret yapıldı. Nuri Bey ile görüşme gerçekleştirildi. Dün 4 adet conti satışı gerçekleştirdik. Genel olarak kamyon grubunda iş yapıyor.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4437b39c-0cf0-453b-897a-a8ab59eef39c', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret gerçekleştirildi. Zeliha Hanım ile görüşme sağlandı. Aktif ziyaretlerimizle beraber lastik sormaya ve b2b takip etmeye başladı. 2 adet matador satışı gerçekleştirmiştik. Yine 1 adet bridgestone siparişi alındı.', '{"bolge": "Körfez", "nokta_durumu": "Pasif Nokta", "bilgi": "Düzenli ziyaretlerle beraber ikinci satışımızı da gerçekleştirmiş olduk.", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin"], "marka_listesi": ["Michelin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1fa9033d-6707-431b-9a97-ca91a4b88544', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret yapıldı. Bekir Bey ile görüşme gerçekleşrildi.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "Aktif ve iyi çalıştığımız bir nokta. Continentalda iyi çalışmaktayız. İlk tercih her zaman biziz. 17.5 özelinde de görüşme gerçekleştirildi. Dönüş sağlayacaklar.", "bayilikler": ["LastikPark"], "raf_markalari": ["Lassa", "Bridgestone", "Hankook", "Continental", "Matador", "Starmaxx", "Laufenn"], "rakipler": ["Lastikpark"], "marka_listesi": ["Bridgestone", "Continental", "Hankook", "Lassa", "Laufenn", "Matador", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '790106e4-d8dc-45b8-baf4-daec192e7678', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret yapıldı. Cüneyt Bey ile görüşme gerçekleştirildi. Zam öncesi conti grubundan sipariş geçilecek.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "Çok markalı çalışmakta. Ekspertiz hizmeti de veriyor. Limana yakın ve güzel bir nokta. Aktif ziyaretlerle alım gerçekleştiriyor. Premium bir nokta. Contide ilk olarak her zaman bizi tercih ediyor.", "bayilikler": ["Lastikpark"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b90f9d6e-835f-4039-b4a6-c48f230878c6', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret yapıldı. Eyyüp Bey ile görüşme gerçekleştildi. Yeni oluşturduğumuz bir nokta. Aktif ve peşin olarak çalışmaktayız.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bilgi": "3 şubesi olan bir nokta. Continentalda ilk tercih biz olarak çalışıyoruz. Tatkoda 400.000 ₺ civarında bir alacağı olduğu ve kartları oraya çektiği için Brisa grubu veya diğer ürün markalarında başka bir yerden alım yapamadığını belirtti.", "bayilikler": ["Lastikpark"], "raf_markalari": ["Riken", "Sentury", "Lassa", "Hankook", "Goodyear", "Dayton"], "rakipler": ["Tatko"], "marka_listesi": ["Dayton", "Goodyear", "Hankook", "Lassa", "Riken", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '72c51015-1194-4249-8f6b-65ab774ce871', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret yapıldı. Oral Bey ile görüşme gerçekleştirildi.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "4-8 Conti satışlarımız mevcut.", "bayilikler": ["OtoPratik"], "raf_markalari": ["Lassa", "Bridgestone"], "marka_listesi": ["Bridgestone", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '52dfd932-453a-420e-8206-bec3a12a7bb2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret gerçekleştirildi. Hakan Bey ile görüşme sağlandı. Aktif ziyaretlerimizden çok memnun ve akılda kalıcılığı sağladığımızı belirtti.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bilgi": "Contide ilk tercihi her zaman biziz. Fiyatlarımızın da iyi olduğunu belirtti. Brisa grubu ile ilgili de b2b den takip gerçekleştiriyor. Brisa gubunu genel olarak sevtardan alım yapıyor. 12 adet sailun 4 adet conti siparişi alındı ve ürünler sevk edildi.", "raf_markalari": ["Lassa", "bridgestone", "Continental", "kumho", "laufen", "michelin", "nexen."], "rakipler": ["Ayko", "Sevtar", "YUKE", "Çakıroğlu", "Konlas", "Mutaflar"], "marka_listesi": ["Bridgestone", "Continental", "Kumho", "Lassa", "Laufenn", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'da9686fc-18ae-49fe-a9ae-71d2673ff8c3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret yapıldı. 4 adet 235/50R19 Lassa siparişi alındı ve tahsilatı hemen gerçekleştirildi. Kardeşi Beyhan Güneş carisine fatura edildi.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bilgi": "Geçen haftalarda 8 adet dayton satışı gerçekleştirmiştik. Genel olarak ön düzen ve yağ, filtre gibi hizmetler vermekte."}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd7433894-29a3-4215-8229-4a2f3a49afd4', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret gerçekleştirildi. Sefa Bey ile görüşme sağlandı. Yeterince stok olduğu için şu an ürün alımı yapmadığını belirtti.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bilgi": "Yavuz Mak''dan Lassa, Bridgestone,Dayton alımlarını yapıyor.  Conti dışında Brisa grubunda bizi takip ediyor ve fiyat soruyor.", "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "rakipler": ["Yavuz Mak"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bd01899f-c2a4-4837-8f83-d6e9f318df36', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret yapıldı, Emre Bey ile görüşme gerçekleştirildi. Aktif ziyaretlerimiz ile beraber tekrar hareket kazandığımız bir nokta. Özellikle iletişimimizden ve telefonlara hemen cevap vermemizden çok memnun. Dün ve bugün conti ve lassa ürün satışları gerçekleştirdik.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Hankook", "Goodyear", "Starmaxx", "Petlas", "Lassa", "Kumho", "Kormoran"], "rakipler": ["Mollaoğlu", "YUKE"], "marka_listesi": ["Goodyear", "Hankook", "Kormoran", "Kumho", "Lassa", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '888b5499-f48b-46f1-8557-f07dee71e1dc', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret yapıldı, Ömer Bey ile görüşme gerçekleştirildi. Yeşilovada arka sokaklarda yer alan bir nokta. Bu yıl stoksuz çalıştığını belirtti. Pasif ve ihtiyaç durumunda arama yapan bir nokta.', '{"bolge": "Yeşilova", "nokta_durumu": "Pasif Nokta", "bayilikler": ["Her Lastik"], "raf_markalari": ["Kumho", "Nexenn"], "marka_listesi": ["Kumho", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '8ddc5191-0153-40f9-8768-c35ee3bdb1f9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret yapıldı, Harun Bey ile görüme gerçekleştildi. Emre Bozbağ carimizin abisi. Ara ara telefonla da ürün soruyor. B2b ve cari açmıştık.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bilgi": "Yol yardım hizmeti de vermekte. Biraz spotçu mantığı ile çalışıyor.", "raf_markalari": ["Pirelli", "Michelin", "Kormoran", "Laufenn", "Hankook", "Lassa"], "marka_listesi": ["Hankook", "Kormoran", "Lassa", "Laufenn", "Michelin", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '5055ca10-4a65-4430-931d-ca277ec65f0e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-28'::date, NULL, 'Genel ziyaret gerçekleştirildi. Sailun satışları gerçekleştiriyoruz. Risk oluşturmadan devam ediyoruz. Zaman zaman havaleli de çalışıyor. Bugün yine ziyaretmizle beraber 4 adet sailun satışı daha gerçekleştirdik.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bilgi": "Fren ve mekanik servisi de yapmakta olan bir nokta.", "raf_markalari": ["Petlas", "Nexen", "Sailun", "Continental", "Lassa"], "rakipler": ["Haskar"], "marka_listesi": ["Continental", "Lassa", "Nexen", "Petlas", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1077dfc0-ad46-465b-97ae-93f7a93a3804', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-29'::date, NULL, 'Genel ziyaret gerçekleştirildi. İlhan Bey ile görüşme sağlandı. 30 gün vade koşulu ile 50 adet sailun siparişi aldık. Aktif ziyaretler ile tekrar bir hareketlenme sağladık. Conti ve Brisa grubunda yakınen takip ediyor bizi.', '{"bolge": "Geyve", "nokta_durumu": "Eski Nokta", "bilgi": "Yedi Oto ile de çalışmakta.", "bayilikler": ["Lastikvs"], "raf_markalari": ["Lassa", "Bridgestone", "Continental", "Petlas", "Sailun"], "rakipler": ["YediOto"], "marka_listesi": ["Bridgestone", "Continental", "Lassa", "Petlas", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '748451f1-2645-4e1d-8d1d-6ba1e250d178', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-29'::date, NULL, 'Genel ziyaret gerçekleştirildi. Cabbar Bey yerinde olmadığı için görüşme gerçekleştiremedik. Daha önceki ziyaretimde tanışmış ve kartvizit bırakmıştım. Şu anlık süreci telefon ile yönetmek istediğini belirtmişti.', '{"bolge": "Geyve", "nokta_durumu": "Yeni Nokta", "bilgi": "Yedek parça ve yağ satış ve servisi de vermekte olan bir nokta.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Kumho", "Lassa"], "rakipler": ["Bayraktar", "Mutaf"], "marka_listesi": ["Kumho", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'add52f6a-0f6a-40c3-b1db-ac0e94a24560', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-29'::date, NULL, 'Genel ziyaret yapıldı. Recep Bey ile tanışma ve görüşme gerçekleştirildi. Petlas bayii. Tarım, LSR ve TBR hizmetleri de veriyor. Şu an için ekrana ihtiyaç duymadığını ve talep olması durumunda bizleri arayacağını belirtti.', '{"bolge": "Geyve", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas", "Starmaxx"], "marka_listesi": ["Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'ec33f5c8-cf28-4c33-a99f-a63b7bee7d9b', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-29'::date, NULL, 'Genel ziyaret ve Emre Bey ile tanışma gerçekleştirildi. Hüseyin Bilgi ile tanışma ve görüşmeleri mevcut. Conti ve Brisa grubunda bir ihtiyaç olursa arayacaklar.', '{"bolge": "Geyve", "nokta_durumu": "Eski Nokta", "bayilikler": ["Goodyear"], "raf_markalari": ["Goodyear", "Sava"], "marka_listesi": ["Goodyear", "Sava"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '9965c44c-eca8-4ad6-9dd3-5258709c6653', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-29'::date, NULL, 'Genel ziyaret gerçekleştirildi. Ayberk Bey ile görüşme gerçekleştirildi. Daha önceki ziyaretimizde cari ve b2b açılışını gerçekleştirmiştik. Şu an için bir ihtiyacının olmadığını ama takip ettiğini belirtti. Rafında conti ürünleri de mevcut ve stoğunun yeterli olduğunu belirtti.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Yeni Nokta", "bilgi": "Bayraktar ile çalışmakta. Conti grubu için sabir bir yerle çalışmadığını belirtti.", "raf_markalari": ["Lassa", "Bridgestone", "Continental"], "rakipler": ["Bayraktar"], "marka_listesi": ["Bridgestone", "Continental", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0ce2df6f-88fa-4f75-91ed-e0ebc6559aff', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-29'::date, NULL, 'Genel ziyaret yapıldı. Serkan Bey ve Saffet Bey ile görüşme gerçekleştirildi. 17.5 üzerine de görüştük. 235/75R17.5 özelinde 6.900₺''ye starmaxxtan ürün aldıklarını belirtti. 4 adet eski dotlu 215/65R16 Yokohoma satışı gerçekleştirdik. Geçen haftalarda da 4 adet 7.50-16 tiron forklift lastiği satışı gerçekleştirmiştik.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bilgi": "Century ve Unique markalarında uygun ve uzun vadede ürün aldığını belirtti. 17.5 grubunda çalışacağız. Brisa grubunu genelde tatkodan alıyorlar. Tatkodaki fiyatların da yükseldiğini belirtti.", "bayilikler": ["Lastik VS"], "raf_markalari": ["Sentury", "Delinte", "Lassa", "Saetta", "Nexen"], "marka_listesi": ["Delinte", "Lassa", "Nexen", "Saetta", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4f44d81d-e105-4235-9fda-08ea04a5e8aa', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-29'::date, NULL, 'Genel ziyaret yapıldı, Ekrem Bey ile tanışma gerçekleştirildi. Telefon ile bana ulaşarak Cari ve B2b açılışını geçen hafta gerçekleştirmiştik. Ön siparişten kaynaklı stok seviyelerinin yüksek olduğunu belirtti. Ekrandan takip gerçekleştirdiğini belirtti.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Yeni Nokta", "bilgi": "Aktif olarak çalışaacağımız bir nokta olacağını düşünüyorum. Brisa grubunda yakın olduğu için Bayraktarlar ile çalışıyormuş.", "bayilikler": ["Lastikmarket (Yeslas)"], "raf_markalari": ["Pirelli", "Hankook", "Laufenn", "Lassa", "Dayton", "Goodyear", "Sava"], "rakipler": ["Ayko", "Tatko", "Bayrktarlar", "Keskin", "YUKE", "Konlas"], "marka_listesi": ["Dayton", "Goodyear", "Hankook", "Lassa", "Laufenn", "Pirelli", "Sava"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
