INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0d271dea-9c17-4f89-b8d8-c1ca7f744cf1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-30'::date, NULL, 'Sakarya Traktörcüler sitesi içerisinde yer alan nokta.  Genel ziyaret ve Alperen Bey ile görüşme gerçekleştirildi. B2b aktif olarak takip ediyor. Dükkanı yeni devraldığı için çok yüksek stok ile çalışmıyor. İhtiyaç durumunda mutlaka arama yapacaklar.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Yeni Nokta", "bilgi": "Dükkan 6 ay önce devralınmış.", "bayilikler": ["Lastik Park"], "raf_markalari": ["Lassa", "Bridgestone", "Starmaxx", "Petlas", "Saetta"], "marka_listesi": ["Bridgestone", "Lassa", "Petlas", "Saetta", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '221473d0-654e-42c4-9172-cf0e155aa075', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-30'::date, NULL, 'Genel ziyaret sağlandı. Kerem Bey ile görüşme gerçekleştrildi. Sailun 13 ve 14 jant siparişi verecekler. Conti grubunda ise Erenlerden zam öncesi bir miktar uzun vadede ürün alımı gerçekleştirilmiş. Fiyattan çok vadeden dolayı rakipleri tercih ediyor. (225/45R17 4.350₺ fiyatından almış. Biz KK ile 4.500₺ den satıyoruz)', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastik Park"], "raf_markalari": ["Lassa", "Sentury", "Hankook", "Continental", "Kumho", "Goodyear", "Sava"], "marka_listesi": ["Continental", "Goodyear", "Hankook", "Kumho", "Lassa", "Sava", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'ad57acd6-da02-41dd-83c4-7cf89b55b448', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-04-30'::date, NULL, 'Genel ziyaret ve Bekir Bey ile görüşme gerçekleştirildi. Conti ve Brisa grubunda mutlaka çalışacağız. Düzenli ziyaret ettiğim bir nokta. Bugünkü görüşmede de Conti ve Brisa fiyatlarını ekrandan takip ettiğini belirtti.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bilgi": "Bizimle de çalışacağını fakat bu aralar Erenler Lastiğe destek verdiğini söyledi.", "bayilikler": ["Dunlop", "Lastikpark"], "raf_markalari": ["Dunlop", "Michelin", "Pirelli", "Kumho", "Çıkma"], "rakipler": ["Erenler"], "marka_listesi": ["Dunlop", "Kumho", "Michelin", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3beece18-2947-4eb5-8580-5b3ee5ac8016', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Genel ziyaret yapıldı. Geçen hafta sailun siparişi almış ve sevkini gerçekleştirmiştik. 17.5''lar özelinde bilgi verildi. 235/75R17.5 Sailun için dönüş sağlayacaklar.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bilgi": "Hüseyin Bilgi ile TBR''de çalışmakta.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Laufen", "Pirelli"], "rakipler": ["Tevekkel"], "marka_listesi": ["Lassa", "Laufenn", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c2397d2f-57de-426c-a3af-3e04d1712eed', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Yeni nokta ziyareti yapıldı. Üzeyir Bey ile görüşme gerçekleştirildi. Yol kenarı, petrol içerisinde yer alan bir lastikçi. Genellikle ucuz lastik sattıklarını belirttirler. Sailun özelinde bilgilendirme yapıldı. Cari ve b2b açılışı gerçekleştiremedik. Lastik alımları ile Emir Bey ilgileniyormuş bir sonraki rutta tekrar ziyaret edilecek.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Delinte", "Petlas", "Seatta"], "marka_listesi": ["Delinte", "Petlas", "Seatta"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd0a74274-6204-48e6-869a-264d77812995', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Gecikmiş bakiye ile ilgili ziyaret sağlandı. Ömür Bey yerinde olmadığı için görüşme sağlanamadı. Bakiye ile ilgili telefonla temas halindeyiz. Gülçin ve ben ayrı ayrı aramalar gerçekleştiriyoruz.', '{"bolge": "Düzce", "nokta_durumu": "Riskli Nokta", "raf_markalari": ["Laufenn"], "marka_listesi": ["Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4a4b2b54-82c0-4d5e-bd06-6cb0f192b4ff', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Genel ziyaret yapıldı. Muhammet Bey ile görüşme gerçekleştirildi. 205/55R16 ve 225/45R17 fiyatlandırmaları yapıldı. Ek olarak sailun ve eski dotlu ürünlerin çıktıları liste haline getirilerek teslim edildi. Hafta sonu çalışıp dönüş yapacak.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Petlas", "Pirelli", "Dayton", "Starmaxx", "Laufenn"], "marka_listesi": ["Dayton", "Laufenn", "Petlas", "Pirelli", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
