INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b8a0d908-8e54-48e1-bf28-48846ff981ab', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Genel ziyaret yapıldı, Ayhan Bey ile görüşüldü. daha önceden cari ve b2b açılışı sağlamıştık.Conti grubunda sipariş hazırlayp vereceğini belirtti.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Lastiğim noktası ve ticari lastik de yapmakta. Aynı zamanda yedek parça servis hizmeti de vermekte", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Goodyear", "Dayton", "Bridgestone", "Prometeon"], "marka_listesi": ["Bridgestone", "Dayton", "Goodyear", "Lassa", "Prometeon"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'a5035f79-b37b-45ab-b532-b189dfa4b5e9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Genel ziyaret yapıldı. Kerim Bey ile görüşme gerçekleştirildi. Daha önceden cari ve b2b açılışı sağlamıştık. Telefon ile bizleri arayarak lastik sormakta.Ayrıca yine Düzcede çalıştığımız ve yeni oluşturduğumuz Michelin Bayisi Nokta Otomotiv Serdar Cingiz ile çalışmakta.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Performans, modifiye, yay gibi hizmetler veriyor.", "raf_markalari": ["Michelin", "petlas", "nexen", "lassa"], "marka_listesi": ["Lassa", "Michelin", "Nexen", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c4eb9141-f932-4f04-99cc-e11b4c3f86d7', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Genel ziyaret yapıldı. Celal Bey ile görüşme gerçekleştirildi. Tatko ile çalışmakta. Premium markalarda stok tutmadığını belirtti. Talep olduğu zaman bizleri arayacak.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastikpark"], "raf_markalari": ["Delinte", "Sentury", "Petlas", "Seatta"], "marka_listesi": ["Delinte", "Petlas", "Seatta", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '7444b468-38cd-465a-8a4d-8136710e78f3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Genel ziyaret yapıldı. Abdurrahman Bey ile görüşüldü. Geçen hafta 4 adet conti satışı ve tahsilatını gerçekleştirmiştik. Bu ziyaretimizde 30 gün vade koşulu ile 20 adet sailun satışı gerçekleştirdik. Mobil uygulamamızı Abdurrahman Bey''in telefonuna kurdum. Kredi kartı çekimlerini de bizden gerçekleştirecek.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Lassa", "Dayton", "Petlas"], "marka_listesi": ["Dayton", "Lassa", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3a68fec8-6c5e-4d9b-b6ff-1e14fba69283', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Genel ziyaret ve Mehmet Bey ile tanışma gerçekleştirildi. Cari ve B2b açılışı sağlayacağız. Conti grubunda bizden talepleri olacak. KDR, Mutaf, Yuke, Uspa firmalarının conti grubunda çok pahalı kaldığını belirtti. Petlas Bayisi güzel bir nokta', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Multibrand çalışan bir petlas bayisi. Petlas yönetiminden ve üründen çok memnun olmadığını bu sebeple multibrand çalıştığını belirtti.", "bayilikler": ["Petlas"], "raf_markalari": ["Pirelli", "Hankook", "Laufenn", "Petlas", "Lassa", "Goodyear", "Milestone"], "rakipler": ["Bar Oto", "YUKE", "Mutaflar", "USPA", "Rota", "Yeslas"], "marka_listesi": ["Goodyear", "Hankook", "Lassa", "Laufenn", "Milestone", "Petlas", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2c91432d-16ae-4646-a235-ebddf8753e49', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Genel ziyaret gerçekleştirildi. Sedat Bey ile görüşme sağlandı. Conti grubunda b2b''yi aktif olarak takip ediyor. Zaman zaman telefonla da bizleri arayıp ürün hakkında bilgi, fiyat soruyor. Henüz satış gerçekleştiremedik fakat aktif ziyaretlerim devam edecek.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Müşterilerin özellikle Conti taleplerinin olduğunu KDR çok pahalı kaldığı için tedarikte sorun yaşadığını ve USPA''dan baktığını belirtti.", "bayilikler": ["Hankook"], "raf_markalari": ["Hankook", "Laufenn"], "rakipler": ["Uspa", "YUKE", "Bar Oto"], "marka_listesi": ["Hankook", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '9ab723b2-7536-4088-abdc-34b76670e9e0', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Genel ziyaret yapıldı ve Volkan Bey ile tanışma gerçekleştirildi. Toyo bayiliği mevcut, aynı zamanda yağ ve mekanik bakım hizmetleri de vermekte. Kartvizit bırakıldı. Yoğunluktan dolayı bir sonraki ziyarette daha detaylı görüşmek istediğini belirtti. Bir sonraki rutta yine ziyaret gerçekleştirilecek.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Toyo"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '493fed79-0efa-4b45-ae65-2fbb15711fc1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Yeni nokta ziyareti yapıldı. Yunus Emre Bey ile tanışma gerçekleştirildi. Kartvizit bırakıldı. Yoğunluktan dolayı bir sonraki ziyarette tekrar görüşme sağlanacak.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
