INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '744153f9-e23f-4807-9209-40ce1086c642', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Genel ziyaret yapıldı. Erhan Bey ve Barış Bey ile görüşme gerçekleştirildi. Yavaş yavaş tekrar hareketlendirme sağladığımız bir nokta. Conti satışları gerçekleştirmiştik. Tekrar sipariş çalışıp bilgi verecekler. Ayrıca 8 adet 195/55R15 ebatında sipariş aldık ve bu ürünü de sıfırladık.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bayilikler": ["Dunlop"], "raf_markalari": ["Lassa", "Falken", "Dunlop", "Bridgestone", "starmaxx", "michelin", "Continental"], "marka_listesi": ["Bridgestone", "Continental", "Dunlop", "Falken", "Lassa", "Michelin", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
