INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '51a29b47-a162-4e53-b7a3-e5109f7018c1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-01'::date, NULL, 'Genel ziyaret yapıldı. Bilal Bey ile görüşme gerçekleştirildi. Conti grubunda pazardaki fiyatların yüksek olduğunu belirtti. Cari ve b2b açılışını yapmıştık. Conti talepleri oluştuğunda mutlaka bizi arayacağını ve b2b den takip edeceğini belirtti.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Kumho bayisi ve potansiyelli bir nokta. Düzce''nin çok eski esnaflarından. Mutaf ile aktif çalışıyor.", "bayilikler": ["Kumho"], "raf_markalari": ["Kumho", "nexen", "goodyear"], "rakipler": ["Mutaf"], "marka_listesi": ["Goodyear", "Kumho", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3d2a6411-8a78-4a81-9206-f934e9ec092e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-04'::date, NULL, 'Genel ziyaret yapıldı, yetkili yerinde olmadığı için görüşme gerçekleştirilemedi. Daha önceden de ziyaret edip bilgilendirme sağlamıştık.', '{"bolge": "Karamürsel-Gölcük", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Lassa", "Continental", "Nexen", "LingLong"], "marka_listesi": ["Continental", "Lassa", "LingLong", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '04dd7ad9-5f41-46b1-9b3e-27f056dc9fad', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-04'::date, NULL, 'Genel ziyaret yapıldı. İsmail Bey ile görüşme gerçekleştirildi.  4-8 çalışmaya başladık. Cemile Hanım ile servis hizmetleri konusunda destek alıyorlarmış.', '{"bolge": "Karamürsel-Gölcük", "nokta_durumu": "Pasif Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas", "Starmaxx"], "marka_listesi": ["Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '9c0f291b-4d31-41e4-a7de-a9a87f77892a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-04'::date, NULL, 'Genel ziyaret ve Naim Bey ile görüşme gerçekleştirildi. Geçen hafta havaleli 8 adet lastik satışı gerçekleştirmiştik. Aktif bir şekilde lastik soruyor. Düzenli çalışacağımızı düşünüyorum.', '{"bolge": "Karamürsel-Gölcük", "nokta_durumu": "Eski Nokta", "bilgi": "Eskiden çalıştığımız lastiğim noktamız.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Dayton"], "marka_listesi": ["Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '9d7e363b-e906-4b64-9911-6a06799c7a7b', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-04'::date, NULL, 'Genel ziyaret gerçekleştirildi. Altay ve Mustafa Beyler ile görüşme sağlandı. Geçen hafta havaleli 2 conti satışı gerçekleştirmiştik. Michelin bayiisi. Talebe göre alım yapıyor. B2b''yi aktif şekilde takip ediyorlar.', '{"bolge": "Karamürsel-Gölcük", "nokta_durumu": "Yeni Nokta", "bilgi": "Conti ile ilgili en hızlı sevkiyatı olanı tercih ettiklerini belirtiler. Ön düzen hizmeti de veren Michelin bayii. Aynı zamanda yedek parça işi de yapmakta.", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Goodyear", "Kormoran", "Taurus"], "rakipler": ["Uspa", "Keskin", "Ayko", "Çakıroğlu"], "marka_listesi": ["Goodyear", "Kormoran", "Michelin", "Taurus"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd1b2eafd-75f1-4dec-bd68-f574c6fa6dc9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-04'::date, NULL, 'Genel ziyaret yapıldı. Taci Bey ile görüşme gerçekleştildi. Eski dotlu 4 adet 215/65R16 Yokohoma satışı gerçekleştirdik gün içerisinde. Yeni cari açılışı yapmış. Bankalarda kredi limitinin oluşmasından sonra DBS ile çalışmayı düşünüyor.', '{"bolge": "Başiskele", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Kumho", "Nexen", "Sailun", "Continental", "Matador"], "rakipler": ["Mutaf"], "marka_listesi": ["Continental", "Kumho", "Matador", "Nexen", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '62c1529f-5a00-4a82-8742-742e77f1f31f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-05'::date, NULL, 'Genel ziyaret yapıldı. İrfan Bey ile beraber İade edilecek lastiklerin kontrolü sağlandı. Herhangi bir problem görülmedi iade alacağımızın bilgisini verdim. Sorunsuz bir şekilde çalışmakta olduğumuz bir noktamız.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Pirelli"], "raf_markalari": ["Pirelli"], "rakipler": ["Ayko", "Mutaf", "YUKE"], "marka_listesi": ["Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c494f542-1d55-4508-b09f-2d67609b80b9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-05'::date, NULL, 'Genel ziyaret yapıldı. Nihat Bey ile görüşme sağlandı. 12.500₺ bir gecikmiş bakiye bulunmakta. Bununla ilgili bilgi aktarımı sağlandı. 06.05.2026 tarihinde gecikmiş bakiye kapatılacak.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Hankook"], "raf_markalari": ["Lassa", "Petlas", "michelin", "dayton", "bridgestone", "laufenn", "continental"], "rakipler": ["YUKE", "Mollaoğlu", "Keskin", "Çakıroğlu"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa", "Laufenn", "Michelin", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '98575284-8d03-4b7b-8537-bb0d11f20cac', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-05'::date, NULL, 'Genel ziyaret yapıldı. Geçen aydan kalan ve iade talebini girdiğimiz ürünler ile ilgili de görüşüldü. Faturası henüz tarafımıza kesilmedi. Faturanın bugün kesileceğini belirtti.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "rakipler": ["YUKE", "Sevtar"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '7ff2ade8-4ca7-4e90-a994-57304640f528', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-05'::date, NULL, 'Genel ziyaret yapıldı. Savaş Bey yerinde olmadığı için ortağı Murat Bey ile görüşüldü. Alım ve satışlara genel olarak Savaş Bey ilgileniyor.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Pirelli"], "raf_markalari": ["Pirelli", "Lassa", "Bridgestone", "Linglong"], "rakipler": ["YUKE", "Mutaf", "Ayko"], "marka_listesi": ["Bridgestone", "Lassa", "LingLong", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '42f53f2f-abb4-4e9d-9d5a-6e830c8ec11f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-05'::date, NULL, 'Genel ziyaret yapıldı. Telefonla havaleli ve sorunsuz şekilde yönettiğimiz bir noktamız.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Laufen", "Sailun", "Continental"], "marka_listesi": ["Continental", "Laufenn", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'a0fdf9d4-482b-4ba5-8f12-d60d4ce2a334', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-05'::date, NULL, 'Genel ziyaret yapıldı, Doğan Bey ile görüşme sağlandı. 21.000₺ gecikmişinden tahsilat da gerçekleştirildi. 6.700₺ bakiyesi kaldı. Sorunsuz ve tekrar 4-8 çalışmaya başladığımız bir nokta.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastik Park"], "raf_markalari": ["Lassa", "Bridgestone", "Seatta", "Continental"], "rakipler": ["YUKE", "Tatko"], "marka_listesi": ["Bridgestone", "Continental", "Lassa", "Seatta"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0e640f01-dd18-492c-b659-4550c9d2390a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-05'::date, NULL, 'Genel ziyaret gerçekleştirildi. Erhan Bey ile görüşme sağlandı. 225/45R17 Lassa''dan fiyat bilgisi aldı bizden. Conti grubunda 4-8 çalıştğımız bir noktamız. Brisa grubunda da çalışmaya başlayacağız. Ayko ile asla çalışmadığını ve çalışmayacağını belirtti.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Her Lastik"], "raf_markalari": ["Optimo", "Riken", "Petlas", "Hankook", "Kumho", "Waterfall", "Sentury", "Unique"], "rakipler": ["Tatko", "YUKE"], "marka_listesi": ["Hankook", "Kumho", "Optimo", "Petlas", "Riken", "Sentury", "Unique", "Waterfall"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '5055ca10-4a65-4430-931d-ca277ec65f0e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-05'::date, NULL, 'Genel ziyaret yapıldı, Ahmet Bey ile görüşme gerçekleştirildi. Sailun çalışması yapmıştık. Havaleli ve 30 gün vadeli koşullar ile çalışmaktayız. Bugün 2 adet Conti, 2 adet  Matador C sınıfı havale koşulu ile satış ve tahsilat gerçekleştirdik. Küçük küçük çalıştığımız bir noktamız', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bilgi": "Fren ve mekanik servisi de yapmakta olan bir nokta.", "raf_markalari": ["Petlas", "Nexen", "Sailun", "Continental", "Lassa"], "rakipler": ["Haskar"], "marka_listesi": ["Continental", "Lassa", "Nexen", "Petlas", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '52dfd932-453a-420e-8206-bec3a12a7bb2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-05'::date, NULL, 'Continental Bölge Yöneticimiz Çağrı Bey ile beraber ziyaret gerçekleştirdik ve Hakan Bey ile görüşme sağladık. Bizden memnuniyetini de Çağrı Bey''e iletti. Geçen hafta sailun ve conti satışları da gerçekleştirdik.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Lassa", "bridgestone", "Continental", "kumho", "laufen", "michelin", "nexen."], "rakipler": ["Ayko", "Sevtar", "YUKE", "Çakıroğlu", "Konlas", "Mutaflar"], "marka_listesi": ["Bridgestone", "Continental", "Kumho", "Lassa", "Laufenn", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bfd6fca3-b120-4a14-9b61-27710a0f16b2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret yapıldı, Burak Bey yerinde olmadığı için görüşme gerçekleştirilemedi. Telefon ile arandı ve istanbulda olduğu için dükkanda olmadığını belirtti. 10.00-20 Forklift lastiği fiyatı talep etti Galaxy marka forklift lastiği ile ilgili bilgilendirme sağlandı dönüş bekleniyor.', '{"bolge": "Gebze", "nokta_durumu": "Eski Nokta", "bilgi": "Uniroyal bayiliği mevcut. Şu an raf payında Uniroyal artıyor.", "bayilikler": ["Her Lastik"], "raf_markalari": ["Uniroyal", "Michelin", "Continental"], "marka_listesi": ["Continental", "Michelin", "Uniroyal"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '85a8a360-5acf-4caf-881c-0ee3bc2dad6a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret gerçekleştirildi. Gökmen Bey ve Gürkan Bey ile görüşme sağlandı. Geçen hafta eski dotlu 225/75r16 conti, 235/65r16 roadx ve 225/75r16 sailun satışları gerçekleştirmiştik. B2b sistemimizden Brisa grubunu da yakınen takip ettiklerini belirttiler.', '{"bolge": "Gebze", "nokta_durumu": "Eski Nokta", "bilgi": "Geçmişten söz verilen termosların da teslimatını sağladım.", "bayilikler": ["LastikVS"], "raf_markalari": ["Kumho", "Goodyear", "Lassa", "Laufenn", "Hankook", "Continental"], "rakipler": ["Ayko", "YUKE", "Mutaf", "Keskin", "Mollaoğlu", "Lastikpark"], "marka_listesi": ["Continental", "Goodyear", "Hankook", "Kumho", "Lassa", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '373ecc09-9880-4a43-8571-d6087784537f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret yapıldı. Tekrar aktifleştirdiğimiz bir nokta. Conti grubunda iyi çalışmaktayız. Tekrar sipariş çalışıp bilgi verecek bize.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["Hankook"], "raf_markalari": ["Hankook", "Laufen", "Lassa", "Continental"], "marka_listesi": ["Continental", "Hankook", "Lassa", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '96f13f57-a374-404f-b9a9-2e980e651f3d', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret yapıldı. Nuri Bey ile görüşme gerçekleştirildi. Geçen hafta 4 adet conti satışı gerçekleştirdik. Bugün de 2 adet 195/65r15 eski dotlu barum satışı gerçekleştirdik. Genel olarak kamyon grubunda iş yapıyor.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e4a0b1cd-a4e8-4f35-a9e3-ab6fee410746', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret yapıldı. Sinan Bey ile görüşme gerçekleştirildi. İhtiyaca göre alım yapmakta ve ucuz segmentte 4-8 çalışmaktayız.', '{"bolge": "Derince-Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "Jant satışı da mevcut. Derincede iç tarafta bir nokta. 4-8 çalışıyoruz. Genelde sailun çalışmaktayız.", "raf_markalari": ["Goodyear", "Sailun", "Nexen", "Lassa", "Hankook"], "marka_listesi": ["Goodyear", "Hankook", "Lassa", "Nexen", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2e24a75d-d9b1-434f-977e-788e580e1378', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret yapıldı. Emre Bey ile görüşme gerçekleştirildi. Yeni oluşturduğumuz bir nokta. 4-8 çalışıyoruz ve şu an bizden alacaklı şekilde gidiyor. Lassa 215/65R16C talepleri olacak. Stoğumuzda henüz olmadığı için yardımcı olamadık.', '{"bolge": "Derince", "nokta_durumu": "Yeni Nokta", "bilgi": "Ön düzen ve ön takım hizmetleri de vermekte.", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas"], "marka_listesi": ["Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4437b39c-0cf0-453b-897a-a8ab59eef39c', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret gerçekleştirildi. Zeliha Hanım ile görüşme sağlandı. Aktif ziyaretlerimizle beraber lastik sormaya ve b2b takip etmeye başladı.  05.05.2026 tarihinde 4 adet 215/65r16 Competus satışı gerçekleştirmiştik. Genel olarak ziyaretlerimizden memnun olduğunu belirtti.', '{"bolge": "Körfez", "nokta_durumu": "Pasif Nokta", "bilgi": "Düzenli ziyaretlerle beraber üçüncü satışımızı da gerçekleştirmiş olduk.", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin"], "marka_listesi": ["Michelin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1fa9033d-6707-431b-9a97-ca91a4b88544', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret yapıldı. Bekir Bey ile görüşme gerçekleşrildi. 8 adet conti ve 1 adet bridgestone satışı gerçekleştirdik. 17.5 stoklarımızın da haretkeltnmesi sonrası LSR grubunda da aktif şekilde çalışacağımız bir nokta. Geçmişe oranla stok seviyelerimizin iyi olduğunu ve bunun da memnun edici olduğunu belirtti.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bilgi": "Ayko''da dün ziyaret gerçekleştirmiş bu noktaya.", "bayilikler": ["LastikPark"], "raf_markalari": ["Lassa", "Bridgestone", "Hankook", "Continental", "Matador", "Starmaxx", "Laufenn"], "rakipler": ["Lastikpark"], "marka_listesi": ["Bridgestone", "Continental", "Hankook", "Lassa", "Laufenn", "Matador", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '790106e4-d8dc-45b8-baf4-daec192e7678', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret yapıldı, Cüneyt Bey ile görüşme gerçekleştirildi. Aktif olarak çalışmaktayız. B2b''yi aktif olarak takip ediyor. Ziyaretlerimiz ile beraber bunu destekliyoruz. Conti grubunda iyi çalışmaktayız ve ilk tercihi her zaman biziz.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastikpark"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b90f9d6e-835f-4039-b4a6-c48f230878c6', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret yapıldı. Eyyüp Bey ile görüşme gerçekleştildi. Yeni oluşturduğumuz bir nokta. Aktif ve peşin olarak çalışmaktayız. Genel olarak sökme takma işlemlerinin hızlı olduğunu ve yeni lastik satışının az olduğunu belirtti. Tatkodaki yüksek alacağından dolayı mecburen tatkodaki markalardan stok oluşturduğunu belirtiyor.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastikpark"], "raf_markalari": ["Riken", "Sentury", "Lassa", "Hankook", "Goodyear", "Dayton"], "rakipler": ["Tatko"], "marka_listesi": ["Dayton", "Goodyear", "Hankook", "Lassa", "Riken", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1f1e5d23-919d-4fa0-8cc4-d27d1daa9886', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Yoğunluktan dolayı Mehmet Bey ile görüşme sağlanamadı. Önümüzdeki günlerde tekrar ziyaret gerçekleştirilecek.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bilgi": "Hareketlenme sağladık ve aktif şekilde devam etmekteyiz.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Continental"], "rakipler": ["YUKE", "Mutaf", "Tatko", "Ayko", "Pazaryerleri"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4d0fb43f-1d8f-4e06-8414-9b36b4e80f9e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret gerçekleştirildi. Ufuk Bey ile görüşme sağlandı. Önceki ziyaretlerimizde cari ve b2b açılışı gerçekleştirmiştik. Bugün de 30 gün vade koşulu ile 20 adet 175/70r13 ve 20 adet 175/65r14 sailun satışı gerçekleştirdik. Filoya satış yaptığını belirtti. Kısa süre içerisinde kartı da çekip hemen kapatma ihimalinin olduğunu belirtti.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastik Fix"], "raf_markalari": ["Goodyear", "Pirelli", "Dayton", "Delinte"], "marka_listesi": ["Dayton", "Delinte", "Goodyear", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f0eca459-375c-411b-a4b6-7325c3b7abb5', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret yapıldı. Erkan Bey ile görüşme sağlandı. Lastik işlerinin genel olarak durgun olduğunu ve yeni lastik satışının çok az olduğunu belirtti. Şu an gecikmiş bir bakiyemiz yok. Vadeli satış gerçekleştirmiştik.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Continental"], "raf_markalari": ["Continental", "Matador"], "rakipler": ["YUKE", "Mutaf"], "marka_listesi": ["Continental", "Matador"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b20ace7e-4e75-45cb-8d22-d0fdd6f5af17', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-06'::date, NULL, 'Genel ziyaret yapıldı. Özkan Bey ile görüşme gerçekleştirildi. Sorunsuz bir şekilde çalıştığımız bir nokta neredeyse tüm alımlarını bizden yapıyor. Normalde 30 gün vade girip fakat vade dolmadan da çekimlerini yapıyor. 20 adet conti satışı daha gerçekleştirdik. 05.05.2026 tarihinde ziyaret gerçekleştirmiştim fakat dünkü aktivitede yazmayı atladığım için bugüne yazdım.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Continental"], "raf_markalari": ["Continental", "Matador"], "rakipler": ["USPA", "Keskin", "Mutaflar"], "marka_listesi": ["Continental", "Matador"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '390384aa-6e5c-460f-839c-3bb9970d9bee', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-08'::date, NULL, 'Genel ziyaret yapıldı, Enes Bey ve Çağrı Bey ile tanışma gerçekleştirildi. Cari ve B2b açılışı sağlanacak. Kartepe kavşağında e-5 kenarında yer alan bir lastikçi. İki genç girişimci. Aynı zamanda oto yıkama yerleri de mevcut.', '{"bolge": "Kartepe", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Nexenn", "Kumho", "Lassa", "Petlas"], "rakipler": ["Mutaf", "YUKE"], "marka_listesi": ["Kumho", "Lassa", "Nexen", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e0c319c6-35e6-464f-8224-7104956cdd70', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-08'::date, NULL, 'Genel ziyaret yapıldı. Sailun kış lastiği iadeleri ile ilgili görüşüldü. Yarın iade alımı gerçekleşecek. İade sonrası hesap yapılıp alacağı kadar yaz lastiği verilip hesap sıfırlanacak.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0842e709-27dd-4f2f-a72e-3a9bba6368cd', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-08'::date, NULL, 'Genel ziyaret gerçekleştirildi. Kenan Bey ile görüşme sağlandı. Aykodaki alacağının henüz bitmediği ve alacak bitene kadar oradan lastik alımı yapacak. Bizim b2b''yi de aktif şekilde takip ediyor.  İşlerin genel anlamda durgun olduğunu belirtti.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Starmaxx", "Dayton"], "rakipler": ["Ayko"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bd01899f-c2a4-4837-8f83-d6e9f318df36', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-08'::date, NULL, 'Genel ziyaret yapıldı Emre Bey ile görüşme gerçekleştirildi. Ziyaretlerimiz ile beraber tekrar aktifleştirdiğimiz bir nokta oldu. Bugün 4 adet dayton c grubu ve 3 adet conti satışı da gerçekleştirdik. Ayko''dan hiç ürün almadığını belirtiyor.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Hankook", "Goodyear", "Starmaxx", "Petlas", "Lassa", "Kumho", "Kormoran"], "rakipler": ["Mollaoğlu", "YUKE"], "marka_listesi": ["Goodyear", "Hankook", "Kormoran", "Kumho", "Lassa", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f8ca1d05-f918-4205-919f-817804633db8', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-08'::date, NULL, 'Genel ziyaret gerçekleştirildi. Erhan Bey ile görüşme gerçekleştirildi.  Gecikmiş 62.000 bakiyesi vardı bu hafta içerisinde de kapatmıştık. B2b yi aktif şekilde takip ediyorlar. Özellikle eski dot ve performans grubu satışları da yapıyoruz.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "rakipler": ["Ayko", "YUKE", "Mutaf", "Keskin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1dd82458-b7f1-471f-b448-315672c23450', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-08'::date, NULL, 'Genel ziyaret gerçekleştirildi. Yıldıray Bilen müşterisi ve aktif şekilde çalışıyor. B2b ekranları ile alakalı sorunlar yaşıyormuş. Ekranlar ile alakalı eğitim ve destek verildi.', '{"bolge": "Yahya Kaptan", "nokta_durumu": "Eski Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'eaa93694-d009-47de-b491-272b798501ea', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Genel ziyaret yapıldı ve Serdar Bey ile tanışma gerçekleştirildi. Hüseyin Bilgi ile tanışmakta. B2b ekranları ile ilgili bilgilendirmeler yapıldı. Conti taleplerinin olduğunu ve bundan sonraki süreçte gerek ekran ile gerek telefon ile irtbata geçeceklerini belirttiler.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bilgi": "Aynı zamanda petlas bayilikleri de mevcut.", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Kormoran"], "marka_listesi": ["Kormoran", "Michelin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '520e6e90-1fec-435c-8fb6-a05e067fd371', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Genel ziyaret yapıldı. Hamza Bey ile görüşme gerçekleştirildi. Bir önceki ziyaretimizde görüştüğümüz ürünleri  11.05.2026 tarihinde 12 adet 205/55r16 matador 4 adet 205/55r16 conti satışı ve tahsilatı gerçekleştirdik.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Continental", "Matador", "Hankook", "Milestone", "Laufenn"], "rakipler": ["Bayraktar"], "marka_listesi": ["Continental", "Hankook", "Laufenn", "Matador", "Milestone"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '61142a4f-0b15-47e0-a6af-575d0bf7aea3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Genel ziyaret gerçekleştirildi. Eski dotlu ve performans grubunda 4-8 satışlar gerçekleştiriyoruz. Jant satışları daha ağırlıkta olan bir nokta. 205/55R16 ve 225/45R17 sipariş vermeyi düşündüklerini belirttiler. B2b ekranımızı yakınen takip ediyorlar.  Dönüş sağlayacaklar.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Pasif Nokta", "bayilikler": ["Express Lastik"], "raf_markalari": ["Nexen"], "marka_listesi": ["Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2ac3fa30-0725-43be-954f-1f8cbd875157', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Genel ziyaret ve Vahap Bey ile tanışma gerçekleştirildi. Traktörcüler sitesi içerisinde yer alan bir nokta. Perakende brisa bayiisi. Bu hafta 4 adet 225/45R19 Turanza 6 satışı gerçekleştirmiştik. Conti grubunda da zaman zaman taleplerin oluştuğunu belirttiler. B2b ekranlarımızı da takip etmekteler.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bayilikler": ["Brisa"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0d271dea-9c17-4f89-b8d8-c1ca7f744cf1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Sakarya Traktörcüler sitesi içerisinde yer alan nokta. Genel ziyaret ve Alperen Bey ile görüşme gerçekleştirildi. Cari ve B2b açılışını sağlamıştık fakat henüz satış gerçekleştiremedik. İşlerin durgunluğundan dolayı bir süredir stoğa ürün almadığını belirtti.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastik Park"], "raf_markalari": ["Lassa", "Bridgestone", "Starmaxx", "Petlas", "Saetta"], "marka_listesi": ["Bridgestone", "Lassa", "Petlas", "Saetta", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '469d97bc-f642-4995-88cb-eac50e666d6d', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Sakarya Traktörcüler sitesi içerisinde yer alan nokta. Genel ziyaret ve Sami Bey ile görüşme gerçekleştirildi. Bir önceki ziyaretimizde cari ve b2b açılışını sağlamıştık. B2B aktif olarak takip etmekte. Değişimlerin beklentinin altında ve yeni lastik satışının düşük olduğunu belirtti.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Yeni Nokta", "bilgi": "Bayraktarlar lastiğim noktası.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Starmaxx", "Petlas", "Saetta"], "rakipler": ["Çakıroğlu", "Erenler", "Bayraktarlar", "Yedi Oto"], "marka_listesi": ["Bridgestone", "Lassa", "Petlas", "Saetta", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '04d811ab-2331-4608-980c-9419ddb52391', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Sakarya Traktörcüler sitesi içerisinde yer alan nokta. Genel ziyaret ve İhsan Bey görüşme gerçekleştirildi. İhtiyaç durumunda arıyor. Şu ana kadar 1 adet conti satışı gerçekleştirdiğimiz bir nokta.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Pasif Nokta", "bayilikler": ["Dunlop"], "raf_markalari": ["Dunlop", "Petlas", "Milestone"], "marka_listesi": ["Dunlop", "Milestone", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '5726d681-aac5-4a9b-9a85-a3aa0f889dc3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Sakarya Traktörcüler sitesi civarında yer alan bir nokta. Turgay Bey ile tanışma ve görüşme gerçekleştirildi. Ürün gamımızadan bahsedildi. Cari ve B2b açılışı sağlayacağız. İşle asıl ilgilenen Turgut Bey bugün İstanbuldaymış. Bir sonraki ziyarette onunla da tanışma ve görüşme gerçekleştireceğiz.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Yeni Nokta", "bilgi": "Ağırlıkta rot-balans hizmeti veren bir nokta. Genel olarak sipariş usulü çalışıyormuş. 16 jant üzeri stok tutmadıklarını belirtiler.", "raf_markalari": ["Lassa", "Petlas", "Nexenn"], "rakipler": ["Mutaf", "YUKE", "Çakıroğlu", "Bayraktarlar"], "marka_listesi": ["Lassa", "Nexen", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '221473d0-654e-42c4-9172-cf0e155aa075', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Genel ziyaret ve Kerem Bey ile görüşme gerçekleştirildi. Sailun siparişi ile ilgili dönüş yapacaklar. Conti grubunda Erenlerin 90-120 gün vadelerinden dolayı zam öncesi ürün alımı gerçekleştirmiş. Conti grubunda biz de 4-8 çalışmaktayız.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastik Park"], "raf_markalari": ["Lassa", "Sentury", "Hankook", "Continental", "Kumho", "Goodyear", "Sava"], "marka_listesi": ["Continental", "Goodyear", "Hankook", "Kumho", "Lassa", "Sava", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b0989dfe-961a-4ecc-9e88-23e191b7a545', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Genel ziyaret sağlandı. Suat Bey ile görüşme gerçekleştirildi. 4-8 çalışmaktayız ama genelde UHP olarak çalışıyoruz. Bu hafta içerisinde yine 10 adet 17 jant conti satışı gerçekleştirdik. Sorunsuz bir şekilde çalışıyoruz. Conti grubunda her zaman ilk tercih biziz.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bayilikler": ["Express Lastik"], "raf_markalari": ["Hankook", "Nexen", "Laufen"], "rakipler": ["Has-Kar", "Keskin", "Bar Oto"], "marka_listesi": ["Hankook", "Laufenn", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0ce2df6f-88fa-4f75-91ed-e0ebc6559aff', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Genel ziyaret gerçekleştirildi. Serkan Bey ve Saffet Bey ile görüşme gerçekleştirildi. Ön siparişimizde yer alan 225/75R17.5 Bridgestone ile illgili görüşüldü. 2 adet ihtiyaçları olacakmış. 15 Mayısta fabrikada üretime girdikten ve tarafımıza sevk edildikten sonra satışı gerçekleştireceğiz. Ayrıca 4 adet 235/70R16 Sailun satışı gerçekleştirdik. Alacaklı şekilde gidiyordu.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bilgi": "Tabela değişikliği yapılmış. Önceki tabela Lastik Vs iken şu an Lastikpark olarak hizmet veriyor.", "bayilikler": ["Lastikpark"], "raf_markalari": ["Sentury", "Delinte", "Lassa", "Saetta", "Nexen"], "marka_listesi": ["Delinte", "Lassa", "Nexen", "Saetta", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'ad57acd6-da02-41dd-83c4-7cf89b55b448', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Genel ziyaret ve Bekir Bey ile görüşme gerçekleştirildi. Conti grubunda destek sözü verdiği için şu an Erenler ile çalışmakta. Bizim ekranlarımızı da takip etmekte.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bayilikler": ["Dunlop", "Lastikpark"], "raf_markalari": ["Dunlop", "Michelin", "Pirelli", "Kumho", "Çıkma"], "rakipler": ["Erenler"], "marka_listesi": ["Dunlop", "Kumho", "Michelin", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4f44d81d-e105-4235-9fda-08ea04a5e8aa', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Genel ziyaret ve Ekrem Bey ile görüşme gerçekleştirildi. Yeslas''tan ocak-şubat ayında vermiş olduğu ön siparişlerin sevkinin başladığıını belirtti. Stok seviyelerinin şu an yüksek olduğunu ve sadece ihtiyaç durumunda alım yapacağını belirtti. B2b''mizi aktif şekilde takip ediyor. Kış lastiğinde mutlaka çalışacağız.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastikmarket (Yeslas)"], "raf_markalari": ["Pirelli", "Hankook", "Laufenn", "Lassa", "Dayton", "Goodyear", "Sava"], "rakipler": ["Ayko", "Tatko", "Bayrktarlar", "Keskin", "YUKE", "Konlas"], "marka_listesi": ["Dayton", "Goodyear", "Hankook", "Lassa", "Laufenn", "Pirelli", "Sava"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '914713c0-9b0e-4f0d-8303-37a9028c20f1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Senet aldığımız müşteri. Tahsilat için ziyaret gerçekleştirildi. Ümit Bey''in sağlık problemlerinden dolayı iş yerinde olmadığını belirtti personeller.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Riskli Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
