INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e28d5a69-590f-4188-a2d9-8ab053dce0b6', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Genel ziyaret ve Erol Bey ile görüşme gerçekleştirildi. B2b şifreleri güncellendi ve bilgisayara kurulumu sağlandı. Ekranların gösterimi ve kullanım şekli ile ilgili eğitim de verildi. Ekranı takip edeceğini ve çalışacağımızı belirtti.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Eski Nokta", "bayilikler": ["Her Lastik"], "raf_markalari": ["Unique", "Sentury", "Lassa", "Laufenn", "Hankook", "Nexen"], "marka_listesi": ["Hankook", "Lassa", "Laufenn", "Nexen", "Sentury", "Unique"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '562b81cb-a105-46ea-ba9f-c24570ad6024', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, 'Genel ziyaret gerçekleştirildi. Daha önceki ziyaretlerimizde cari ve b2b açılışını gerçekleştirmiştik. B2b ekranlarımızı takip ediyor ve bu hafta havale koşulu ile 1 adetlik 17 jant conti satışı gerçekleştirdik.', '{"bolge": "Adapazarı-Sakarya", "nokta_durumu": "Yeni Nokta", "bilgi": "Hankook bayisi aynı zamanda ön takım, jant hizmetleri de mevcut.", "bayilikler": ["Hankook"], "raf_markalari": ["Hankook", "Nexen", "Funtoma", "Delinte"], "rakipler": ["Erenler"], "marka_listesi": ["Delinte", "Funtoma", "Hankook", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '42f53f2f-abb4-4e9d-9d5a-6e830c8ec11f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-12'::date, NULL, '133.000₺ tahsilat için ziyaret gerçekleştirildi.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Laufen", "Sailun", "Continental"], "marka_listesi": ["Continental", "Laufenn", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd2f983aa-79ac-4f77-8028-ee290e0ba2bb', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-13'::date, NULL, 'Genel ziyaret yapıldı. Tahir Bey ile görüşme gerçekleştirildi. Zam öncesi ürün satışı gerçekleştirmiştik. Aktif şekilde çalışmaktayız. Kredi kartlı satışlarımız mevcut. Risk oluşturmadan ilerleme sağlıyoruz. Haziran öncesi tekrar sipariş verecekler. Brisa grubunda yakın  olduğu için daha önceden Şahin kardeşlerden aldığı ürünler stoklarında yer alıyor.', '{"bolge": "Karabük", "nokta_durumu": "Yeni Nokta", "bilgi": "Ekspertiz noktası. Genelde bizden conti alımı yapıyor. Sailun alımı da yapmıştı. Yavaş yavaş brisa grubunda da satışlar gerçekleştiriyoruz.", "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Continental", "Petlas", "Matador"], "rakipler": ["Şahin Kardeşler"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa", "Matador", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c88545d6-c7ef-43bb-895c-c8bb9d8b8594', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-13'::date, NULL, 'Genel ziyaret yapıldı, bir önceki ziyaretimizde b2b aktifleştirmesini sağlamıştık. Mustafa Bey yerinde olmadığı için görüşme gerçekleştirielemedi. Özellikle conti grubunda takip edeceklerini daha önceden belirtmişlerdi.', '{"bolge": "Karabük", "nokta_durumu": "Eski Nokta", "bayilikler": ["Brisa"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e0be6a87-6d83-46c9-855b-3b115342183b', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-13'::date, NULL, 'Genel ziyaret yapıldı. Ekrem Bey ile görüşme gerçekleştirildi. Daha önceki ziyaretimizde b2b aktifleştirmesini sağlamıştık. Dönem dönem ürün soruyor ve b2b takip ediyor.', '{"bolge": "Karabük", "nokta_durumu": "Eski Nokta", "bilgi": "Bugünkü ziyaretimde bir tır lassa bridgestone ürün indiriyordu.  Uzun süredir Lastikparktan ürün almıyormuş. Lastikpark bayiliğini alacakmış diye duyum aldım.", "bayilikler": ["Lastikpark"], "raf_markalari": ["Falken", "Starmaxx", "Delinte", "Lassa", "Bridgestone", "Dayton", "Petlas"], "rakipler": ["Tatko"], "marka_listesi": ["Bridgestone", "Dayton", "Delinte", "Falken", "Lassa", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b916ab3e-c085-4b3b-8a84-6bdc46cec2e3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-13'::date, NULL, 'Genel ziyaret yapıldı. Ümit ve Turgay Beyler ile görüşme gerçekleştirildi. Brisa kış lastiğinde çalışma yapacağız. Bir önceki ziyaretim sonrasında Conti grubundan ürün sevki gerçekleştirmiştik. Aynı zamanda 30.000₺ tahsilat gerçekleştirdim. Kalan 40.000₺ bakiyesini bu cumaya kadar kapatacak.', '{"bolge": "Karabük", "nokta_durumu": "Eski Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas", "Falken", "Starmaxx", "Milestone"], "marka_listesi": ["Falken", "Milestone", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0a0c4edb-9178-456d-8f35-0cb7ff3ff6c2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-13'::date, NULL, 'Genel ziyaret ve Tolga Bey ile görüşme gerçekleştirildi. Genelde Off-Road lastikleri (BF Goodrich) satışları yoğun. Pasif bir nokta.', '{"bolge": "Karabük", "nokta_durumu": "Eski Nokta", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "BFGoodrich"], "marka_listesi": ["BFGoodrich", "Michelin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
