INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '66af4850-0beb-403a-9ba8-cb4295ef6a62', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-13'::date, NULL, 'Genel ziyaret gerçekleştrildi. Serdar Bey şehir dışında olduğu için görüşme gerçekleştiremedik. . Starmaxx ve Dunlop bayiliği var. Bir önceki ziyaretimizde cari ve b2b açılışı sağlamıştık.', '{"bolge": "Bartın", "nokta_durumu": "Yeni Nokta", "bilgi": "Batı karadeniz bölgesinde toptancılık yapan bir nokta.", "bayilikler": ["Starmaxx", "Dunlop"], "raf_markalari": ["Hankook", "Laufenn", "Starmaxx", "Dunlop", "Goodyear"], "rakipler": ["Bar Oto", "YUKE"], "marka_listesi": ["Dunlop", "Goodyear", "Hankook", "Laufenn", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd09574a4-db88-4ac9-a898-9bd8a57071ad', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-13'::date, NULL, 'Genel ziyaret gerçekleştirildi ve Serdar Bey ile görüşme sağlandı. Sanayideki Emir Gür Oto lastik Continental bayisinin abisi. Önceki ziyaretimde cari ve b2b açılışı sağlamıştık. B2b üzerinden özellikle brisa grubunda takip ettiğini belirtti.', '{"bolge": "Bartın", "nokta_durumu": "Yeni Nokta", "bilgi": "Brisa grubunda Rota Lastik ile de çalışmaktaymış.", "bayilikler": ["Falken"], "raf_markalari": ["Falken", "Milestone", "Petlas"], "rakipler": ["Rota Lastik"], "marka_listesi": ["Falken", "Milestone", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '7ec8e7e9-ece9-4eaf-a088-e0f23a5e2143', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret yapıldı. Çaycuma sanayi içerisinde yer alan Lastikpark Bayiisi. Yetkili Turgut Bey yerinde olmadığı için görüşme gerçekleştriilemedi. Personel Doğuş Bey ile görüşüldü. Firmamızın ve ürün gamımız hakkında bilgilendirme sağlandı. Kartvizit bırakıldı. Bir sonraki ziyarette Turgut Bey ile görüşülecek.', '{"bolge": "Zonguldak-Çaycuma", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastikpark"], "raf_markalari": ["Delinte", "Sentury", "Petlas", "Seatta", "Lassa", "Bridgestone"], "marka_listesi": ["Bridgestone", "Delinte", "Lassa", "Petlas", "Seatta", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '571ec198-43fd-4f05-80f1-aa8cfdec36b8', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret yapıldı. Çaycuma sanayi içerisinde yer alan bir nokta. Lastiğim bayiliği mevcut. Şaban Bey ve Berkan Bey ile görüşme gerçekleştirildi. Firmamızın ve ürün gamımız hakkında bilgilendirme sağlandı. Cari ve B2b açılışı yapılacak. Conti grubunda taleplerinin olduğunu fakat karşılayamadıklarını belirttiler.', '{"bolge": "Zonguldak-Çaycuma", "nokta_durumu": "Yeni Nokta", "bilgi": "Jant satışı da mevcut.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Petlas", "Milestone"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa", "Milestone", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '14e461b2-3877-4220-be1c-4a41c6ec3902', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret yapıldı. İş yeri yetkilisi Mustafa Bey yerinde olmadığı için görüşme gerçekleştirilemedi. Kartvizit bırakıldı ve bir sonraki ziyarette Mustafa Bey ile görüşülecek.', '{"bolge": "Zonguldak-Çaycuma", "nokta_durumu": "Yeni Nokta", "bilgi": "Çalışan personelin söylemine göre Conti bayiliği ile ilgili görüşmeleri mevcutmuş.", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas", "Starmaxx", "Milestone"], "marka_listesi": ["Milestone", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '9a28b328-4c37-4904-947e-022521a90427', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret yapıldı. Akın Bey ile görüşme gerçekleştirildi. Acılık Sanayi içerisinde Lastikpark noktası aynı zamanda araç bakım hizmetleri de vermekte. Bir önceki ziyaretimizde cari ve b2b açılışını sağlamıştık. Şu an için yeterli stok seviyelerinin olduğunu belirtti gelen müşterilere de bu şekilde stoktaki ürünleri satmaya çalıştğını belirtti. B2b ''mizi takip ediyor.', '{"bolge": "Zonguldak", "nokta_durumu": "Yeni Nokta", "bilgi": "Yıllık 8-10 bin arası satışı mevcutmuş. Çok markalı bir bayi. Jant satışı da mevcut olup ön düzen hizmeti de vermekte.", "bayilikler": ["Lastikpark"], "raf_markalari": ["Lassa", "Bridgestone", "Yokohoma", "Delinte", "Falken", "Continental", "Pirelli", "Riken", "Hankook", "Laufenn"], "rakipler": ["Tatko", "Uspa", "YUKE"], "marka_listesi": ["Bridgestone", "Continental", "Delinte", "Falken", "Hankook", "Lassa", "Laufenn", "Pirelli", "Riken", "Yokohama"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b90efc14-613e-462f-8e1a-f9ed87a61bdc', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret yapıldı, Engin Bey ile görüşme gerçekleştirildi. Bir önceki ziyaretimizde cari ve b2b açılışı sağladık ve çalışmaya da başlamıştık. 2 adet Lassa LSR ve 4 adet adet conti 4x4 grubunda satış gerçekleştirmiştik. Bugün de 4 adet 225/45r17 Conti siparişi aldık. Conti grubunda fiyatlarımızın diğer tüm rakiplere göre avantajlı olduğunu belirtti. B2b aktif olarak takip ediyor aynı zamanda telefon ile de görüşmekteyiz.', '{"bolge": "Zonguldak", "nokta_durumu": "Yeni Nokta", "bilgi": "Dükkanı geçtiğimiz ağustos ayında devralmış. 8 yıl tatkoda son 2 yılda da haskarda bölge müdürlüğü yapmış.", "raf_markalari": ["Lassa", "Bridgestone", "Delinte", "Sentury", "Michelin", "Goodyear"], "rakipler": ["Tatko", "Haskar", "Yuke", "Keskin", "USPA"], "marka_listesi": ["Bridgestone", "Delinte", "Goodyear", "Lassa", "Michelin", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '744a17c4-4513-4a2c-9ee4-9a5f380be581', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret ve Arif Bey ile görüşme gerçekleştirildi. Bir önceki ziyaretimizde cari ve b2b açılışı gerçekleştirmiştik. Henü satış yapamadığımız bir nokta. Elinde şu an için çok fazla michelin stok bulunduğunu belirtti bu sebeple de başka premium marka ürün şu an için almadığını ve özellikle conti taleplerinde micheline yönlendirdiğini belirtti.', '{"bolge": "Zonguldak", "nokta_durumu": "Yeni Nokta", "bilgi": "Ön düzen hizmeti de mevcut.", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Kormoran"], "rakipler": ["YUKE"], "marka_listesi": ["Kormoran", "Michelin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4b2f3e41-e5c0-4033-9836-7834e9fe160f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret ve Ümit Bey ile görüşme gerçekeltirildi. Daha önceki ziyaretimizde cari ve b2b açılışı sağlamıştık. 4 adet 4x4 conti satışı gerçekleştirmiştik. Bugün de 4 adet 195/65r15 Conti satışı gerçekleştirdik.  b2b''mizi aktif olarak takip ediyor ürün gamımız genişledikten sonra b2b''mizi ana ekrana sabitlediğini belirtti.', '{"bolge": "Zonguldak", "nokta_durumu": "Yeni Nokta", "bilgi": "Yedek  parça ve ön düzen hizmeti de vermekte. Hazar Oto ile daha önceden ortaklarmış.", "bayilikler": ["Express Lastik"], "raf_markalari": ["Michelin", "Petlas", "Lassa", "Nexenn"], "marka_listesi": ["Lassa", "Michelin", "Nexen", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '6eb9994c-dc51-4480-9a12-3c003dc5b2ef', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret ve Ersoy Bey ile görüşme gerçekleştirildi. B2b aktif olarak takip eden bir nokta. Uniroyal satışları da mevcut. Kozlu sanayinin içerisinde en arka blokta yer alan bir nokta. jant satışı da yapıyor.', '{"bolge": "Zonguldak", "nokta_durumu": "Yeni Nokta", "bilgi": "Ön düzen hizmeti de mevcut.", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas", "Milestone", "Uniroyal"], "rakipler": ["Bar Oto"], "marka_listesi": ["Milestone", "Petlas", "Uniroyal"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f30df748-2c0c-405a-827b-416933e208b4', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret ve Bülent Bey ile görüşme gerçekleştirildi. Bir önceki ziyaretimizde cari ve b2b açılışı sağlamıştık. Toplamda havale koşulu ile 12 adet lastik satışı da gerçekleştirmiştik. Conti grubunda sürekli bilgi bizden bilgi almakta.', '{"bolge": "Zonguldak-Ereğli", "nokta_durumu": "Yeni Nokta", "bilgi": "Ereğli sanayi sitesi içerisinde Goodyear bayii.", "bayilikler": ["Goodyear"], "raf_markalari": ["Goodyear"], "rakipler": ["Yuke"], "marka_listesi": ["Goodyear"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '9cf2c2b1-e694-4d69-9b65-c02cd126cfdd', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret ve İsmail Bey ile tanışma gerçekleştirildi. Firmamız ve ürünlerimiz hakkında bilgilendirme sağlandı.  Cari ve B2b açılışı yapılacak. Ereğli sanayi içerisinde petlas bayii.', '{"bolge": "Zonguldak-Ereğli", "nokta_durumu": "Yeni Nokta", "bilgi": "Ereğli sanayi sitesi içerisinde Petlas bayii.", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas"], "marka_listesi": ["Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '5fdc3796-a462-4c8b-a087-70d07337ccf1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret ve Zeynep Hanım ile görüşme gerçekleştirildi. Conti grubunda aktif olarak Keskin ile çalışmaktalar. B2b ekranlarımız da mevcut. Fiyatlarımızın takip edilecek şekilde rekabetçi olduğu konusunda bilgi verdim. Ekranları kontrol edecek ve talep oluştuğunda bilgi alacağını belirtti.', '{"bolge": "Zonguldak-Ereğli", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastikpark"], "rakipler": ["Keskin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4399d7b4-2fae-4ae0-8bb0-88167f5a79be', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret yapıldı. Eralp Bey ve Emine Hanım ile görüşme gerçekleştirildi. Ereğli merkez lokasyonunda Michelin bayii.  Firmamız ve ürün gamımızdan bahsedildi. Conti grubunda ihtiyaç olduğunu ve premium marka olduğu için michelinde yüksek olan fiyatlarda eş değer olarak conti grubunda keskinden alım yaptığını belirtti. Cari ve B2b açılışı yapılacak.', '{"bolge": "Zonguldak-Ereğli", "nokta_durumu": "Yeni Nokta", "bilgi": "Kormoranın YUKE''ye verilmesinden sonra aktif olarak orayla çalıştığını fakat yaşadığı problemler nedeniyle bir süredir çalışmadığını ve çalışmayaccağını belirtti. Kormotan yerine linglong tedarik ettiğini ve sattığını belirtti.", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Linglong"], "rakipler": ["Keskin"], "marka_listesi": ["LingLong", "Michelin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '8a21da2e-8f90-49d9-bd13-714b8dc5fa95', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-14'::date, NULL, 'Genel ziyaret ve Güven Bey ile görüşme gerçekleştildi. Bir önceki ziyaretimizde cari ve b2b açılışı sağlamıştık. Aktif ziyaretler ile hareket kazanacağını düşündüğüm bir nokta.', '{"bolge": "Düzce- Akçakoca", "nokta_durumu": "Yeni Nokta", "bilgi": "Eski Brisa bayisiymiş. (Güleryüz Lastik) şu an lastikpark noktası olarak hizmet vermekte.", "bayilikler": ["Lastikpark"], "raf_markalari": ["Lassa", "Goodyer", "Sentury", "Delinte", "Yokohoma", "Petlas"], "marka_listesi": ["Delinte", "Goodyear", "Lassa", "Petlas", "Sentury", "Yokohama"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '744153f9-e23f-4807-9209-40ce1086c642', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Genel ziyaret yapıldı, Erhan Bey ve Barış Beyler ile görüşme gerçekleştirildi. Pasif bir noktaydı tekrar hareketlendirme sağladık. Conti ve Sailun satışları da yapmıştık. İletişimde olduğumuz bir nokta. B2b de aktif takip ediyor.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bayilikler": ["Dunlop"], "raf_markalari": ["Lassa", "Falken", "Dunlop", "Bridgestone", "starmaxx", "michelin", "Continental"], "marka_listesi": ["Bridgestone", "Continental", "Dunlop", "Falken", "Lassa", "Michelin", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3a68fec8-6c5e-4d9b-b6ff-1e14fba69283', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Genel ziyaret yapıldı Mehmet Bey ile görüşme gerçekleştirildi. Bir önceki ziyarette cari ve b2b açılışını sağlamıştık. Bu ziyaretimizde ilk satışımızı da gerçekleştirdik. 12 adet lassa 1 adet dayton siparişi aldık. Conti grubunda da çalışmalarımız olacak. Genel olarak sipariş üzeri Conti alımı yapıyor. B2b aktif olarak takip etmekte.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Multibrand çalışan bir petlas bayisi. Hankook ağırlıkta çalışıyor.", "bayilikler": ["Petlas"], "raf_markalari": ["Pirelli", "Hankook", "Laufenn", "Petlas", "Lassa", "Goodyear", "Milestone"], "rakipler": ["Bar Oto", "YUKE", "Mutaflar", "USPA", "Rota", "Yeslas"], "marka_listesi": ["Goodyear", "Hankook", "Lassa", "Laufenn", "Milestone", "Petlas", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '9ab723b2-7536-4088-abdc-34b76670e9e0', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Genel ziyaret yapıldı. Önceki rutta da ziyaret gerçekleştirmiş fakat yoğunluktan dolayı görüşememiştik. Bugünkü ziyaretimizde de Volkan Bey mekanik bakım yaptığı için daha sonra görüşme gerçekleştireceğiz.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Toyo"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '51a29b47-a162-4e53-b7a3-e5109f7018c1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Genel ziyaret gerçekleştirildi. Bilal Beylerin cenazeleri olduğu için görüşme gerçekleştirilemedi.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Kumho"], "raf_markalari": ["Kumho", "nexen", "goodyear"], "rakipler": ["Mutaf"], "marka_listesi": ["Goodyear", "Kumho", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2c91432d-16ae-4646-a235-ebddf8753e49', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Genel ziyaret gerçekleştirildi. Sedat Bey ile görüşme sağlandı. Conti grubunda b2b''yi aktif olarak takip ediyor. Zaman zaman telefonla da bizleri arayıp ürün hakkında bilgi, fiyat soruyor. Henüz satış gerçekleştiremedik.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Hankook"], "raf_markalari": ["Hankook", "Laufenn"], "rakipler": ["Uspa", "YUKE", "Bar Oto"], "marka_listesi": ["Hankook", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3bed035a-fc69-488d-b2c2-94f1735e12b5', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Genel ziyaret ve İbrahim Bey ile görüşme gerçekleştirildi. Daha önceki ziyaretlerimizde b2b aktifleştirmesini sağlamıştık. B2b''mizi takip ediyor.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bayilikler": ["Brisa"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '493fed79-0efa-4b45-ae65-2fbb15711fc1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Yeni nokta ziyareti yapıldı. Yunus Emre ve Muhammed Beyler ile görüşme gerçekleştirildi. Bir önceki ziyaretimizde yoğunluktan dolayı görüşme gerçekleştirememiştik. Bu ziyaretimizde cari ve b2b açılışını da sağladık. Ürün gamımızdan bahsedildi. Conti grubunda talep olduğunu fakat karşılayamadıklarını belirttiler.  Aktif olarak çalışacağımızı düşündüğüm bir nokta.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'fa4c6130-34e9-4899-b16c-321f2e37b14e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Genel ziyaret yapıldı ve Serdar Bey ile görüşme gerçekleştirildi. Yeni oluşturdğumuz bir nokta. 8 adet conti siparişi alındı. B2b aktif olarak takip ediyor. Aynı zamanda mekanik bakım da yapan bir nokta. Sevkiyat hızımızdan da menmun.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Kormoran", "Nexen"], "rakipler": ["Uspa", "Keskin", "YUKE", "Bar Oto"], "marka_listesi": ["Kormoran", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4a4b2b54-82c0-4d5e-bd06-6cb0f192b4ff', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Genel ziyaret yapıldı, Muhammet Bey ile görüşme gerçekleştirildi. Geçen hafta toplu lastik satışı gerçekleştirmiştik. Siparişinden 125.000₺ bakiye kaldı. Bayram öncesi bakiye kapatılacak.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Petlas", "Pirelli", "Dayton", "Starmaxx", "Laufenn"], "marka_listesi": ["Dayton", "Laufenn", "Petlas", "Pirelli", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e38030a5-d4d9-4fb0-a036-1978dfb6f4e3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Genel ziyaret yapıldı. Abdurrahman ve İrfan beylerle görüşme gerçekleştirildi. Bu ay içerisinde 30 gün vade koşulu ile  sailun satışı gerçekleştirmiştik. Sattıkça hemen kartını bize çekiyor. Risk yüklenmeden devam ettiğimiz bir nokta.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Lassa", "Dayton", "Petlas"], "marka_listesi": ["Dayton", "Lassa", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c2397d2f-57de-426c-a3af-3e04d1712eed', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Yeni nokta ziyareti yapıldı. Emir Bey yerinde olmadığı için görüşme gerçekleştirelemedi. Daha önceki ziyaretimizde de Emir Bey''in ortağı Üzeyir Bey ile görüşme gerçekleştirmiştik. Lastik alımları ile Emir Bey ilgileniyor. Bir sonraki rutta tekrar ziyaret gerçekleştireceğim.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Yol kenarında Total petrol içerisinde yer alan bir lasitkçi", "raf_markalari": ["Delinte", "Petlas", "Seatta"], "marka_listesi": ["Delinte", "Petlas", "Seatta"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd0a74274-6204-48e6-869a-264d77812995', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Gecikmiş bakiye ile ilgili ziyaret sağlandı. Ömür Bey yerinde olmadığı için görüşme sağlanamadı. Bakiye ile ilgili telefonla temas halindeyiz. Gülçin ve ben ayrı ayrı aramalar gerçekleştiriyoruz. Gecikmiş bakiyeyi 59.000₺''ye kadar düşürdük.', '{"bolge": "Düzce", "nokta_durumu": "Riskli Nokta", "raf_markalari": ["Laufenn"], "marka_listesi": ["Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3beece18-2947-4eb5-8580-5b3ee5ac8016', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Genel ziyaret yapıldı ve Ali Bey ile görüşme gerçekleştilridi. 24 Adet Sailun binek satışı gerçekleştirmiştik. 235/75R17.5 Sailun için çalıştığı bir firmaya teklif verip bize dönüş sağlayacaklar.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bilgi": "Hüseyin Bilgi ile TBR''de çalışmakta.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Laufen", "Pirelli", "Sailun"], "rakipler": ["Tevekkel"], "marka_listesi": ["Lassa", "Laufenn", "Pirelli", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c61005fe-63c4-4f06-9e68-14208454192f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Genel ziyaret ve Eren Bey ile görüşme gerçekleştirildi. Pasif bir nokta. Geçtiğimiz hafta 30 Gün vadeli 8 Adet Dayton satışı gerçekleştirmiştik. Aynı zamanda yol yardım hizmeti de veren bir nokta. B2b üzerinden takip etmekte ve telefonla iletişim kurmakta.', '{"bolge": "Hendek", "nokta_durumu": "Pasif Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '679c968b-e080-4c8c-a116-cec76aba4447', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-15'::date, NULL, 'Genel ziyaret yapıldı, Samet Bey yol yardımında olduğu için görüşme gerçekleştirilemedi. Pasif bir nokta Continental tabela mevcut. 4-8 çalışıyoruz. Bu ay içerisinde 8 adet lastik satışı gerçekleştirmiştik.', '{"bolge": "Hendek", "nokta_durumu": "Pasif Nokta", "bayilikler": ["Continental"], "raf_markalari": ["Continental"], "marka_listesi": ["Continental"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c5e29a5c-91b6-483d-9358-4d551a4d7c40', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-18'::date, NULL, 'Genel ziyaret gerçekleştirildi. Sezer Bey ile görüşme sağlandı. Gecikmiş bakiye ile ilgili bilgi aktarıldı. Bu hafta gecikmeye giren 59.000₺ bakiye ile ilgili bu hafta sonuna kadar kapaması yapılacak. Bugün 14.000₺ kart çekildi.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bilgi": "Yeni oluşturduğumuz nokta. Genelde 30 gün vade koşulu ile çalışıyoruz. Havaleli ve öde al kredi kartı ile çalıştığımız dönemler de oluyor.", "bayilikler": ["LastikJantAVM"], "raf_markalari": ["Lassa", "Kormoran", "Hankook"], "rakipler": ["Keskin", "Uspa"], "marka_listesi": ["Hankook", "Kormoran", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c494f542-1d55-4508-b09f-2d67609b80b9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-18'::date, NULL, 'Genel ziyaret yapıldı, Nihat Bey ile görüşme gerçekleştirildi. Düzene soktuğumuz ve düzenli ilerlediğimiz bir nokta haline geldi. Brisa grubunda da çalışmalarımıza başladık.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Hankook"], "raf_markalari": ["Lassa", "Petlas", "michelin", "dayton", "bridgestone", "laufenn", "continental"], "rakipler": ["YUKE", "Mollaoğlu", "Keskin", "Çakıroğlu"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa", "Laufenn", "Michelin", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '7ff2ade8-4ca7-4e90-a994-57304640f528', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-18'::date, NULL, 'Genel ziyaret yapıldı, Savaş Bey ile görüşme gerçekleştildi. Özellike eski dotlarda çalışıyoruz. Kredi kartlı ve havale koşulu ile çalışmaktayız. 4 adet 225/45R17 Bridgestone RFT ve 4 adet eski dotlu 215/60R16 Yokohoma satışı ve tahsilatı gerçekleştirdik.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bilgi": "Ortakları ile anlaşma sağladığını ve şu anlık problemleri giderdiğini belirtti.", "bayilikler": ["Pirelli"], "raf_markalari": ["Pirelli", "Lassa", "Bridgestone", "Linglong"], "rakipler": ["YUKE", "Mutaf", "Ayko", "Bar Oto"], "marka_listesi": ["Bridgestone", "Lassa", "LingLong", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '42f53f2f-abb4-4e9d-9d5a-6e830c8ec11f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-18'::date, NULL, 'Genel ziyaret yapıldı, Savaş Bey ile görüşme gerçekleştirildi. 6 adet Sailun, 1 adet conti sipariş alındı. Havaleli şekilde çalışmalarımıza devam ediyoruz.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Laufen", "Sailun", "Continental"], "marka_listesi": ["Continental", "Laufenn", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '98575284-8d03-4b7b-8537-bb0d11f20cac', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-18'::date, NULL, 'Genel ziyaret yapıldı, Barış Bey ile görüşme gerçekleştirildi. 60 Gün vadeli fiyatlarımızıın çok yüksek olduğunu belirtti.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "rakipler": ["YUKE", "Sevtar"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'a0fdf9d4-482b-4ba5-8f12-d60d4ce2a334', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-18'::date, NULL, 'Genel ziyaret yapıldı, Doğan Bey ile görüşme sağlandı. Geçtiğimiz hafta 4 adet 205/55R16 Conti satışı gerçekleştirmiştik. 4-8 çalışıyoruz. Telefonla da bilgi alıyor ve conti grubunda ilk bizi tercih ediyor. Brisa grubunda da çalışacağımızı düşünüyor ve planlıyorum.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastik Park"], "raf_markalari": ["Lassa", "Bridgestone", "Seatta", "Continental"], "rakipler": ["YUKE", "Tatko"], "marka_listesi": ["Bridgestone", "Continental", "Lassa", "Seatta"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0e640f01-dd18-492c-b659-4550c9d2390a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-18'::date, NULL, 'Genel ziyaret ve Erhan Bey ile görüşme gerçekleştirildi. Yeni oluşturduğumuz bir nokta, genelde conti markasında kredi kartı koşulu ile çalışıyoruz. Brisa grubunda da fiyat ve bilgi alıyor. 4.ay itibariyle çalışmaya başladık ve şimdiye kadar 28 adet conti satışı gerçekleştirdik.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Her Lastik"], "raf_markalari": ["Optimo", "Riken", "Petlas", "Hankook", "Kumho", "Waterfall", "Sentury", "Unique"], "rakipler": ["Tatko", "YUKE"], "marka_listesi": ["Hankook", "Kumho", "Optimo", "Petlas", "Riken", "Sentury", "Unique", "Waterfall"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f0eca459-375c-411b-a4b6-7325c3b7abb5', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-18'::date, NULL, 'Genel ziyaret yapıldı. Erkan Bey ile görüşme sağlandı. Bayram nedeniyle hareketlenme başladığını belirtti. Geçen ay satışını yaptığımız ürünlerin vadesi geldi. 1Vade geldiğinden beri çekilmlere başladı. Bugün de 13.000₺ çekim gerçekleştirdik. Gecikmiş 109.000₺ bakiyeyi 69.000₺ ye düşürdük. 8 günlük gecikmiş bakiyesi söz konusu.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Continental"], "raf_markalari": ["Continental", "Matador"], "rakipler": ["YUKE", "Mutaf"], "marka_listesi": ["Continental", "Matador"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '62c1529f-5a00-4a82-8742-742e77f1f31f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-18'::date, NULL, 'Genel ziyaret yapıldı, 13.000₺ bir gecikmiş bakiyesi bulunuyor. Bilgilendirme yapıldı, Kredi kartı çekilip kapatılacak.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Pirelli"], "raf_markalari": ["Pirelli"], "rakipler": ["Ayko", "Mutaf", "YUKE"], "marka_listesi": ["Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b20ace7e-4e75-45cb-8d22-d0fdd6f5af17', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-18'::date, NULL, 'Genel ziyaret yapıldı, Özkan Bey ile görüşme gerçekleştirildi. 20 adet conti satışı gerçekleştirildi. 30 gün vade koşulu ile satışlarımızı yapıyoruz fakat vadeler dolmadan çekimler yapıyor.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Continental"], "raf_markalari": ["Continental", "Matador"], "rakipler": ["USPA", "Keskin", "Mutaflar"], "marka_listesi": ["Continental", "Matador"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4437b39c-0cf0-453b-897a-a8ab59eef39c', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-19'::date, NULL, 'Genel ziyaret gerçekleştirildi. Zeliha Hanım ile görüşme sağlandı. Aktif ziyaretlerimizle beraber lastik sormaya ve b2b takip etmeye başladı. Conti ve brisa grubunda satışlar gerçekleştirmiştik. 4-8 noktası', '{"bolge": "Körfez", "nokta_durumu": "Pasif Nokta", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin"], "marka_listesi": ["Michelin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '96f13f57-a374-404f-b9a9-2e980e651f3d', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-19'::date, NULL, 'Genel ziyaret yapıldı. Nuri Bey yerinde olmadığı için görüşme gerçekleştirilemedi. Dün 12 adet sailun satışı gerçekleştirmiştik. Tahsilatı 20.05.2026 tarihinde gerçekleştirilecek.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '373ecc09-9880-4a43-8571-d6087784537f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-19'::date, NULL, 'Genel ziyaret ve Hakan Bey ile görüşme gerçekleştirildi. Paket kampanyaları ile ilgili bilgi verildi. Stoklarını kontrol ettikten sonra dönüş sağlayacak.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["Hankook"], "raf_markalari": ["Hankook", "Laufen", "Lassa", "Continental"], "marka_listesi": ["Continental", "Hankook", "Lassa", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1fa9033d-6707-431b-9a97-ca91a4b88544', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-19'::date, NULL, 'Genel ziyaret ve Bekir Bey ile görüşme gerçekşeştirildi. Paket kampanyası ile ilgili bilgi verildi. 8 adet 225/45r17 conti ve 6 adet 215/65r16c conti siparişi alındı.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["LastikPark"], "raf_markalari": ["Lassa", "Bridgestone", "Hankook", "Continental", "Matador", "Starmaxx", "Laufenn"], "rakipler": ["Lastikpark"], "marka_listesi": ["Bridgestone", "Continental", "Hankook", "Lassa", "Laufenn", "Matador", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd283f269-35c8-49df-b899-5cc953bc165f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-19'::date, NULL, 'Genel ziyaret yapıldı, Murat ve Emre Beyler ile tanışma gerçekleştirildi. Adnan Karakaya TBR grubunda çalışıyor. Ben de binek grubunda da çalışacağız. B2b açılışı sağlanacak.', '{"bolge": "Körfez", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Çıkma"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '22682a86-951c-45cf-a427-9446a1da9208', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-19'::date, NULL, 'Genel ziyaret yapıldı, Serdar Bey yerinde olmadığı için görüşme gerçekleştirilemedi. TBR grubunda Adnan Karakaya çalışmakta. Binek lastik satışları yapıyoruz. Genelde telefon ile bilgi alıyor.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas"], "marka_listesi": ["Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '790106e4-d8dc-45b8-baf4-daec192e7678', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-19'::date, NULL, 'Genel ziyaret yapıldı, Cüneyt Bey ile görüşme gerçekleştirildi. Aktif olarak çalışmaktayız. B2b''yi aktif olarak takip ediyor. Ziyaretlerimiz ile beraber bunu destekliyoruz. Conti grubunda iyi çalışmaktayız ve ilk tercihi her zaman biziz. Paket kampanyaları paylaşılacak.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastikpark"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'da9686fc-18ae-49fe-a9ae-71d2673ff8c3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-20'::date, NULL, 'Genel ziyaret yapıldı. Geçen ay sattığımız 8 adet daytonun vadesi gelmişti. Vadesi gelmiş olan 19.760₺ tahsilatı gerçekleştirdik. ayrıca 4 Adet 195/65R15 Revola siparişi de aldık.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bilgi": "Pasif bir nokta fakat ziyaretler sağladığımızdan veri 12 adet lastik satışı gerçekleştirdik"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd7433894-29a3-4215-8229-4a2f3a49afd4', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-20'::date, NULL, 'Genel ziyaret yapıldı. Bu hafta içerisinde 4 adet 205/55r16 conti satışı ve tahsilatını gerçekleştirmiştik. Conti grubunda 4-8 çalıştığımız bir nokta. Sadece brisa grubunda ürün satışları yapıyor diyebilirim.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bilgi": "Yavuz Mak''dan Lassa, Bridgestone,Dayton alımlarını yapıyor.  Conti dışında Brisa grubunda bizi takip ediyor ve fiyat soruyor.", "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "rakipler": ["Yavuz Mak"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f8ca1d05-f918-4205-919f-817804633db8', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-20'::date, NULL, 'Genel ziyaret yapıldı. Erhan Bey ile görüşme gerçekleştirildi. Aktif ziyaretlerimizle hareketlendirme sağaldığımız bir nokta. Genellike eski dotlu ürünlerde çalışıyoruz. Yeni paket  kampanyalarımız paylaşıldı. 22.000₺ gecikmiş bakiyesi bulunuyordu. 45.000₺ tahsilat gerçekleştirdik. Eski dotlu ürünlerde sipariş çalışıp gönderecekler.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "rakipler": ["Ayko", "YUKE", "Mutaf", "Keskin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bd01899f-c2a4-4837-8f83-d6e9f318df36', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-20'::date, NULL, 'Genel ziyaret yapıldı Emre Bey ile görüşme gerçekleştirildi. Ziyaretlerimiz ile beraber tekrar aktifleştirdiğimiz bir nokta oldu. Ziyaretlerime başladığım günden bugüne kadar 67 adet lastik satışı ve tahsilatlarını gerçekleştirdik. Bugün de 4 adet 175/65R14 Dayton siparişi aldık. Paket kampanyaları ile ilgili bilgi verildi fakat paket alımı hiç yapmadığını belirtti.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Hankook", "Goodyear", "Starmaxx", "Petlas", "Lassa", "Kumho", "Kormoran"], "rakipler": ["Mollaoğlu", "YUKE", "Tatko"], "marka_listesi": ["Goodyear", "Hankook", "Kormoran", "Kumho", "Lassa", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4d0fb43f-1d8f-4e06-8414-9b36b4e80f9e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-20'::date, NULL, 'Genel ziyaret yapıldı ve Ufuk Bey ile görüşme gerçekleştirildi. Geçen haftalarda 30 gün vadeli 40 adet sailun satışı gerçekleştirmiştik. Ödemelere erkenden başlayacağını belirtti.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastik Fix"], "raf_markalari": ["Goodyear", "Pirelli", "Dayton", "Delinte"], "marka_listesi": ["Dayton", "Delinte", "Goodyear", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '52dfd932-453a-420e-8206-bec3a12a7bb2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-20'::date, NULL, 'Genel ziyaret yapıldı ve Hakan Bey ile görüşme gerçekleştirildi. Geçen hafta 18 adet conti siparişi alınmıştı. Paket kampanyaları paylaşıldı. İnceleyip bizlere dönüş sağlayacaklar.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bilgi": "Contide ilk tercihi her zaman biziz. Brisa ürün stoklarını tükettikten sonra brisa grubunda da çalışacağız.", "raf_markalari": ["Lassa", "bridgestone", "Continental", "kumho", "laufen", "michelin", "nexen."], "rakipler": ["Ayko", "Sevtar", "YUKE", "Çakıroğlu", "Konlas", "Mutaflar"], "marka_listesi": ["Bridgestone", "Continental", "Kumho", "Lassa", "Laufenn", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'dfcd41f8-b7b4-4f9e-bdcc-30a4bce1b7fa', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-20'::date, NULL, 'Genel ziyaret yapıldı ve Ahmet Bey ile görüşme gerçekleştirildi. Genelde sailun satışları yaptığımız bir nokta. Bunun yanı sıra conti ve matador satışları da gerçekleştiriyoruz. 4-8 ilerlediğimiz bir nokta.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Petlas", "Nexen", "Sailun", "Continental", "Lassa"], "rakipler": ["Haskar"], "marka_listesi": ["Continental", "Lassa", "Nexen", "Petlas", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '62e72edc-5866-475d-835b-e020d2c5f523', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-20'::date, NULL, 'Genel ziyaret ve Furkan Bey ile görüşme gerçekleştilrildi. Pasif nokta fakat ziyaretlerimizden bugüne kadar 8 adet conti satışı ve tahsilatını gerçekleştirdik. Conti grubunda bizi tercih ediyor. B2b''yi de takip etmekte. Zaman zaman telefonla da bilgi alıyor.', '{"bolge": "Yeşilova", "nokta_durumu": "Pasif Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas"], "marka_listesi": ["Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0842e709-27dd-4f2f-a72e-3a9bba6368cd', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-20'::date, NULL, 'Genel ziyaret gerçekleştirildi. Kenan Bey ile görüşme sağlandı. B2b aktif şekilde takip ediyor. 10 adet 195/55R16 Revola siparişi alındı. B2b aktif olarak takip ediyor. Geçen hafta da 4 adet eski dotlu Conti C satışı gerçekleştirmiştik. Aktif ziyaretlerle satışlara başladık.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Starmaxx", "Dayton"], "rakipler": ["Ayko"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '136a2967-6cfa-4ad7-b8f7-674668ea1813', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-22'::date, NULL, 'Genel ziyaret yapıldı ve Yakup Bey ile görüşme gerçekşeştirildi. Genelde telefon ile arayıp bilgi almakta olan bir noktamız. Aynı zamanda B2b''yi de aktif olarak takip etmekte. Paket kampanyaları hakkında bilgi verildi. İşlerin durgun olduğunu belirtti.', '{"kis_stok": "150 adet", "bolge": "Kandıra", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Özka"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4e27841c-2551-4f97-86aa-370aa06af628', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-22'::date, NULL, 'Genel ziyaret yapıldı. Bülent Bey yerinde olmadığı için görüşme gerçekleştirilemedi. Önceki ziyaretlerimizde cari ve b2b açılışını sağlamıştık. B2b takip ediyor.', '{"bolge": "Kaynarca", "nokta_durumu": "Yeni Nokta", "bilgi": "Ticari lastik satışı da yapmakta.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Petlas"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1b9130ed-2201-4783-9484-ac6b84e3f5ae', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-22'::date, NULL, 'Genel ziyaret gerçekleştirildi. Muhammed ve Bahattin Beyler ile görüşme sağlandı. Kampanyalar ile ilgili bilgi verildi ve listeler paylaşıldı. Brisa grubunda genelde Bayraktar ile çalışmışlar. Aykodan sadece bir kere alışveriş yapmışlar. B2b''mizi de aktif olarak takip ediyor.', '{"kis_stok": "350 adet", "bolge": "Kaynarca", "nokta_durumu": "Eski Nokta", "bayilikler": ["Özka"], "raf_markalari": ["Nexen", "Hankook", "Starmaxx", "Goodyear", "Lassa", "Bridgestone"], "rakipler": ["Bayraktar"], "marka_listesi": ["Bridgestone", "Goodyear", "Hankook", "Lassa", "Nexen", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '61689ce1-f2ac-43b1-97bf-e64828139429', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-22'::date, NULL, 'Genel ziyaret gerçekleştirildi. Daha önce ziyaret gerçekleştirip kartvizit bırakmıştım. Cari ve b2b açamadık. İhtiyaç durumunda arama sağlayacaklar', '{"bolge": "Kaynarca", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Her Lastik"], "raf_markalari": ["Goodyear", "Kumho", "Taurus"], "marka_listesi": ["Goodyear", "Kumho", "Taurus"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c0536bdc-737e-4a79-a1bb-464ad91dfd37', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-22'::date, NULL, 'Genel ziyaret ve Fevzi Bey ile görüşme gerçekleştirildi. Daha önceden de ziyaret sağlamış ve kartvizit bırakmıştık. Cari ve b2b açılışı henüz yapılamadı.', '{"bolge": "Kaynarca", "nokta_durumu": "Yeni Nokta", "bilgi": "Brisa grubunda Bayraktar ile çalışmakta. Contideki alımlarını da Erenler''den yapmaktaymış.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "rakipler": ["Albayrak"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '571df243-f880-4dd2-ad6b-3acbef2726b8', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-22'::date, NULL, 'Genel ziyaret yapıldı. İbrahim Bey ile görüşme gerçekleştrildi. Paket kampanyası ile ilgili bilgilendirme yapıldı fakat paket düşünmediği belirtti. Kış lastiğinde sıfır stoğunun olduğunu belirtti. Sailun kış stoğumuzu excel olarak paylaştım. Çok erkenden sipariş alabiliriz. Bugün de 16 adet sailun ve 1 adet conti siparişi aldık. Aktif ve sorunsuz şekilde çalıştığımız bir nokta.', '{"kis_stok": "0 adet", "bolge": "Karasu", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastikpark"], "raf_markalari": ["Nexen", "Hankook", "Continental", "Starmaxx", "Milestone", "Petlas", "Sailun", "Michelin", "Laufenn", "Riken", "Unique"], "rakipler": ["YUKE", "Çakıroğlu", "Tatko", "Haskar"], "marka_listesi": ["Continental", "Hankook", "Laufenn", "Michelin", "Milestone", "Nexen", "Petlas", "Riken", "Sailun", "Starmaxx", "Unique"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'a3f243c5-f57b-468c-a46d-dec783618133', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-22'::date, NULL, 'Genel ziyaret gerçekleştirildi ve Orhan Bey ile görüşme sağlandı. Yeni oluşturduğumuz bir nokta sailun, conti, matador grubunda çalışmalar yapmıştık. Risk yüklenmeden yönetilecek bir nokta. Vadesi yaklaşan bakiyeler ile ilgili bilgi verildi tarih ve tutarlar paylaşıldı. Kış sezonun kötü geçtiğini belirtti.', '{"kis_stok": "200 adet", "bolge": "Karasu", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastik Evi"], "raf_markalari": ["Continental", "Matador", "Sailun", "Dayton", "Laufenn", "Lassa", "Hankook"], "marka_listesi": ["Continental", "Dayton", "Hankook", "Lassa", "Laufenn", "Matador", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '45fd034d-bad4-4ba8-8039-702e59dafd50', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-22'::date, NULL, 'Genel ziyaret gerçekleştirildi. Hasan Bey ile görüşme sağlandı. Yeni oluşturduğumuz bir nokta. Toplamda 12 adet satış gerçekleştirmiştik. Genelde telefon ile bilgi alıyor.', '{"bolge": "Karasu", "nokta_durumu": "Yeni Nokta", "bilgi": "Yedek par.a ve yağ işi de yapmakta. Ziraii lastik satışları da mevcut.", "bayilikler": ["Goodyear"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '15c09d58-070e-4e73-8175-9b8fc7c59a30', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-22'::date, NULL, 'Genel ziyaret gerçekleştirildi. Önceki ziyaretlerimde cari ve b2b açmıştık. Tolga Bey yerinde olmadığı için görüşme gerçekleştiremedik.', '{"bolge": "Karasu", "nokta_durumu": "Yeni Nokta", "bilgi": "Rafında daha çok ucuz segment ürün mevcut. Araç kurtarma ve yol yardım hizmetleri de vermekte. Ayrıca ticari lastik satışı ve servisi de yapıyor.", "raf_markalari": ["Sentury", "Delinte", "Petlas", "Dayton", "Unique"], "marka_listesi": ["Dayton", "Delinte", "Petlas", "Sentury", "Unique"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'ec33f5c8-cf28-4c33-a99f-a63b7bee7d9b', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-22'::date, NULL, 'Genel ziyaret ve Emre Bey ile görüşme gerçekleştirildi. B2b şifreleri güncellendi ve bilgisayarına kurulumu sağlandı. Tüm sailun stoğu excel olarak paylaşıldı. Bakıp bilgi dönecek. Bu noktaya da sailun kış erken satabiliriz. Hüseyin Bilgi aktif olarak çalışmakta.', '{"bolge": "Geyve", "nokta_durumu": "Eski Nokta", "bayilikler": ["Goodyear"], "raf_markalari": ["Goodyear", "Sava"], "marka_listesi": ["Goodyear", "Sava"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1077dfc0-ad46-465b-97ae-93f7a93a3804', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-22'::date, NULL, 'Genel ziyaret gerçekleştirildi. İlhan Bey ile görüşme sağlandı. Ay başında 50 adet sailun siparişi oluşturmuştuk. Kampanyalar ile ilgili bilgi verildi. 17" üzeri conti sipariş çalışıp bilgi dönecek. B2b üzerinden de takip gerçekleştiriyor.', '{"bolge": "Geyve", "nokta_durumu": "Eski Nokta", "bilgi": "Yedi Oto ile de çalışmakta.", "bayilikler": ["Lastikvs"], "raf_markalari": ["Lassa", "Bridgestone", "Continental", "Petlas", "Sailun"], "rakipler": ["YediOto"], "marka_listesi": ["Bridgestone", "Continental", "Lassa", "Petlas", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '748451f1-2645-4e1d-8d1d-6ba1e250d178', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-05-22'::date, NULL, 'Genel ziyaret gerçekleştirildi. Cabbar Bey ile görüşme gerçekleştirildi. Cari ve B2b açılışını yapacağız. Bayraktar''ın lastiğim noktası fakat uzun süredir herhangi bir çalışma yapmadığını belirtti. Yaklaşık 1.5 yıldır hiç kimsenin uğramadığını belirtti. Ön düzen hizmeti de veriyor.', '{"bolge": "Geyve", "nokta_durumu": "Yeni Nokta", "bilgi": "Yedek parça ve yağ satış ve servisi de vermekte olan bir nokta.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Kumho", "Lassa"], "rakipler": ["Bayraktar", "Mutaf"], "marka_listesi": ["Kumho", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '85a8a360-5acf-4caf-881c-0ee3bc2dad6a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-01'::date, NULL, 'Genel ziyaret gerçekleştirildi. Gökmen Bey ve Gürkan Bey ile görüşme gerçekleştirildi. Kampanyalar paylaşıldı, kış stoğunun az kaldığını belirtti. Vadesi gelmiş bakiye ile ilgili bilgi verildi. Kısa süre içerisinde kapatılacak.', '{"kis_stok": "300 adet", "bolge": "Gebze", "nokta_durumu": "Eski Nokta", "bayilikler": ["LastikVS"], "raf_markalari": ["Kumho", "Goodyear", "Lassa", "Laufenn", "Hankook", "Continental"], "rakipler": ["Ayko", "YUKE", "Mutaf", "Keskin", "Mollaoğlu", "Lastikpark"], "marka_listesi": ["Continental", "Goodyear", "Hankook", "Kumho", "Lassa", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bfd6fca3-b120-4a14-9b61-27710a0f16b2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-01'::date, NULL, 'Genel ziyaret yapıldı, Burak Bey ile görüşme gerçekleştirildi.  Kış lastiği ortalama 100-150 adet kaldığını belirtti. Mayıs ayı içerisinde sailun ağırlıkta satışları gerçekleştirdik.', '{"kis_stok": "150 adet", "bolge": "Gebze", "nokta_durumu": "Eski Nokta", "bayilikler": ["Her Lastik"], "raf_markalari": ["Uniroyal", "Michelin", "Continental"], "marka_listesi": ["Continental", "Michelin", "Uniroyal"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '10b74adc-c14d-47bb-a772-fef28890c46d', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-01'::date, NULL, 'Genel ziyaret yapıldı, Oğuz Bey ile tanışma ve görüşme gerçekleştirildi. Ürün gamımız ve şirketimiz hakkında bilgilendirme yapıldı. Kartvizit bırakıldı, Cari ve b2b açılışını henüz yapamadık. Brisa ürün grubunu tatko ve atlastan tedarik ediyorlarmış.', '{"bolge": "Gebze", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Goodyear"], "raf_markalari": ["Goodyear", "Sava"], "rakipler": ["Tatko", "Atlas"], "marka_listesi": ["Goodyear", "Sava"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '373ecc09-9880-4a43-8571-d6087784537f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-01'::date, NULL, 'Genel ziyaret yapıldı, Hakan Bey ile görüşme gerçekleştirildi. Kampanyadan ürün almayacağını fakat yazlık sipariş çalışıp sipariş hazırlayacağını belirtti. Mağaza ve depo düzeltimine başladıklarını ve bu sebeple henüz kış stoğu ile ilgili net bilgi verilmedi.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["Hankook"], "raf_markalari": ["Hankook", "Laufen", "Lassa", "Continental"], "marka_listesi": ["Continental", "Hankook", "Lassa", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4437b39c-0cf0-453b-897a-a8ab59eef39c', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-01'::date, NULL, 'Genel ziyaret gerçekleştirildi. Zeliha Hanım yerinde olmadığı için görüşme sağlanamadı.', '{"bolge": "Körfez", "nokta_durumu": "Pasif Nokta", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin"], "marka_listesi": ["Michelin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1fa9033d-6707-431b-9a97-ca91a4b88544', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-01'::date, NULL, 'Genel ziyaret yapıldı, Bekir Bey ile görüşme gerçekleştirildi. Kampanya listeleri paylaşılmıştı bu konu ile ilgili dönüş yapılacak. Kış lastiği stoğunun yüksek seviyede olduğunu belirtti.', '{"kis_stok": "500 adet", "bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["LastikPark"], "raf_markalari": ["Lassa", "Bridgestone", "Hankook", "Continental", "Matador", "Starmaxx", "Laufenn"], "rakipler": ["Lastikpark"], "marka_listesi": ["Bridgestone", "Continental", "Hankook", "Lassa", "Laufenn", "Matador", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '790106e4-d8dc-45b8-baf4-daec192e7678', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-01'::date, NULL, 'Genel ziyaret yapıldı, Cüneyt Bey ile görüşme gerçekleştilrildi. Kış lastiği stoğunun çok fazla olmadığını ve kış lastiğinde popüler ebatlarda az stok tuttuğunu onun haricinde diğer ebatlardan stok tutmadığnı belirtti.', '{"kis_stok": "200 adet", "bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastikpark"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'cfa9bb02-faaa-45f7-a84c-3c122732d8da', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-01'::date, NULL, 'Genel ziyaret yapıldı, Murat ve Emre Beyler ile görüşme gerçekleştirildi. Sipariş üzeri ve stoksuz çalıştığımız bir nokta. Ticari lastik satışı da yapmakta. 10-12 adet kaplama yapılacak karkası varmış. Adnan Karakaya''ya bilgi verildi. Adnan Karakaya kaplamalar ile ilgili yarın uğrayacak.', '{"bolge": "Derince", "nokta_durumu": "Yeni Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2e24a75d-d9b1-434f-977e-788e580e1378', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-01'::date, NULL, 'Genel ziyaret yapıldı. Emre Bey ile görüşme gerçekleştirildi. Yeni oluşturduğumuz bir nokta. 4-8 çalışıyoruz.', '{"bolge": "Derince", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas"], "marka_listesi": ["Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e4a0b1cd-a4e8-4f35-a9e3-ab6fee410746', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-01'::date, NULL, 'Genel ziyaret yapıldı, Sinan Bey ile görüşme gerçekleştirildi. Mayıs ayında sailun satışları gerçekleştirmiştik. 4-8 çalışmakta olan bir yer ve ihtiyaca göre alın yapmaktadır.', '{"bolge": "Derince", "nokta_durumu": "Eski Nokta", "bilgi": "Jant satışı da mevcut. Derincede iç tarafta bir nokta. 4-8 çalışıyoruz. Genelde sailun çalışmaktayız.", "raf_markalari": ["Goodyear", "Sailun", "Nexen", "Lassa", "Hankook"], "marka_listesi": ["Goodyear", "Hankook", "Lassa", "Nexen", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
