INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c494f542-1d55-4508-b09f-2d67609b80b9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-01'::date, NULL, 'Genel ziyaret yapıldı, Nihat Bey ile görüşme gerçekleştirildi. Düzene soktuğumuz ve düzenli ilerlediğimiz bir nokta haline geldi. Vadesi gelmiş bakiyesi ile ilgili bilgi verildi.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Hankook"], "raf_markalari": ["Lassa", "Petlas", "michelin", "dayton", "bridgestone", "laufenn", "continental"], "rakipler": ["YUKE", "Mollaoğlu", "Keskin", "Çakıroğlu"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa", "Laufenn", "Michelin", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'e0c319c6-35e6-464f-8224-7104956cdd70', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-01'::date, NULL, 'Genel ziyaret yapıldı, Mürsel Bey ile görüşme gerçekleştirildi. İade edilen ürünler ile ilgili fatura düzenlenmesi ile ilgili bilgi verildi ve fatura alındı.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'da9686fc-18ae-49fe-a9ae-71d2673ff8c3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-02'::date, NULL, 'Genel ziyaret ve Metin Bey ile görüşme gerçekleştirildi. Pasif bir noktaydı ziyaretlerimizin sayesinde 4-8 satışlara başladık. Lastik satışından çok rot ve araç bakım hizmeti veriyor. Yeşilovada yeni dükkan açmış olup burada hizmet veriyor.', '{"kis_stok": "0 adet", "bolge": "Yeşilova", "nokta_durumu": "Eski Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f8ca1d05-f918-4205-919f-817804633db8', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-02'::date, NULL, 'Genel ziyaret yapıldı. Erhan Bey ile görüşme gerçekleştirildi. Daha çok eski dotlu satış yaptığımız bir noktaydı. Paket kampanyaları ve eski dotlu listelerin paylaşımını yapmıştım. Henüz sipariş çalışamamışlar. Kısa süre içerisinde paket ve eski dotlu ürünler ile ilgili dönüş yapacaklar. Depo düzenlemesi sonrası kış lastiği stoklarına bakacaklar', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "rakipler": ["Ayko", "YUKE", "Mutaf", "Keskin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bd01899f-c2a4-4837-8f83-d6e9f318df36', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-02'::date, NULL, 'Genel ziyaret yapıldı. Emre bey yol yardımında olduğu için görüşme gerçekleştirilemedi. Paket kampanyasının sunumunu yapmıştık fakat paket kampanyalarına hiç dahil olmadığını belirtmişti. Aktif ziyaretlerimizle özellikle conti grubunda satış gerçekleştirdiğimiz bir nokta.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Hankook", "Goodyear", "Starmaxx", "Petlas", "Lassa", "Kumho", "Kormoran", "Delinte"], "rakipler": ["Mollaoğlu", "YUKE", "Tatko"], "marka_listesi": ["Delinte", "Goodyear", "Hankook", "Kormoran", "Kumho", "Lassa", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4d0fb43f-1d8f-4e06-8414-9b36b4e80f9e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-02'::date, NULL, 'Genel ziyaret yapıldı ve Ufuk Bey ile görüşme gerçekleştirildi. Geçen ay gerçekleştirdiğimiz 40 adet sailun satışımızın vadesinin yaklaştığının bilgisini aktardım. Bu hafta çekimlere başlayacağını belirtti. Yeni nokta olduğu için yakınen takip ediyorum.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastik Fix"], "raf_markalari": ["Goodyear", "Pirelli", "Dayton", "Delinte"], "marka_listesi": ["Dayton", "Delinte", "Goodyear", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '5055ca10-4a65-4430-931d-ca277ec65f0e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-02'::date, NULL, 'Genel ziyaret yapıldı ve Ahmet Bey ile görüşme gerçekleştirildi. Genelde sailun satışları yaptığımız bir nokta. Bunun yanı sıra conti ve matador satışları da gerçekleştiriyoruz. 4 Adet 175/70R13 ve 4 adet 175/65R14 Sailun siparişi aldık. Kış lastiğinde hiç stok tutmadığını sadece konsiye olarak 2 takım petlas bulundurduğunu belirtti.', '{"kis_stok": "0 adet", "bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Petlas", "Nexen", "Sailun", "Continental", "Lassa"], "rakipler": ["Haskar"], "marka_listesi": ["Continental", "Lassa", "Nexen", "Petlas", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '52dfd932-453a-420e-8206-bec3a12a7bb2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-02'::date, NULL, 'Genel ziyaret ve Hakan Bey ile görüşme gerçekleştirildi. Geçtiğimiz haftaki ziyarette paket kampanya listeleri paylaşılmıştı. Paket ile ilgili dönüş yapacak. Paket haricinde de geçtiğimiz hafta 28 adet Continental markasında sipariş oluşturup sevkini gerçekleştirmiştik. Kış lastiği stoğunun hiç kalmadığı belirtti.', '{"kis_stok": "0 adet", "bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Lassa", "bridgestone", "Continental", "kumho", "laufen", "michelin", "nexen."], "rakipler": ["Ayko", "Sevtar", "YUKE", "Çakıroğlu", "Konlas", "Mutaflar"], "marka_listesi": ["Bridgestone", "Continental", "Kumho", "Lassa", "Laufenn", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
