INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '8bf98c44-e325-4a26-a33e-16396f54a7b0', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-03'::date, NULL, 'Genel ziyaret yapıldı ve Uğur Bey ile tanışma gerçekleştirildi. Gölcük sanayi içerisinde yer alan bir nokta.  Ürün gamımız ve şirketimiz ile ilgili bilgi verildi. Cari ve b2b açılışı yapılacak. Rot hizmeti veriyor aynı zamanda jant satışı da yapan bir nokta.', '{"bolge": "Gölcük", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Lassa", "Nexenn", "Laufenn"], "rakipler": ["Yuke"], "marka_listesi": ["Lassa", "Laufenn", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'fa06e642-503e-43f1-a98a-35b5688c699d', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-03'::date, NULL, 'Genel ziyaret ve Ramazan Bey ile tanışma gerçekleştirildi. Ürün gamımız ve şirketimiz ile ilgili bilgilendirme yapıldı. Şu an için b2b ve cari açılışı sağlayamadık. Kartvizit bırakıldı, ihtiyaç durumunda arama yapacaklar. 5-6 tedarikçi ile çalıştığnı ve genelde 75-90 gün vadelerle ürün aldığını belirtti.', '{"bolge": "Gölcük", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["LingLong", "Seatta"], "marka_listesi": ["LingLong", "Seatta"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'fe37315a-4eb2-49a7-8e7c-6b65bfa5f581', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-03'::date, NULL, 'Genel ziyaret yapıldı ve Abdurrahman Bey ile görüşme gerçekleştirildi. Gölcük sanayi içerisinde yer alan Lastikpark Bayisii. Ürün gamımız ve firmamız ile ilgili bilgilendirme yapıldı, Cari ve B2b açılışı yapılacak.', '{"bolge": "Gölcük", "nokta_durumu": "Yeni Nokta", "bayilikler": ["LastikPark"], "raf_markalari": ["Unique", "Delinte", "Lassa", "Bridgestone", "Seatta"], "rakipler": ["Tatko"], "marka_listesi": ["Bridgestone", "Delinte", "Lassa", "Seatta", "Unique"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '694af2b2-4673-4b65-8786-98f31bc13302', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-03'::date, NULL, 'Genel ziyaret yapıldı ve Mehmet Bey ile tanışma gerçekleştirildi. Gölcük sanayi içerisinde yer alan Lastik VS bayiisi. Ürün gamımız ve şirketimiz hakkında bilgilendirme yapıldı. Cari ve B2b açılışı sağlanacak.', '{"bolge": "Gölcük", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastik VS"], "raf_markalari": ["Goodyear", "Pirelli", "Apollo", "Goodyear"], "marka_listesi": ["Apollo", "Goodyear", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '22724ac8-14e8-4d85-bf6a-28d4ac86dbc6', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-03'::date, NULL, 'Genel ziyaret yapıldı, yetkili yerinde olmadığı için görüşme gerçekleştirilemedi. Bir sonraki rutta tekrar ziyaret edilecek.', '{"bolge": "Gölcük", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastik Jant AVM"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '9d7e363b-e906-4b64-9911-6a06799c7a7b', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-03'::date, NULL, 'Genel ziyaret yapıldı, Mustafa Bey ile görüşme gerçekleştirildi. Önceki ziyaretlerimizde Cari vw B2b açılışı yapıp 4 adet de conti satışı gerçekleştirmiştik. B2b aktif olarak takip ediyorlar. Michelin bayiisi.', '{"bolge": "Gölcük", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Goodyear", "Kormoran", "Taurus"], "rakipler": ["Uspa", "Keskin", "Ayko", "Çakıroğlu"], "marka_listesi": ["Goodyear", "Kormoran", "Michelin", "Taurus"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c5c24fed-6bdf-4497-a35e-c1d1f0a0100b', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-03'::date, NULL, 'Genel ziyaret yapıldı. Fatih Bey ile tanışma ve görüşme gerçekleştirildi. B2b aktifleştirildi. Daha çok ticari serviste işlem yapmakta ve Cemile Hanım ile görüşmekteler. Binek tarafında da taleplerinin olduğunu belirtti. B2b bilgileri paylaşıldı. Ticari lastik ve kaplama konuları ile ilgili de Yıldıray Bey''e bilgi verildi. Yıldıray Bey de ziyaret gerçekleştirecek.', '{"bolge": "Gölcük", "nokta_durumu": "Eski Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd1b2eafd-75f1-4dec-bd68-f574c6fa6dc9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-03'::date, NULL, 'Genel ziyaret yapıldı. Taci Bey ile görüşme gerçekleştildi. Kampanyalar ile ilgili bilgi paylaşıldı, şu an için stok almayacağını belirtti.', '{"bolge": "Başiskele", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Kumho", "Nexen", "Sailun", "Continental", "Matador"], "rakipler": ["Mutaf"], "marka_listesi": ["Continental", "Kumho", "Matador", "Nexen", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '31b27d8e-1a85-4b45-aaa7-5e916f48311d', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-04'::date, NULL, 'Genel ziyaret yapıldı, Rami Bey ile tanışma ve görüşme gerçekleştirildi. Firmamız ve ürün gamımız ile ilgili bilgi aktarımı sağlandı. Cari ve B2b açılışı yapıldı.', '{"bolge": "Sakarya", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas"], "marka_listesi": ["Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2fbeab14-d49b-4104-bb72-71858f11e56b', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-04'::date, NULL, 'Genel ziyaret gerçekleştirildi. Turgay Bey ile görüşme sağlandı. Mayıs ayı içerisinde sailun ve eski dotlu ürün satışları gerçekleştirmiştik. B2b aktif şekilde takip ediyor. Kış lastiği stoğu sıfır.', '{"kis_stok": "0 adet", "bolge": "Sakarya", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Petlas", "Sailun"], "rakipler": ["Erenler", "Mutaf"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa", "Petlas", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0ce2df6f-88fa-4f75-91ed-e0ebc6559aff', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-04'::date, NULL, 'Genel ziyaret ve Serkan Bey ve Saffet Bey ile görüşme gerçekleştirildi. Kampanya listeleri paylaşıldı. Listeleri inceledikten sonra dönüş yapacaklar. Mayıs ayında eski dotlu Continental C grubunda satışlar gerçekleştirmiştik. Kış lastiği stoğununun maximum 100 adette olduğunu belirtti.', '{"kis_stok": "100 adet", "bolge": "Sakarya", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastikpark"], "raf_markalari": ["Sentury", "Delinte", "Lassa", "Saetta", "Nexen"], "marka_listesi": ["Delinte", "Lassa", "Nexen", "Saetta", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b0989dfe-961a-4ecc-9e88-23e191b7a545', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-04'::date, NULL, 'Genel ziyaret yapıldı ve Suat Bey ile görüşme gerçekleştirildi. 20.000₺ vadesi geçmiş bakiyesi bulunuyor bu hafta içerisinde kapatılacak. 4-8 çalışmakta olduğumuz bir nokta. İhtiyaca göre alım yapmakta ve paket kampanyalarına girmiyor.', '{"kis_stok": "0 adet", "bolge": "Sakarya", "nokta_durumu": "Eski Nokta", "bayilikler": ["Express Lastik"], "raf_markalari": ["Hankook", "Nexen", "Laufen"], "rakipler": ["Has-Kar", "Keskin", "Bar Oto"], "marka_listesi": ["Hankook", "Laufenn", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '221473d0-654e-42c4-9172-cf0e155aa075', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-04'::date, NULL, 'Genel ziyaret ve Kerem Bey ile görüşme gerçekleştirildi. Taksitli çekim fiyatıyla 30 gün içerisinde kart ile kapama koşulunun uygulanacağının bilgisini verdim. Ayrıca kampanya listelerini de paylaşarak bilgilendirme sağladım. İnceleyip dönüş yapacaklar. Bu koşulu bu noktaya uyguladıktan sonra satışlarımızın artacağını düşünüyorum.', '{"bolge": "Sakarya", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastik Park"], "raf_markalari": ["Lassa", "Sentury", "Hankook", "Continental", "Kumho", "Goodyear", "Sava"], "marka_listesi": ["Continental", "Goodyear", "Hankook", "Kumho", "Lassa", "Sava", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2c6852d6-638d-4c30-b815-0076e74db34d', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-04'::date, NULL, 'Genel ziyaret yapıldı, Mehmet Bey ve Elif Hanım ile tanışma gerçekleştirildi. B2b hakkında bilgi verildi ve binek lastik ihtiyaçlarında benim yardımcı olacağım konusunda bilgilendirme sağladım. Cemile Hanım veya Serdar Bey ile görüşme gerçekleştiriyorlarmış.', '{"bolge": "Sakarya", "nokta_durumu": "Eski Nokta", "bayilikler": ["Continental"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4f44d81d-e105-4235-9fda-08ea04a5e8aa', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-04'::date, NULL, 'Genel ziyaret ve Ekrem Bey ile görüşme gerçekleştirildi. Yeslas''tan ön siparişten vermiş olduğu siparişlerinin sevkinin devam ettiğini ve Stok seviyelerinin yüksek olduğunu belirtti. Bayram öncesi  4 adet lassa markasında satış ve tahsilat gerçekleştirmiştik.', '{"bolge": "Sakarya", "nokta_durumu": "Yeni Nokta", "bilgi": "Ara toptancılık da yapmakta olan bir nokta.", "bayilikler": ["Lastikmarket (Yeslas)"], "raf_markalari": ["Pirelli", "Hankook", "Laufenn", "Lassa", "Dayton", "Goodyear", "Sava"], "rakipler": ["Ayko", "Tatko", "Bayrktarlar", "Keskin", "YUKE", "Konlas"], "marka_listesi": ["Dayton", "Goodyear", "Hankook", "Lassa", "Laufenn", "Pirelli", "Sava"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
