INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '520e6e90-1fec-435c-8fb6-a05e067fd371', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-04'::date, NULL, 'Genel ziyaret yapıldı ve Hamza Bey ile görüşme gerçekleştirildi. Bu yıl içerisinde açılmış bir nokta. Kampanya listeleri paylaşıldı. Paketleri inceleyip dönüş sağlayacaklar. Bayram öncesinde matador satışları ve tahsilatlarını gerçekleştirmiştik. Kış lastik stoğu  hiç yok.', '{"kis_stok": "0 adet", "bolge": "Sakarya", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Continental", "Matador", "Hankook", "Milestone", "Laufenn"], "rakipler": ["Bayraktar"], "marka_listesi": ["Continental", "Hankook", "Laufenn", "Matador", "Milestone"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'ad57acd6-da02-41dd-83c4-7cf89b55b448', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-04'::date, NULL, 'Genel ziyaret ve Bekir Bey ile görüşme gerçekleştirildi. Paket kampanyalarımız ile ilgili bilgi aktarımı sağlandı. İnceleyip dönüş yapacaklar. Ümit Işık''taki bakiyemizin tahsilatında da bize yardımcı olan noktamız. Erenlere destek sözü verdiği için bu aralar onunla çalıştığını ama mutlaka bize de döneceğini belirtti. Kış lastiğinin maximum 5 takım olduğunu belirtti.', '{"kis_stok": "20 adet", "bolge": "Sakarya", "nokta_durumu": "Eski Nokta", "bayilikler": ["Dunlop", "Lastikpark"], "raf_markalari": ["Dunlop", "Michelin", "Pirelli", "Kumho", "Çıkma"], "rakipler": ["Erenler"], "marka_listesi": ["Dunlop", "Kumho", "Michelin", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3beece18-2947-4eb5-8580-5b3ee5ac8016', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-05'::date, NULL, 'Genel ziyaret yapıldı Ali Bey ile görüşme gerçekleştrildi. 16 adet sailun binek ve 4 adet sailun 235/75r17.5 satışı gerçekleştirildi. Kampanya listeleri paylaşıldı. Bilgi dönüşü yapacaklar. Kış lastiği stoğu 80 adet civarı bir stok kaldığını belirtti. Brisa binek grubunda genelde Tevekkelden alım yapıyor.', '{"kis_stok": "80 adet", "bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bilgi": "Hüseyin Bilgi ile TBR''de çalışmakta.", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Laufen", "Pirelli", "Sailun"], "rakipler": ["Tevekkel"], "marka_listesi": ["Lassa", "Laufenn", "Pirelli", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'd0a74274-6204-48e6-869a-264d77812995', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-05'::date, NULL, 'Genel ziyaret yapıldı ve Ömür Bey ile tahsilat konusunda görüşüldü. Bakiyeyi 33.000₺ ye kadar düşürdük. Haftaya yine çekimler yapıp bakiyenin kapatılacağını belirtti. Bakiye kapatıldıktan sonra talep olursa sadece peşin çalışılacak.', '{"bolge": "Düzce", "nokta_durumu": "Riskli Nokta", "raf_markalari": ["Laufenn"], "marka_listesi": ["Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '713ed189-85b8-4a88-80f8-fb3f7903f860', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-05'::date, NULL, 'Genel ziyaret yapıldı ve Volkan bey ile görüşme gerçekleştirildi. Daha önceden Eren Hacıoğlu''ndan şubeden lastik talepleri olan bir noktaydı. Toptana çevirerek ben iletişime geçmeye başladım. İhtiyaca göre alım yapmakta.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Petlas", "Goodyear", "Sailun", "Dayton"], "marka_listesi": ["Dayton", "Goodyear", "Petlas", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '744153f9-e23f-4807-9209-40ce1086c642', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-05'::date, NULL, 'Genel ziyaret yapıldı, Erhan Bey ve Barış Beyler ile görüşme gerçekleştirildi. Pasif bir noktaydı tekrar hareketlendirme sağladık. Conti ve sailun satışlarının haricinde brisa grubunda da satışlar gerçekleştirmeye başladık.Kampanya listeleri de paylaşıldı. İnceleyip dönüş sağlayacakar.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bayilikler": ["Dunlop"], "raf_markalari": ["Lassa", "Falken", "Dunlop", "Bridgestone", "starmaxx", "michelin", "Continental"], "marka_listesi": ["Bridgestone", "Continental", "Dunlop", "Falken", "Lassa", "Michelin", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3a68fec8-6c5e-4d9b-b6ff-1e14fba69283', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-05'::date, NULL, 'Genel ziyaret yapıldı ve Mehmet Bey ile görüşme gerçekleştirildi. Yeni oluşturduğumuz bir nokta. Tanışmamızdan sonra brisa grubu ürünlerinden 58.000₺ satış ve tahsilat gerçekleştirmiştik. Daha sonra tekrar conti grubundan 52.000₺ tutarında bir satış gerçekleştirmiştik. Kampanya listeleri paylaşıldı. İncleyip dönüş yapacaklar. Kış lastiği stoğunun parası ödenmiş 1400 adet olduğunu söyledi.', '{"kis_stok": "1400 adet", "bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Multibrand çalışan bir petlas bayisi. Hankook ağırlıkta çalışıyor.", "bayilikler": ["Petlas"], "raf_markalari": ["Pirelli", "Hankook", "Laufenn", "Petlas", "Lassa", "Goodyear", "Milestone"], "rakipler": ["Bar Oto", "YUKE", "Mutaflar", "USPA", "Rota", "Yeslas", "Sevtar"], "marka_listesi": ["Goodyear", "Hankook", "Lassa", "Laufenn", "Milestone", "Petlas", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'fa4c6130-34e9-4899-b16c-321f2e37b14e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-05'::date, NULL, 'Genel ziyaret yapıldı, Serdar Bey ile görüşme gerçekleştirildi. Kampanya listeleri paylaşıldı. Düzcedeki tek Michelin bayisi. B2b aktif olarak takip ediyor genelde conti grubunda çalışıyoruz. Yakın zamanda dayton markasında da satışlar gerçekleştirdik. Ayrıca geçen hafta 16.9-28 ve 16.70-20 satışı da yaptık. Sailun özelinde de görüşme gerçekleştirdik kormoran markasında tedarik sıkıntısı yaşadığını ve ucuz segmentte dayton tercih ettiğini belirtti. Denemek için 4 adet 175/70r13 sailun siparişi verdi. Sailun kış listesini de ayrıca paylaştım. Kış lastiği stoğunun 6 takım olduğunu belirtti. Kış lastiğinde çalışırken teminatlı bir şekilde çalışacağız. DBS, Teminat Mektubu veya çek olacak. Özellikle sevkiyat hızımızdan çok memnun olduğunu belirtti. Bu sebeple continental grubunda artık başka arayışta olmadığını da belirtti.', '{"kis_stok": "24 adet", "bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Kormoran", "Nexen", "Continental"], "rakipler": ["Uspa", "Keskin", "YUKE", "Bar Oto"], "marka_listesi": ["Continental", "Kormoran", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4a4b2b54-82c0-4d5e-bd06-6cb0f192b4ff', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-05'::date, NULL, 'Genel ziyaret yapıldı, Muhammet Bey ile görüşme gerçekleştirildi. Geçen ay toplu lastik satışı gerçekleştirmiştik. Tüm tahsilatı tamamladık. Sailun listeleri paylaşıldı. Muhtemelen yakın tarihte sailun siparişi de yazacağız.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Petlas", "Pirelli", "Dayton", "Starmaxx", "Laufenn"], "marka_listesi": ["Dayton", "Laufenn", "Petlas", "Pirelli", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '7444b468-38cd-465a-8a4d-8136710e78f3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-05'::date, NULL, 'Genel ziyaret yapıldı, Abdurrahman Bey ile görüşme gerçekleştirildi. Yeni bir dükkan ve düşük riskle devam ettiğimiz bir nokta. Geçtiğimiz ay 20 adet 37.000₺  tutarında 30 gün vadeli sailun satışı gerçekleştirmiştik. 9.000₺ tutarında tahsilatı da gerçekleştirdik. Vadesinin yaklaştığının ttutarının bilgisi de verildi. Kış lastiği stoğu sıfır.', '{"kis_stok": "0 adet", "bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Lassa", "Dayton", "Petlas"], "marka_listesi": ["Dayton", "Lassa", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
