INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c494f542-1d55-4508-b09f-2d67609b80b9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-08'::date, NULL, 'Genel ziyaret yapıldı, Nihat Bey ile görüşme gerçekleştirildi. Gecikmiş bakiyesini hafta sonu kapattık. 4 adet 225/40R18 Bridgestone satışı gerçekleştirdik. Genelde sipariş üzerine çalışıyoruz. Diğer tedarikçilerle de bu şekilde çalışıyor. Stok seviyeleri çok az.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Hankook"], "raf_markalari": ["Lassa", "Petlas", "michelin", "dayton", "bridgestone", "laufenn", "continental"], "rakipler": ["YUKE", "Mollaoğlu", "Keskin", "Çakıroğlu"], "marka_listesi": ["Bridgestone", "Continental", "Dayton", "Lassa", "Laufenn", "Michelin", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
