INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'a0fdf9d4-482b-4ba5-8f12-d60d4ce2a334', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-08'::date, NULL, 'Genel ziyaret yapıldı, Doğan Bey ile görüşme gerçekleştirildi. Genelde sipariş üzeri çalışıyoruz.  Özellikle conti grubunda aktif şekilde çalışıyoruz. Contide bizden başka bir yerden alım yapmıyor.', '{"bolge": "İzmit", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastik Park"], "raf_markalari": ["Lassa", "Bridgestone", "Seatta", "Continental"], "rakipler": ["YUKE", "Tatko"], "marka_listesi": ["Bridgestone", "Continental", "Lassa", "Seatta"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '0e640f01-dd18-492c-b659-4550c9d2390a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-08'::date, NULL, 'Genel ziyaret ve Erhan Bey ile görüşme gerçekleştirildi. Conti grubunda çalışıyoruz. 4 adet 205/55r16 conti mutlaka rafında bulunduruyor, sattıkça yerine yenisini bizden tedarik ediyor. Brisa grubunda da b2b''den takiplerini yapıyor telefon ile mutlaka bilgi alıyor.  Yeni oluşturduğumuz bir nokta.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Her Lastik"], "raf_markalari": ["Optimo", "Riken", "Petlas", "Hankook", "Kumho", "Waterfall", "Sentury", "Unique"], "rakipler": ["Tatko", "YUKE"], "marka_listesi": ["Hankook", "Kumho", "Optimo", "Petlas", "Riken", "Sentury", "Unique", "Waterfall"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c5e29a5c-91b6-483d-9358-4d551a4d7c40', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-08'::date, NULL, 'Genel ziyaret yapıldı, Sezer Bey yerinde olmadığı için görüşme gerçekleştirilemedi. Gecikmiş baakiyesi ile ilgili geçen hafta görüşme sağlamıştık. En geç 12 haziran tarihinde tüm bakiye kapanacak.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bayilikler": ["LastikJantAVM"], "raf_markalari": ["Lassa", "Kormoran", "Hankook"], "rakipler": ["Keskin", "Uspa"], "marka_listesi": ["Hankook", "Kormoran", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f87f9a89-bfbb-456f-8a45-3ba9faea18a9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-08'::date, NULL, 'Genel ziyaret yapıldı. Eski personelimiz Beytullah Eşiyok''un işletmesi. Beytullah Bey ile görüşme sağlandı. Daha önceden cari mevcut fakat etkin değil statüsünde. İstişare ettikten sonra B2b aktifleştirip çalışmayı düşünüyorum.', '{"bolge": "İzmit", "nokta_durumu": "Pasif Nokta", "rakipler": ["Yuke", "Tatko", "Haskar"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '66837193-fbbd-4c77-9bc1-944471661299', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-09'::date, NULL, 'Genel ziyaret yapıldı, Ali Bey ile görüşme gerçekleştirildi. Gerek telefon gerek ziyaretlerimizle  mayıs ayı içerisinde 4 adet 17 jant lastik satışı ve tahsilatını gerçekleştirmiştik. 4-8 sattığımız bir nokta.', '{"bolge": "Derince", "nokta_durumu": "Pasif Nokta", "raf_markalari": ["Goodyear", "Montreal", "Seha"], "marka_listesi": ["Goodyear", "Montreal", "Seha"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4437b39c-0cf0-453b-897a-a8ab59eef39c', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-09'::date, NULL, 'Genel ziyaret gerçekleştirildi. Zeliha Hanım ile görüşme sağlandı. İşlerin bu hafta çok durgun başladığını belirtti. 4-8 sattığımız bir nokta. B2b aktif şekilde takip ediyor.', '{"bolge": "Derince", "nokta_durumu": "Pasif Nokta", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin"], "marka_listesi": ["Michelin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1fa9033d-6707-431b-9a97-ca91a4b88544', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-09'::date, NULL, 'Genel ziyaret yapıldı, Bekir Bey ile görüşme gerçekleştirildi. Kampanya listeleri paylaşılmıştı. Pakete girmeyecek muhtemelen ama inceleyip dönüş yapacaklar. +1 puan daha destek vereceğimizi belirttim. 8 adet 185/65R15 Sailun, 2 Adet 215/75R17.5 LSR siparişi aldık. Contide +5 kampanyasını hemen bildirdim ve 24 adet 205/55R16 Conti siparişi de aldık. Diğer ürünlerin de bilgilendirmesi ve sipariş için tekrar ziyaret sağlayacağım', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["LastikPark"], "raf_markalari": ["Lassa", "Bridgestone", "Hankook", "Continental", "Matador", "Starmaxx", "Laufenn"], "rakipler": ["Lastikpark"], "marka_listesi": ["Bridgestone", "Continental", "Hankook", "Lassa", "Laufenn", "Matador", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '790106e4-d8dc-45b8-baf4-daec192e7678', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-09'::date, NULL, 'Genel ziyaret yapıldı, Cüneyt Bey ile görüşme gerçekleştilrildi. 5 adet 205/60r16 conti sipariş aldık. +5 kampanya bilgilendirme ve sipariş için tekrar ziyaret sağlayacağım.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastikpark"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bd01899f-c2a4-4837-8f83-d6e9f318df36', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-09'::date, NULL, 'Genel ziyaret yapıldı, Emre Bey ile görüşme gerçekleştirildi. Düzene soktuğumuz bir nokta haline geldi diyebilirim. Dün akşam 4 adet 205/55r16 conti siparişi almıştık. 2 adet daha bugün sipariş verdi. +5 kampanyası ile minimum 12 adet stok için ürün alacağını düşünüyorum. Tekrar ziyaret sağlayacağım.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Hankook", "Goodyear", "Starmaxx", "Petlas", "Lassa", "Kumho", "Kormoran", "Delinte"], "rakipler": ["Mollaoğlu", "YUKE", "Tatko"], "marka_listesi": ["Delinte", "Goodyear", "Hankook", "Kormoran", "Kumho", "Lassa", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f8ca1d05-f918-4205-919f-817804633db8', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-09'::date, NULL, 'Genel ziyaret yapıldı, Erhan Bey ile görüşme gerçekleştirildi. Stok ve sipariş için biraz daha beklemek istediğini belirtti. Piyasa koşullarının çok kötü olduğundan dolayı hem fırsat beklediğini hem de tedirgin olduğunu belirtti. +5 için tekrar ziyaret sağlayacağım.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "rakipler": ["Ayko", "YUKE", "Mutaf", "Keskin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '8ddc5191-0153-40f9-8768-c35ee3bdb1f9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-09'::date, NULL, 'Genel ziyaret yapıldı, Harun Bey ile görüme gerçekleştildi. B2b takip etmekte ve ara ara telefonla da ürün soruyor. B2b ve cari açmıştık fakat henüz lastik satışı gerçekleştiremedik. Kampanya ile satış yapabileceğimizi düşünüyorum.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bilgi": "Yol yardım hizmeti de vermekte. Biraz spotçu mantığı ile çalışıyor.", "raf_markalari": ["Pirelli", "Michelin", "Kormoran", "Laufenn", "Hankook", "Lassa"], "marka_listesi": ["Hankook", "Kormoran", "Lassa", "Laufenn", "Michelin", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4d0fb43f-1d8f-4e06-8414-9b36b4e80f9e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-09'::date, NULL, 'Genel ziyaret yapıldı ve Ufuk Bey ile görüşme gerçekleştirildi. Geçen ay gerçekleştirdiğimiz 40 adet 67.600₺ tutarında sailun satışımızın vadesi bu hafta doldu. Vade dolmadan 16.000₺ kk çekmiştik. Bu hafta sonuna kadar kalan 51.600₺ bakiyesi kapatılacak', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastik Fix"], "raf_markalari": ["Goodyear", "Pirelli", "Dayton", "Delinte"], "marka_listesi": ["Dayton", "Delinte", "Goodyear", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '8a75e9a6-bf2d-495c-8e99-e16f5043e58a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-09'::date, NULL, 'Genel ziyaret yapıldı ve Mehmet Ali Bey ile görüşme gerçekleştrildi. Daha önceki ziyaretlerimizde cari ve b2b açılışı sağlamıştık. Henüz lastik satışı gerçekleştiremedik. Önceki ziyaretlerimizde firmamız ve ürün gamımız hakkında bilgilendirme sağlamıştık.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastik Ustam"], "raf_markalari": ["Hankook", "Michelin", "Laufenn", "Seatta", "Lassa", "Sentury"], "marka_listesi": ["Hankook", "Lassa", "Laufenn", "Michelin", "Seatta", "Sentury"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'da9686fc-18ae-49fe-a9ae-71d2673ff8c3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-09'::date, NULL, 'Genel ziyaret ve Metin Bey ile görüşme gerçekleştirildi. 4-8 çalıştığmız bir nokta. Dayton, Lassa, Conti satışları gerçekleştirmiştik.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
