INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '04d811ab-2331-4608-980c-9419ddb52391', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-17'::date, NULL, 'Sakayar Traktörcüler sitesi içerisinde yer alan bir nokta. Genel ziyaret yapıldı, İhsan Bey ile görüşme gerçekleştirildi. Pasif bir noktaydı, B2b takip ediyor. Bu hafta içerisinde 4 adet kampanyalı ürünlerden satış gerçekleştirmiştik. Toplu kampanya listesi de paylaşıldı.', '{"bolge": "Sakarya", "nokta_durumu": "Pasif Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
