INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '2fbeab14-d49b-4104-bb72-71858f11e56b', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-17'::date, NULL, 'Genel ziyaret gerçekleştirildi. Turgay Bey ile görüşme sağlandı. Mayıs ayı içerisinde sailun ve eski dotlu ürün satışları gerçekleştirmiştik. B2b aktif şekilde takip ediyor. Vadenin haftaya dolacağı ile ilgili bilgi verdim. Vade gelmeden 50.000₺ ödeme yapılacak. Daha sonra kampanyalı ürünlerle ilgili dönüş sağlayacaklar.', '{"bolge": "Sakarya", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Petlas", "Sailun"], "rakipler": ["Erenler", "Mutaf"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa", "Petlas", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '31b27d8e-1a85-4b45-aaa7-5e916f48311d', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-17'::date, NULL, 'Genel ziyaret yapıldı, Rami Bey yerinde olmadığı için görülme gerçekleştirilemedi.', '{"bolge": "Sakarya", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas"], "marka_listesi": ["Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
