INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '520e6e90-1fec-435c-8fb6-a05e067fd371', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-17'::date, NULL, 'Genel ziyaret yapıldı,  Hamza Bey ile görüşüldü, +5''li kampaya listeleri paylaşıldı, Geçen hafta 12 adet 205/55r16 matador ürün satışı gerçekleştirmiştik. (8 adet kampanyasız, 4 adet kampanyalı)', '{"bolge": "Sakarya", "nokta_durumu": "Eski Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '61142a4f-0b15-47e0-a6af-575d0bf7aea3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-17'::date, NULL, 'Genel ziyaret gerçekleştirildi. Eski dotlu ve performans grubunda çalışıyoruz.  Jant satışları daha ağırlıkta olan bir nokta. Pasif bir şekilde çalışıyoruz. +5 li ürün listeleri ile ilgili bilgi dönüşü yapacaklar.', '{"bolge": "Sakarya", "nokta_durumu": "Pasif Nokta", "bayilikler": ["Express Lastik"], "raf_markalari": ["Nexen"], "marka_listesi": ["Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '51ffe505-a039-439b-945f-6335297051b8', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-17'::date, NULL, 'Genel ziyaret yapıldı, Tümay Bey ile görüşme gerçekleştirildi. Adapazarı girişinde yer alan Michelin Bayii. İşlerin çok durgun olduğunu belirtti. Uzun bir süredir de bu şekilde devam ettiğini söyledi. Daha önceki ziyaretlerimizde b2b aktifleştirmiştik.', '{"bolge": "Sakarya", "nokta_durumu": "Pasif Nokta", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Kumho", "Nexen"], "marka_listesi": ["Kumho", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '914713c0-9b0e-4f0d-8303-37a9028c20f1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-17'::date, NULL, 'Genel ziyaret yapıldı, Ümitin babası Mehmet Bey ile görüşme ve tanışma gerçekleştirildi. İşi tamamen kendisinin devraldığını belirtti. 105.000₺ bakiyemiz kaldı. Haftaya 40.000₺ nakit ve 40.000₺ KK çekeceğini belirtti.', '{"bolge": "Sakarya", "nokta_durumu": "Riskli Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bfd6fca3-b120-4a14-9b61-27710a0f16b2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-18'::date, NULL, 'Genel ziyaret yapıldı, Burak Bey ile görüşme gerçekleştirildi. +5''li kampanya listeleri paylaşıldı. Genel bir conti ve sailun sipairşi çalışıp gönderecek.', '{"bolge": "Gebze", "nokta_durumu": "Eski Nokta", "bayilikler": ["Her Lastik"], "raf_markalari": ["Uniroyal", "Michelin", "Continental"], "marka_listesi": ["Continental", "Michelin", "Uniroyal"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '85a8a360-5acf-4caf-881c-0ee3bc2dad6a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-18'::date, NULL, 'Genel ziyaret yapıldı, Gürkan ve Gökmen Beyler ile görüşüldül. +5''li kampanya listeleri paylaşıldı, inceleyip dönüş yapacaklar.', '{"bolge": "Gebze", "nokta_durumu": "Eski Nokta", "bayilikler": ["LastikVS"], "raf_markalari": ["Kumho", "Goodyear", "Lassa", "Laufenn", "Hankook", "Continental"], "rakipler": ["Ayko", "YUKE", "Mutaf", "Keskin", "Mollaoğlu", "Lastikpark"], "marka_listesi": ["Continental", "Goodyear", "Hankook", "Kumho", "Lassa", "Laufenn"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1fa9033d-6707-431b-9a97-ca91a4b88544', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-18'::date, NULL, 'Genel ziyaret yapıldı, Bekir Bey ile görüşme gerçekleştirildi. Geçen hafta kampanyalı ürünlerden satış gerçekleştirmiştik.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta", "bayilikler": ["LastikPark"], "raf_markalari": ["Lassa", "Bridgestone", "Hankook", "Continental", "Matador", "Starmaxx", "Laufenn"], "rakipler": ["Lastikpark"], "marka_listesi": ["Bridgestone", "Continental", "Hankook", "Lassa", "Laufenn", "Matador", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '373ecc09-9880-4a43-8571-d6087784537f', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-18'::date, NULL, 'Genel ziyaret yapıldı, Hakan Bey ile görüşme gerçekleştirildi. Kampanyaşı ürünlerden geçen hafta satış gerçekleştirmiştik. Bugün de kampanyalı ürünlerden 8, diğer conti ürünlerinden 2 adeti eski dot olmak üzere 8 adet, toplamda 16 adet sipariş aldık.', '{"bolge": "Körfez", "nokta_durumu": "Eski Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3beece18-2947-4eb5-8580-5b3ee5ac8016', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-19'::date, NULL, 'Genel ziyaret yapıldı, kampanya listleri paylaşıldı. İnceleyip dönüş yapacak. Yavaş yavaş kış hazırlığına başlayacağını bu nedenle çok fazla yaz stoğu taşımak istemediğini belritti. Geçtiğimiz hafta 17.5 sailun ve binek sailun satışı gerçekleştirmiştik.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Laufen", "Pirelli", "Sailun"], "rakipler": ["Tevekkel"], "marka_listesi": ["Lassa", "Laufenn", "Pirelli", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'fa4c6130-34e9-4899-b16c-321f2e37b14e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-19'::date, NULL, 'Genel ziyaret yapıldı, Serdar Bey ile görüşme gerçekleştirildi. Kampanya listeleri paylaşıldı. Düzcedeki tek Michelin bayisi. Kış lastiği ile ilgili de görüşme sağladık. Muhtemelen bu noktadan ön sipariş alacağız. Müşteri Çeki, Firma çeki veya DBS olacak şekilde bir çalışma gerçekleştireceğiz. Mevcut bakiyenin de vadesi gelmeden kredi kartı veya çok yakın tarihli müşteri çeki verip bakiyeyi kısa sürede kapatacağız.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Kormoran", "Nexen", "Continental"], "rakipler": ["Uspa", "Keskin", "YUKE", "Bar Oto"], "marka_listesi": ["Continental", "Kormoran", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '744153f9-e23f-4807-9209-40ce1086c642', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-19'::date, NULL, 'Genel ziyaret yapıldı, Emre Bey ve Barış Bey ile görüşme gerçekleştirildi. Kampanya listeleri paylaşıldı. Düzcedeki Dunlup Bayiisi. İnceleyip dönüş sağlayacaklar. Pasif bir noktaydı tekrar hareketledirme sağladık.', '{"bolge": "Düzce", "nokta_durumu": "Eski Nokta", "bayilikler": ["Dunlop"], "raf_markalari": ["Lassa", "Falken", "Dunlop", "Bridgestone", "starmaxx", "michelin", "Continental"], "marka_listesi": ["Bridgestone", "Continental", "Dunlop", "Falken", "Lassa", "Michelin", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '3a68fec8-6c5e-4d9b-b6ff-1e14fba69283', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-19'::date, NULL, 'Genel ziyaret yapıldı ve Mehmet Bey ile görüşme gerçekleştirildi. Yeni oluşturduğumuz bir nokt. Kampanya listeleri paylaşıldı. İncleyip dönüş yapacaklar. Stoğunda bulunan 1400 kış lastiği mevcut. Yaklaşık 2000 adet daha kış lastiği alacağını belirtti. Buradan da ön sipariş almayı planlıyorum.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Multibrand çalışan bir petlas bayisi. Hankook ağırlıkta çalışıyor.", "bayilikler": ["Petlas"], "raf_markalari": ["Pirelli", "Hankook", "Laufenn", "Petlas", "Lassa", "Goodyear", "Milestone"], "rakipler": ["Bar Oto", "YUKE", "Mutaflar", "USPA", "Rota", "Yeslas", "Sevtar"], "marka_listesi": ["Goodyear", "Hankook", "Lassa", "Laufenn", "Milestone", "Petlas", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '07cb245c-c6c3-4eb9-9b11-0b62d5247e04', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-19'::date, NULL, 'Genel ziyaret yapıldı, Ümit Bey ile görüşme gerçekeltirildi. Sanayi sitesi içerisinde yer alan Petlas Bayii. Kampanya listeleri paylaşıldı. İşlerin genel olarak düşüşte olduğunu belirtti.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas", "Dayton", "Starmaxx"], "marka_listesi": ["Dayton", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b8a0d908-8e54-48e1-bf28-48846ff981ab', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-06-19'::date, NULL, 'Genel ziyaret yapıldı, Ayhan Bey ile görüşüldü. daha önceden cari ve b2b açılışı sağlamıştık. +5''li kampanya listeleri paylaşıldı. Henüz satış gerçekleştiremedik.', '{"bolge": "Düzce", "nokta_durumu": "Yeni Nokta", "bilgi": "Lastiğim noktası ve ticari lastik de yapmakta. Aynı zamanda yedek parça servis hizmeti de vermekte", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Goodyear", "Dayton", "Bridgestone", "Prometeon"], "marka_listesi": ["Bridgestone", "Dayton", "Goodyear", "Lassa", "Prometeon"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
