INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'da9686fc-18ae-49fe-a9ae-71d2673ff8c3', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-07'::date, NULL, 'Genel ziyaret yapıldı, Metin Bey ile görüşme gerçekleştirildi. Vadesi bugün dolan bakiye ile ilgili bilgi aktarımı sağlandı. 09.07.2026 tarihinde tüm bakiye kapatılacak.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'f8ca1d05-f918-4205-919f-817804633db8', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-07'::date, NULL, 'Genel ziyaret yapıldı, Erhan Bey ile görüşme gerçekleştirildi. 4 adet eski dotlu 22 jant conti ve 16 adet sailun siparişi alındı. Vadesi dolan 10.300₺ bakiye muhtemelen yarın kapatılacak.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "rakipler": ["Ayko", "YUKE", "Mutaf", "Keskin"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'bd01899f-c2a4-4837-8f83-d6e9f318df36', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-07'::date, NULL, 'Genel ziyaret yapıldı, Emre Bey ile görüşme gerçekleştirildi. 4 adet 17 jant conti sipairşi havale koşulu ile sipariş alındı ve tahsilatı gerçekleştirildi.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Hankook", "Goodyear", "Starmaxx", "Petlas", "Lassa", "Kumho", "Kormoran", "Delinte"], "rakipler": ["Mollaoğlu", "YUKE", "Tatko"], "marka_listesi": ["Delinte", "Goodyear", "Hankook", "Kormoran", "Kumho", "Lassa", "Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '4d0fb43f-1d8f-4e06-8414-9b36b4e80f9e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-07'::date, NULL, 'Genel ziyaret yapıldı, Ufuk Bey ile görüşme gerçekleştirildi. Gecikmiş bakiye ile ilgili görüşüldü, en geç 15.07.2026 tarihinde kesinlikle kapama yapılacak. Bizden aldığı ürünleri bir filoya satmış olduğunu ve filodan ödeme alamadığı için aksama yaşandığını belirtti.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastik Fix"], "raf_markalari": ["Goodyear", "Pirelli", "Dayton", "Delinte"], "marka_listesi": ["Dayton", "Delinte", "Goodyear", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '8ddc5191-0153-40f9-8768-c35ee3bdb1f9', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-07'::date, NULL, 'Genel ziyaret yapıldı, Harun Bey ile görüşme gerçekleştirildi. 06.07.2026 tarihinde 18 jant conti satışı gerçekleştirildi. Bugün de havalesi alınarak bakiye kapatıldı. Düzenli ziyaretlerimiz sayesinde 2.satışımızı da gerçekleştirdik. Fiyatlarımızdan, ilgimizden ve sevkiyatlarımızdan memnun olduğunu belirtti.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Pirelli", "Michelin", "Kormoran", "Laufenn", "Hankook", "Lassa"], "marka_listesi": ["Hankook", "Kormoran", "Lassa", "Laufenn", "Michelin", "Pirelli"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '5055ca10-4a65-4430-931d-ca277ec65f0e', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-07'::date, NULL, 'Genel ziyaret yapıldı, Ahmet Bey ile görüşme gerçekleştirildi. Sailun ağırlıkta çalıştığımız bir nokta.', '{"bolge": "Yeşilova", "nokta_durumu": "Yeni Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '52dfd932-453a-420e-8206-bec3a12a7bb2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-07'::date, NULL, 'Genel ziyaret yapıldı, Hakan Bey ile görüşme gerçekleştirildi. Kış lastiği ile ilgili koşullarımızı beklediğini belirtti. Düzenli ve aktif bir şekilde çalıştığımız bir nokta.  200-300 adetlik bir sailun çalışması yapılacak. Haftaya bu konu ile ilgili dönüş yapacaklar. Kış sailunları da erkenden alabilirler.', '{"bolge": "Yeşilova", "nokta_durumu": "Eski Nokta", "raf_markalari": ["Lassa", "bridgestone", "Continental", "kumho", "laufen", "michelin", "nexen."], "rakipler": ["Ayko", "Sevtar", "YUKE", "Çakıroğlu", "Konlas", "Mutaflar"], "marka_listesi": ["Bridgestone", "Continental", "Kumho", "Lassa", "Laufenn", "Michelin", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '04dd7ad9-5f41-46b1-9b3e-27f056dc9fad', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-08'::date, NULL, 'Genel ziyaret yapıldı. İsmail Bey ve Mustafa Bey yerinde olmadığı için görüşme gerçekleştirilemedi. Conti grubunda satışlar gerçekleştirdiğimiz bir nokta aynı zamanda brisa grubunda da çalışıyoruz. Bugün de telefon ile ziyaret bilgilendirmesi sağlandıktan sonra 2 adet 185/65R14 T005 satışı gerçekleştirdik.', '{"bolge": "Karamürsel", "nokta_durumu": "Pasif Nokta", "satis": {"adet": "2 adet", "marka": "Bridgestone"}, "bayilikler": ["Petlas"], "raf_markalari": ["Petlas", "Starmaxx"], "marka_listesi": ["Petlas", "Starmaxx"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '9c0f291b-4d31-41e4-a7de-a9a87f77892a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-08'::date, NULL, 'Genel ziyaret yapıldı, Naim Bey ile görüşme gerçekleştirildi. Aktif bir şekilde çalıştığımız bir nokta haline geldi. 4 adet 235/65R16 kampanyalı ürün satışı gerçekleştirdik.', '{"bolge": "Karamürsel", "nokta_durumu": "Eski Nokta", "satis": {"adet": "4 adet", "marka": "Lassa"}, "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Dayton"], "marka_listesi": ["Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c5c24fed-6bdf-4497-a35e-c1d1f0a0100b', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-08'::date, NULL, 'Genel ziyaret yapıldı, Fatih Bey ile görüşme gerçekleştirildi. B2b aktifleştirmiştik ve kontroller sağlıyorlar. Ağırlıkta TBR çalışan bir nokta. Kaplama ile ilgili fiyat istedi. Yıldıray Bey''den destek alındı. Aynı zamanda Yıldıray Bey''de TBR grubunda görüşüyüor.', '{"bolge": "Gölcük", "nokta_durumu": "Eski Nokta"}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'cdef76b5-ac68-405b-8349-5d376948b34a', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-08'::date, NULL, 'Genel ziyaret yapıldı, yetkili Raif Bey istanbulda olduğu için görüşme gerçekleştirilemedi. Eğer çalışma gerçekleştirirsek para içeri mal dışarı modeli ile çalışacağız.', '{"bolge": "Gölcük", "nokta_durumu": "Yeni Nokta", "bilgi": "pazardan aldığım bilgilere göre piyasaya çok fazla borcu varmış. Özellikle ana tedarikçisi YUKE''ye çok fazla borcunun olduğu bilgisine ulaştım", "raf_markalari": ["Nexenn", "Goodyear", "Leao"], "marka_listesi": ["Goodyear", "Leao", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'fe37315a-4eb2-49a7-8e7c-6b65bfa5f581', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-08'::date, NULL, 'Genel ziyaret yapıldı, Abdurrahman Bey ile görüşme gerçekleştirildi. B2b takip ediyorlar. Henüz satış gerçekleştiremediğimiz bir nokta. Düzenli ziyaretler ile buraya da satış yapacağımızı planlıyorum.', '{"bolge": "Gölcük", "nokta_durumu": "Yeni Nokta", "bayilikler": ["LastikPark"], "raf_markalari": ["Unique", "Delinte", "Lassa", "Bridgestone", "Seatta"], "rakipler": ["Tatko"], "marka_listesi": ["Bridgestone", "Delinte", "Lassa", "Seatta", "Unique"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '9c92e94f-977e-46cd-b28f-1a6f852329d1', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-08'::date, NULL, 'Genel ziyaret yapıldı, Yusuf Bey ile görüşme gerçekleştirildi. Kampanyalı ürünlerden satışlar gerçekleştirmiştik. Onun haricinde matador ve sailun satışları da gerçekleştiriyoruz. Yavaş yavaş havaleli modele geçiyoruz. Vadeler dolmadan kart çekimlerini yapıyor. 4 adet sailun siparişi de aldık.', '{"bolge": "Gölcük", "nokta_durumu": "Yeni Nokta", "satis": {"adet": "4 adet", "marka": "Sailun"}, "raf_markalari": ["Nexenn", "Hankook", "Laufenn"], "rakipler": ["Yuke", "Mutaf"], "marka_listesi": ["Hankook", "Laufenn", "Nexen"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
