INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'cca828fd-efd1-48ff-aaa9-db7dcf14c077', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-08'::date, NULL, 'Genel ziyaret yapıldı, Alperen Bey ile görüşme ve tanışma gerçekleştirildi. Gölcük yolu üzerinde Goodyear bayii. İşin asıl sahibi Birol bey şehir dışında olduğu için bir sonraki rutta tanışma ve görüşme gerçekleştireceğiz.', '{"bolge": "Gölcük", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Goodyear"], "raf_markalari": ["Goodyear", "Sava", "Lassa"], "rakipler": ["Bar Oto"], "marka_listesi": ["Goodyear", "Lassa", "Sava"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '9d7e363b-e906-4b64-9911-6a06799c7a7b', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-08'::date, NULL, 'Genel ziyaret yapıldı, Mustafa Bey  ve Altay Bey ile görüşme gerçekleştirildi. İhtyaca göre alım yapan bir nokta. Ziyaretlerimiz sonrası 4 adet conti satışı gerçekleştirmiştik.', '{"bolge": "Gölcük", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Michelin"], "raf_markalari": ["Michelin", "Goodyear", "Kormoran", "Taurus"], "rakipler": ["Uspa", "Keskin", "Ayko", "Çakıroğlu"], "marka_listesi": ["Goodyear", "Kormoran", "Michelin", "Taurus"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c5e29a5c-91b6-483d-9358-4d551a4d7c40', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-08'::date, NULL, 'Genel ziyaret yapıldı, Sezer Bey ile görüşüldü. 6.000₺''lik bir vadesi geçen bakiye mevcut onunla ilgili bilgilendirme yapıldı, yarın kapaması yapılacak. İhtiyaca göre alım yapan bir nokta.', '{"bolge": "İzmit", "nokta_durumu": "Yeni Nokta", "bayilikler": ["LastikJantAVM"], "raf_markalari": ["Lassa", "Kormoran", "Hankook"], "rakipler": ["Keskin", "Uspa"], "marka_listesi": ["Hankook", "Kormoran", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '136a2967-6cfa-4ad7-b8f7-674668ea1813', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-09'::date, NULL, 'Genel ziyaret yapıldı, Yakup Bey ile görüşme gerçekleştirildi. 17.5 grubunda çalışmalar gerçekleştirdik. Matador C grubu kışlıkları ile ilgili desen gösterildi ve bilgilendirme sağlandı.', '{"bolge": "Kandıra", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton", "Özka"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'cdd26764-ae69-4f95-983d-76d40596b3d0', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-09'::date, NULL, 'Genel ziyaret yapıldı ve Nafiz Bey ile görüşme gerçekleştirildi. B2b uzun süredir takip etmiyordu. B2b tekrar aktifleştirildi ve ürün gamımız ile ilgili detaylı bilgi aktarımı sağlandı.', '{"bolge": "Kandıra", "nokta_durumu": "Eski Nokta", "bayilikler": ["Petlas"], "raf_markalari": ["Petlas", "Milestone", "Lassa"], "marka_listesi": ["Lassa", "Milestone", "Petlas"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
