INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '61689ce1-f2ac-43b1-97bf-e64828139429', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-09'::date, NULL, 'Genel ziyaret yapıldı, Ali Bey ile görüşme gerçekleştilridi. Henüz satış yapamadığımız, cari ve b2b açamadığımız bir nokta.', '{"bolge": "Kaynarca", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Her Lastik"], "raf_markalari": ["Goodyear", "Kumho", "Taurus"], "marka_listesi": ["Goodyear", "Kumho", "Taurus"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'c0536bdc-737e-4a79-a1bb-464ad91dfd37', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-09'::date, NULL, 'Genel ziyaret yapıldı, Fevzi Bey yerinde olmadığı için görüşme gerçekleştirilemedi.  Daha önceden de ziyaret sağlamış ve kartvizit bırakmıştık. Cari ve b2b açılışı henüz yapılamadı.', '{"bolge": "Kaynarca", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastiğim"], "raf_markalari": ["Lassa", "Bridgestone", "Dayton"], "rakipler": ["Albayrak", "Erenler"], "marka_listesi": ["Bridgestone", "Dayton", "Lassa"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '571df243-f880-4dd2-ad6b-3acbef2726b8', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-09'::date, NULL, 'Genel ziyaret yapıldı, İbrahim Bey ile görüşme gerçekleştirildi. 22 adet sailun satışı gerçekleştirildi. Kış lastiğinde alım koşullarınının çok avantajlı olmasından sebep ağırlıkta nexenn sipariş vereceğini belirtti. Bizden de sailun kış alımı gerçekleştirecekler.', '{"bolge": "Karasu", "nokta_durumu": "Eski Nokta", "satis": {"adet": "22 adet", "marka": "Sailun"}, "bayilikler": ["Lastikpark"], "raf_markalari": ["Nexen", "Hankook", "Continental", "Starmaxx", "Milestone", "Petlas", "Sailun", "Michelin", "Laufenn", "Riken", "Unique"], "rakipler": ["YUKE", "Çakıroğlu", "Tatko", "Haskar", "Yedi Oto"], "marka_listesi": ["Continental", "Hankook", "Laufenn", "Michelin", "Milestone", "Nexen", "Petlas", "Riken", "Sailun", "Starmaxx", "Unique"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'a3f243c5-f57b-468c-a46d-dec783618133', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-09'::date, NULL, 'Genel ziyaret gerçekleştirildi Orhan Bey yerinde olmadığı için görüşme gerçekleştirilemedi. Telefon ile ziyaret bilgilendirmesi yapıldı, en geç ayın 15''ine kadar gecikmiş bakiyeyi kapatacaklar.', '{"bolge": "Karasu", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Lastik Evi"], "raf_markalari": ["Continental", "Matador", "Sailun", "Dayton", "Laufenn", "Lassa", "Hankook"], "marka_listesi": ["Continental", "Dayton", "Hankook", "Lassa", "Laufenn", "Matador", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', 'b2069b68-b4b7-45dc-90b6-4d8f8e4faff2', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-09'::date, NULL, 'Genel ziyaret yapıldı, Yasin Bey ile görüşme gerçekleştirildi. Karasu sanayi girişinde yer alan güzel bir nokta. Henüz herhangi bir çalışma gerçekleştiremedik. Düzenli ziyaretlerle çalışmaya başlayacğaımızı düşünüyorum. Erenler ile çalışmakta.', '{"bolge": "Karasu", "nokta_durumu": "Yeni Nokta", "raf_markalari": ["Continental", "Uniroyal", "Pirelli", "Goodyear", "Kumho", "Michelin", "Leao"], "rakipler": ["Erenler"], "marka_listesi": ["Continental", "Goodyear", "Kumho", "Leao", "Michelin", "Pirelli", "Uniroyal"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '45fd034d-bad4-4ba8-8039-702e59dafd50', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-09'::date, NULL, 'Genel ziyaret gerçekleştirildi. Hasan Bey ile görüşme sağlandı. Daha önceden conti satışları gerçekleştirmiştik. Stok kontrolleri sonrası conti grubunda sipariş verecekler. (185/65r15, 205/55r16 ebatlarında)', '{"bolge": "Karasu", "nokta_durumu": "Yeni Nokta", "bayilikler": ["Goodyear"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
INSERT INTO saha_ziyaret (id, tenant_id, musteri_id, rep_id, rep_adi, tip, durum, ziyaret_tarihi, katilimci, notlar, detay, kaynak, created_by) VALUES (gen_random_uuid(), 'f8a5d20f-ecf8-4ce2-a492-69268fbb03fa', '1077dfc0-ad46-465b-97ae-93f7a93a3804', 'ae0c55f9-68cc-421d-96d9-409222452f1a', 'Eftal Yıldız', 'TUKETICI', 'TAMAMLANDI', '2026-07-09'::date, NULL, 'Genel ziyaret gerçekleştirildi. İlhan Bey ile görüşme sağlandı. Geçen ay sailun satışları gerçekleştirmiştik. Tekrar sailun siparişi verecek. Ayrıca Kış koşullarımızı bekliyor.', '{"bolge": "Geyve", "nokta_durumu": "Eski Nokta", "bayilikler": ["Lastikvs"], "raf_markalari": ["Lassa", "Bridgestone", "Continental", "Petlas", "Sailun"], "rakipler": ["YediOto", "Bayraktar"], "marka_listesi": ["Bridgestone", "Continental", "Lassa", "Petlas", "Sailun"]}'::jsonb, 'EXCEL_MIGRASYON', 'ae0c55f9-68cc-421d-96d9-409222452f1a');
